window.CG_QUIZ=[{"cat": "A", "ep": "A-1 做游戏不是玩游戏", "u": "A/01-jlFkxfkICO8.html", "vid": "jlFkxfkICO8", "q": "被问「为什么做游戏」，樱井的回答是什么？「喜欢游戏」处于什么位置？", "a": "「因为这是我最擅长的工作。」「喜欢游戏/喜欢做游戏」的优先级比这更低。只要涉及金钱，做游戏就必须当作工作，独立开发者收了钱也是专业人士。", "t": 16}, {"cat": "A", "ep": "A-1 做游戏不是玩游戏", "u": "A/01-jlFkxfkICO8.html", "vid": "jlFkxfkICO8", "q": "樱井举了哪两个例子说明自己不按个人喜好立项？", "a": "常玩游戏的他做了面向新手的《星之卡比》；不擅长下落式拼图的他做了《Meteos》。他把被指定的类型当作「课题」来解决。", "t": 146}, {"cat": "A", "ep": "A-1 做游戏不是玩游戏", "u": "A/01-jlFkxfkICO8.html", "vid": "jlFkxfkICO8", "q": "做各种类型游戏的开发者，共同的终极目标是什么？", "a": "让玩家开心。遇到困难、迷失方向时，就回想这一点，把「让玩的人享受」当作行动的动力。", "t": 207}, {"cat": "A", "ep": "A-2 演示讲究速度！", "u": "A/02-nkNSNGJvFXk.html", "vid": "nkNSNGJvFXk", "q": "樱井的演示「秘诀」是什么？", "a": "演示就是速度：削掉赘肉，只传达必要的内容。", "t": 21}, {"cat": "A", "ep": "A-2 演示讲究速度！", "u": "A/02-nkNSNGJvFXk.html", "vid": "nkNSNGJvFXk", "q": "演示讲究速度，是否意味着演示必须很短？", "a": "不是。不一定要短，关键是在给定时间内讲得多密、节奏多快。", "t": 41}, {"cat": "A", "ep": "A-2 演示讲究速度！", "u": "A/02-nkNSNGJvFXk.html", "vid": "nkNSNGJvFXk", "q": "演示中关于配图，樱井怎么说？", "a": "需要配图，但要简洁。", "t": 37}, {"cat": "A", "ep": "A-3 你打算去跟玩家解释吗？", "u": "A/03-Ik3deWOVCHI.html", "vid": "Ik3deWOVCHI", "q": "当规格书「对开发方便、对玩家不友好」时，樱井常说的那句话是什么？", "a": "「你打算挨个去跟玩家解释这些情况吗？」", "t": 44}, {"cat": "A", "ep": "A-3 你打算去跟玩家解释吗？", "u": "A/03-Ik3deWOVCHI.html", "vid": "Ik3deWOVCHI", "q": "为什么开发者容易忘掉玩家视角？", "a": "开发者自己也是玩家，本应知道玩的时候会怎么想；但站到制作方后，需要克服的障碍很多（如难以实现、人手不够），意识就会离开玩家视角。", "t": 71}, {"cat": "A", "ep": "A-3 你打算去跟玩家解释吗？", "u": "A/03-Ik3deWOVCHI.html", "vid": "Ik3deWOVCHI", "q": "觉得规格对玩家不友好时，应该怎么做？", "a": "考虑有没有别的办法，不只和策划、也和程序员商量，在理想与技术之间取得最理想的平衡；「方便」最该优先给的对象是玩家/顾客。", "t": 117}, {"cat": "A", "ep": "A-4 规格变更", "u": "A/04-bzWibA7izF8.html", "vid": "bzWibA7izF8", "q": "为什么规格变更应尽量避免，又无法完全避免？", "a": "避免：已做的东西可能白费、开发绕远、增加成本、打击士气。无法避免：不实际做出来就有发现不了的问题；想用文档预先写尽一切，工作量可能堪比做一整款游戏；换了程序员等实现也不同；进度原因也常要改。", "t": 9}, {"cat": "A", "ep": "A-4 规格变更", "u": "A/04-bzWibA7izF8.html", "vid": "bzWibA7izF8", "q": "开发成员发现规格有问题时应该怎么做？团队如何决定？", "a": "立刻告诉别人（事后说「早就觉得」毫无帮助，人人适用）。利用集体智慧把能想到的手段都摆上桌，从短期和长期两方面考虑，选出当下最优解。", "t": 157}, {"cat": "A", "ep": "A-4 规格变更", "u": "A/04-bzWibA7izF8.html", "vid": "bzWibA7izF8", "q": "樱井自己面对课题时怎么做决定？需要什么？", "a": "不花时间，通常当场立刻下结论；但判断需要信息，信息越不准确越容易出错，所以希望把已知情况全部听到。为「该怎么商量」拖延也是损失，商量越早损失越小。", "t": 204}, {"cat": "A", "ep": "A-5 企划书的写法", "u": "A/05-2Iiu1k16Ukc.html", "vid": "2Iiu1k16Ukc", "q": "樱井的企划书每页长什么样？总页数多少？", "a": "用 PowerPoint，几乎每页「1 张图/照片 + 2 行文字」，1 页 1 个说明项；《大乱斗 SPECIAL》的企划书超过 200 页。", "t": 33}, {"cat": "A", "ep": "A-5 企划书的写法", "u": "A/05-2Iiu1k16Ukc.html", "vid": "2Iiu1k16Ukc", "q": "为什么页数多也没关系？", "a": "读起来像翻漫画一样快，演示也不花太多时间；关键在于好懂、有趣、内容妥当，能快速听完一场有密度的演示，与页数无关。", "t": 80}, {"cat": "A", "ep": "A-5 企划书的写法", "u": "A/05-2Iiu1k16Ukc.html", "vid": "2Iiu1k16Ukc", "q": "演示企划书时，樱井反对什么做法？", "a": "在画面上放长长一段文字然后照着念——观众会先读完，让人烦躁。如果这么做，请改掉。", "t": 125}, {"cat": "A", "ep": "A-6 企划书要趁热、要快", "u": "A/06-1cFrEoiziDA.html", "vid": "1cFrEoiziDA", "q": "根据本期，企划书里哪些东西「不需要」？", "a": "冗长罗列的企划意图、图表、调研和 Plan B——有不有趣才是一切。", "t": 49}, {"cat": "A", "ep": "A-6 企划书要趁热、要快", "u": "A/06-1cFrEoiziDA.html", "vid": "1cFrEoiziDA", "q": "为什么要趁热写企划书？", "a": "趁着想做这个企划的热情高时一口气写出来，别小看这股势头；拖久了新鲜度就会下降。", "t": 77}, {"cat": "A", "ep": "A-6 企划书要趁热、要快", "u": "A/06-1cFrEoiziDA.html", "vid": "1cFrEoiziDA", "q": "樱井举《怪物猎人》想说明什么？企划没通过时应该怎么想？", "a": "企划层面它就是「狩猎怪物、用素材做装备」，并无新意，实际游戏的优点在纸面上只能体现一部分——乐趣很大程度来自打磨。企划没通过时别认为对方没眼光，传达魅力的责任在企划者自己。", "t": 99}, {"cat": "A", "ep": "A-7 辛苦会忘，作品会留！", "u": "A/07-MPSFfqxpVJk.html", "vid": "MPSFfqxpVJk", "q": "樱井认为辛苦为什么会有回报？", "a": "只要很多人玩，辛苦就有回报：1,000 人玩，效果就是辛苦的 1,000 倍，1 万人就是 1 万倍——这与卖得多不多无关。", "t": 41}, {"cat": "A", "ep": "A-7 辛苦会忘，作品会留！", "u": "A/07-MPSFfqxpVJk.html", "vid": "MPSFfqxpVJk", "q": "樱井至今忘不了的作品失误是什么？", "a": "《星之卡比 梦之泉物语》结局的某一刻，不该用画面震动，而应该用画面闪白。", "t": 104}, {"cat": "A", "ep": "A-7 辛苦会忘，作品会留！", "u": "A/07-MPSFfqxpVJk.html", "vid": "MPSFfqxpVJk", "q": "这期是在鼓励吃苦吗？", "a": "不是。不是说要吃无谓的苦，而是在最大限度提高效率的前提下努力为用户服务，想着回报尚未谋面的买家，尽可能不留遗憾。", "t": 158}, {"cat": "A", "ep": "A-8 总监要有个性", "u": "A/08-WXBS7hk0B7k.html", "vid": "WXBS7hk0B7k", "q": "樱井认为能干的总监硬要说有什么共同点？", "a": "对某种感觉很敏锐，看到的东西和别人不同：不放过细微之处，能感受到与他人不同的东西。", "t": 38}, {"cat": "A", "ep": "A-8 总监要有个性", "u": "A/08-WXBS7hk0B7k.html", "vid": "WXBS7hk0B7k", "q": "「总监稍微有点怪是好事」——樱井补充了什么以免误解？", "a": "也需要一定的平衡感，大概也需要从自身发出的强有力的输出（表达能力）；完全不擅长与人对话的总监不太常见。", "t": 87}, {"cat": "A", "ep": "A-8 总监要有个性", "u": "A/08-WXBS7hk0B7k.html", "vid": "WXBS7hk0B7k", "q": "本期的结论是什么？", "a": "做出与众不同游戏的总监，像游戏本身一样，被要求的是个性和只有这个人才有的东西——总监需要有个性。", "t": 116}, {"cat": "A", "ep": "A-9 总之，现在就做！", "u": "A/09-IN-Uh2VfL8c.html", "vid": "IN-Uh2VfL8c", "q": "樱井给出的「唯一、最大的解决办法」是什么？", "a": "总之，去做：要写就现在写，要画就一直画，要出门就马上收拾出门——就当不马上做房间就会爆炸。", "t": 25}, {"cat": "A", "ep": "A-9 总之，现在就做！", "u": "A/09-IN-Uh2VfL8c.html", "vid": "IN-Uh2VfL8c", "q": "没干劲时，深想原因有用吗？", "a": "没有意义。总之动手，干劲会随后跟来。", "t": 64}, {"cat": "A", "ep": "A-9 总之，现在就做！", "u": "A/09-IN-Uh2VfL8c.html", "vid": "IN-Uh2VfL8c", "q": "樱井认为锻炼自己、接近成功靠的是什么？", "a": "压倒性地靠出手次数——输出少就没有成功；意义之类的以后再想。", "t": 82}, {"cat": "A", "ep": "A-10 我是如何坚持写专栏的", "u": "A/10-ff7HadWHTJo.html", "vid": "ff7HadWHTJo", "q": "樱井的专栏连载了多久、多少回？在哪本杂志？", "a": "《周刊 Fami 通》，18 年 9 个月，共 640 回。", "t": 12}, {"cat": "A", "ep": "A-10 我是如何坚持写专栏的", "u": "A/10-ff7HadWHTJo.html", "vid": "ff7HadWHTJo", "q": "专栏能坚持的三个理由是什么？", "a": "①输出：作为总监，传达东西不觉得苦；②不花太多时间：每次约 1 小时；③不太在意：不背负「必须写」「很多人在看」的使命感，随意地写。", "t": 90}, {"cat": "A", "ep": "A-10 我是如何坚持写专栏的", "u": "A/10-ff7HadWHTJo.html", "vid": "ff7HadWHTJo", "q": "樱井是如何获得这个专栏连载的？", "a": "在 MMORPG《最终幻想 XI》中偶然与当时 Fami 通编辑部的专栏负责人组队相识（现实中没见过面），被邀请给 Fami 通写专栏。", "t": 213}, {"cat": "A", "ep": "A-11 不要依赖「Plan B」", "u": "A/11-QgkLrqGrwy4.html", "vid": "QgkLrqGrwy4", "q": "樱井为什么反对在企划书里写「A 也行、B 也行」？他建议怎么做？", "a": "那是把决定交给别人。应该综合考虑后选出自己认为最好的一个方法写进去，其他提议之后再接受。", "t": 40}, {"cat": "A", "ep": "A-11 不要依赖「Plan B」", "u": "A/11-QgkLrqGrwy4.html", "vid": "QgkLrqGrwy4", "q": "写了「理想规格」之后，如何应对成本或实现上的问题？", "a": "以理想规格为基础，为了性价比做轨道修正；出现问题时由团队一起研究解决方案，企划者要倾听团队的提议。", "t": 61}, {"cat": "A", "ep": "A-11 不要依赖「Plan B」", "u": "A/11-QgkLrqGrwy4.html", "vid": "QgkLrqGrwy4", "q": "如果最后还是回到了 B 案，那坚持 Plan A 还有什么意义？", "a": "重要的是企划者从一开始就负起责任、想透后给出一个方案，并一直这样做；这也有助于积累经验。", "t": 87}, {"cat": "A", "ep": "A-12 分岔的口味", "u": "A/12-50Khnf80P7M.html", "vid": "50Khnf80P7M", "q": "樱井用什么比喻说明玩家价值观的变化？年轻层位于哪里？", "a": "一棵树：人在成长中因经历、文化背景、相遇等让价值观不断分岔，越往枝头越细；年轻层位于尚未分岔、最粗的树干部分。", "t": 130}, {"cat": "A", "ep": "A-12 分岔的口味", "u": "A/12-50Khnf80P7M.html", "vid": "50Khnf80P7M", "q": "樱井认为任天堂（尤其畅销作）卖得好的一大原因是什么？他说这期的重点是这个吗？", "a": "他认为一大原因是在年轻层中大受欢迎（而不是硬件技术最尖端）。但他强调本期并不是在解释任天堂为何畅销——原因还有很多。", "t": 120}, {"cat": "A", "ep": "A-12 分岔的口味", "u": "A/12-50Khnf80P7M.html", "vid": "50Khnf80P7M", "q": "「枝头」的市场有什么特点？那是否应该所有游戏都瞄准树干？", "a": "枝头是小众（niche）市场，也可能是更狂热（hardcore）的市场，只有那里的人才能尽情享受。所以并不是说大家都该瞄准树干，而是要有意识地做目标定位。", "t": 215}, {"cat": "A", "ep": "A-13 多输入，多输出", "u": "A/13-VGsxpvJ4IfM.html", "vid": "VGsxpvJ4IfM", "q": "樱井的「输入」习惯有哪些具体做法？", "a": "大量玩游戏和看影像作品；比起一直玩一款，更想接触更多作品；但以通关为目标，以把握当今游戏的规模感，做出不输于它们的东西。", "t": 25}, {"cat": "A", "ep": "A-13 多输入，多输出", "u": "A/13-VGsxpvJ4IfM.html", "vid": "VGsxpvJ4IfM", "q": "樱井举了哪些「输出」的例子？", "a": "在《周刊 Fami 通》连载专栏 18 年 9 个月；开发现场的日报（信息分享和杂谈）；Twitter 上的「今日一图」（基于开发中的截图，原本是给团队内部做的）；以及这个 YouTube 节目。", "t": 61}, {"cat": "A", "ep": "A-13 多输入，多输出", "u": "A/13-VGsxpvJ4IfM.html", "vid": "VGsxpvJ4IfM", "q": "是否每个人都必须靠玩大量游戏来输入？", "a": "不必。输入的形式因人而异，不用勉强玩游戏；看同样的东西也能感受、反刍，就已经大不一样。重要的是不要让输入左耳进右耳出。", "t": 109}, {"cat": "A", "ep": "A-14 把内压保持在高位", "u": "A/14-UVnLW47cpFk.html", "vid": "UVnLW47cpFk", "q": "樱井说的「内压」是什么意思？为什么跟人聊企划会破坏它？", "a": "像气球/压力锅里往外顶的压力。规格要在脑子里加压、把力挤出来；跟人一说就会满足，等于泄压，点子的力会散掉。", "t": 27}, {"cat": "A", "ep": "A-14 把内压保持在高位", "u": "A/14-UVnLW47cpFk.html", "vid": "UVnLW47cpFk", "q": "脑暴和找人咨询都不反对，那写企划书时他建议怎么做？", "a": "企划书需要「想做」的热量。自己谁也不说、憋着写完的规格书，通常比脑暴后再被派去整理的更烫手；真要咨询，先写完再谈。", "t": 109}, {"cat": "A", "ep": "A-14 把内压保持在高位", "u": "A/14-UVnLW47cpFk.html", "vid": "UVnLW47cpFk", "q": "关于 SNS，他额外提醒了什么？写的时候还可以做什么来加劲？", "a": "别把点子内容或工作进度发到 SNS 上泄压。先忍住、把内压养起来再砸进工作；写时想象对方看到时会怎么反应（做游戏时也一样，想象玩家的反应与感动点）。", "t": 153}, {"cat": "A", "ep": "A-15 不要什么都靠多数表决", "u": "A/15-dP94K69NSVc.html", "vid": "dP94K69NSVc", "q": "为什么樱井认为作品内容不该靠多数表决？举了什么例子？", "a": "多数表决选出的是最稳妥、即最平庸的东西；企划时多数人否定的规格做出来反而有趣的情况很常见。例子：《潜龙谍影 3》提出「受伤后治疗」的企划时，据说赞成的只有 4 人，而玩过成品的人都能理解治疗伤势的乐趣。", "t": 33}, {"cat": "A", "ep": "A-15 不要什么都靠多数表决", "u": "A/15-dP94K69NSVc.html", "vid": "dP94K69NSVc", "q": "由核心人物独断，有什么前提条件？", "a": "决策者要有良好的平衡感（否则会变成凭薄弱依据说不合理的话的独裁）；而且需要正确的信息——员工应把问题点和解决方案候选全部说出来，有隐瞒或看不见的东西，谁都会判断失误。", "t": 81}, {"cat": "A", "ep": "A-15 不要什么都靠多数表决", "u": "A/15-dP94K69NSVc.html", "vid": "dP94K69NSVc", "q": "樱井自己用过多数表决吗？结果如何？", "a": "偶尔当余兴用过：《大乱斗》中 Mii 格斗家女仆装的设计让员工投票，意见各种各样很有趣。他本来就觉得 A 或 B 好，最终产品采用了 A，并由总监判断把袜子改成白色——因为末端明度差别大，动作看得更清楚。", "t": 112}, {"cat": "A", "ep": "A-16 暗示的力量", "u": "A/16-QI39AHhZNcY.html", "vid": "QI39AHhZNcY", "q": "中学时赛跑总是倒数第一的樱井，是怎么突然拿到第一的？", "a": "在起跑线上给自己暗示：一个可怕的东西（3 米多高、满载碾碎用的齿和旋转装置的重型机械）从背后高速追来；起跑后拼命逃，结果冲过了终点线。", "t": 18}, {"cat": "A", "ep": "A-16 暗示的力量", "u": "A/16-QI39AHhZNcY.html", "vid": "QI39AHhZNcY", "q": "樱井认为哪种暗示更有效？在工作中如何应用？", "a": "与其设定一个要奔向的目标，不如想象有东西逼近、必须全力逃离，比如截止日期或终点。做工作时，「还剩几个小时必须结束」比「随时结束都行」更能真正做完。", "t": 77}, {"cat": "A", "ep": "A-16 暗示的力量", "u": "A/16-QI39AHhZNcY.html", "vid": "QI39AHhZNcY", "q": "他当年总是倒数第一时，是怎么跑的？", "a": "像在追自己的影子一样跑——他说那样不行。", "t": 109}, {"cat": "A", "ep": "A-17 坚守你的概念", "u": "A/17-2LvPC7bIywM.html", "vid": "2LvPC7bIywM", "q": "樱井所说的「概念」是什么？举了哪些例子？", "a": "决定游戏魅力方向的核心。例如：把对手打飞的快感；用立体的剧本结构讲深刻的故事；在笔直的道路上一路冲刺的爽快感。", "t": 28}, {"cat": "A", "ep": "A-17 坚守你的概念", "u": "A/17-2LvPC7bIywM.html", "vid": "2LvPC7bIywM", "q": "为什么不推荐中途改方向或频繁 scrap and build？", "a": "会迷失、越陷越深；而且可能浪费大量制作素材，例如美术或程序员几个月的成果被丢掉，既增加成本，也降低员工士气。", "t": 75}, {"cat": "A", "ep": "A-17 坚守你的概念", "u": "A/17-2LvPC7bIywM.html", "vid": "2LvPC7bIywM", "q": "樱井认为在什么条件满足之前不应推进项目？为什么总监必须看清方向？", "a": "至少在总监能随时清楚看到「灯塔」（概念）之前。因为新项目里员工往往要做出来才懂它的魅力，企划书也难以传达，所以总监要坚定朝最初方向前进，才能充分利用团队做出的资源。", "t": 110}, {"cat": "A", "ep": "A-18 竞争与丰富", "u": "A/18-fWWwELXIAEw.html", "vid": "fWWwELXIAEw", "q": "为什么樱井说「如果想放弃做游戏，可以放心地抽身」？", "a": "因为想做游戏的人非常多，就算少一个人，想做游戏的人依然多如山（他自己也是如此）。", "t": 37}, {"cat": "A", "ep": "A-18 竞争与丰富", "u": "A/18-fWWwELXIAEw.html", "vid": "fWWwELXIAEw", "q": "商业游戏面临的竞争有什么特点？", "a": "游戏大多很耗时间，所以是在争夺玩家的时间；而且不仅与最新作竞争，也与过去的作品竞争——订阅制服务里尤其必然。", "t": 57}, {"cat": "A", "ep": "A-18 竞争与丰富", "u": "A/18-fWWwELXIAEw.html", "vid": "fWWwELXIAEw", "q": "站在玩家的立场，竞争激烈意味着什么？樱井想让大家意识到什么？", "a": "意味着可以从海量作品中自由挑选只玩自己喜欢的。他希望大家意识到：有人辛苦做出的东西会让别人快乐，在竞争中也彼此支撑，才构成了有趣的世界。", "t": 154}, {"cat": "A", "ep": "A-19 说出口，就可能成真", "u": "A/19-sbEFYooj0Y8.html", "vid": "sbEFYooj0Y8", "q": "樱井说「说出口就可能成真」，他真正的意思是转运之类的玄学吗？", "a": "不是。他说那样讲会像玄学；真正想说的是：说过、想过的话会塑造自己的姿态（态度），看不见效果所以更不能小看。", "t": 73}, {"cat": "A", "ep": "A-19 说出口，就可能成真", "u": "A/19-sbEFYooj0Y8.html", "vid": "sbEFYooj0Y8", "q": "樱井如何看待负面想法？", "a": "负面想法并不坏，可以有。如果把它转成「要改善」的心情，例如「工作没意义→怎样把工作做得更好」「每天没意思→能不能做点不一样的事」，它会成为有具体方向的燃料，反而更有效。", "t": 87}, {"cat": "A", "ep": "A-19 说出口，就可能成真", "u": "A/19-sbEFYooj0Y8.html", "vid": "sbEFYooj0Y8", "q": "本期与哪一期的话题相通？结论是什么？", "a": "与之前「暗示的力量」（A-16）相通：动起来的人赢。哪怕只是嘴上说「去做！」，也会朝前进的方向动起来。", "t": 140}, {"cat": "A", "ep": "A-20 回声室效应", "u": "A/20-AuI0zoKIURY.html", "vid": "AuI0zoKIURY", "q": "在 SNS 语境中，「回声室」指什么现象？", "a": "发表意见后，赞同的人纷纷出现，于是自我强化「我是对的」；其实也有很多不同意或反对的人，但自己看到的世界一片赞同，变成封闭的世界，无法接受其他意见。", "t": 21}, {"cat": "A", "ep": "A-20 回声室效应", "u": "A/20-AuI0zoKIURY.html", "vid": "AuI0zoKIURY", "q": "樱井问观众「你觉得我想说什么」，用意是什么？", "a": "无论观众怎么理解，都会去找能认同的意见并产生共鸣；如果只吸收那种意见，就会形成回声室。他说自己这次只是平淡地陈述事实，并无其他意图。", "t": 83}, {"cat": "A", "ep": "A-20 回声室效应", "u": "A/20-AuI0zoKIURY.html", "vid": "AuI0zoKIURY", "q": "回声室会如何影响作品？樱井对「偏向」持什么态度？", "a": "无法客观看待，作品一定会失衡（变圆滑还是变尖锐不确定）。但游戏制作中大胆偏向某个方向也可能很有意思，比被人牵着走好；鲜明的个性有不可替代的力量。同时要听取员工指出的问题、灵活应对，最终取得平衡。", "t": 124}, {"cat": "A", "ep": "A-21 想不出点子的时候", "u": "A/21-kh0DhZGfaIY.html", "vid": "kh0DhZGfaIY", "q": "想不出点子时，樱井建议的第一步是什么？为什么它最关键？", "a": "先用简单的形式定义问题的主题（如「如何在某栋废弃建筑里灭火」）。因为从一无所有开始想就失去了抓手，想不出点子也理所当然。", "t": 33}, {"cat": "A", "ep": "A-21 想不出点子的时候", "u": "A/21-kh0DhZGfaIY.html", "vid": "kh0DhZGfaIY", "q": "在「灭火」例子中，樱井如何从失败的想法里找到线索？", "a": "逐个试错：水（附近没水）、隔绝空气（做不到）、沙子（没有）→「土也许行」；爆炸（波及太大）；盖桶（火不小）→「桶够大也许行」。不放过这些细小线索，继续深挖。", "t": 84}, {"cat": "A", "ep": "A-21 想不出点子的时候", "u": "A/21-kh0DhZGfaIY.html", "vid": "kh0DhZGfaIY", "q": "这种想点子的方法中，关于「质量和数量」的原则是什么？", "a": "不要停止联想，实现性低也先拿出来，拼数量；筛选（删掉）放在后面。至少能摆脱抱头想不出点子的状态，也能看到更好的改进方案。", "t": 93}, {"cat": "A", "ep": "A-22 千万别吵架", "u": "A/22-8kgrvdeLBR8.html", "vid": "8kgrvdeLBR8", "q": "为什么樱井强调「别和团队成员吵架 / 别把后事搞砸就走」？", "a": "行业比想象的窄。新工作或几年后无关项目里，常会再碰到前队友；结怨会跟着你。", "t": 58}, {"cat": "A", "ep": "A-22 千万别吵架", "u": "A/22-8kgrvdeLBR8.html", "vid": "8kgrvdeLBR8", "q": "别的导演问他对某位面试者的看法时，他怎么做？这对「别说坏话」说明了什么？", "a": "他从不说坏话，也会护着人；但回答有时仍会为难。说明业内口碑会流动，恶评容易回旋镖。", "t": 100}, {"cat": "A", "ep": "A-22 千万别吵架", "u": "A/22-8kgrvdeLBR8.html", "vid": "8kgrvdeLBR8", "q": "面对压力或不合拍的人，哪些可以、哪些不行？", "a": "可以：直说建设性意见；从不合拍处离开。不行：怀着「这人很差」去讨厌人——讨厌会回到自己头上。工作空气要自己造；别只盯着讨厌的人，而看不见撑着你的人。", "t": 125}, {"cat": "A", "ep": "A-23 上即是下，下即是上", "u": "A/23-r8ZZlnvNvBY.html", "vid": "r8ZZlnvNvBY", "q": "樱井认为总监/领导和员工是上下关系吗？", "a": "不是。领导只是处在请别人做事、把作品带到完成的位置，高度和其他员工一样；提议者没有他人协助什么也做不成。", "t": 22}, {"cat": "A", "ep": "A-23 上即是下，下即是上", "u": "A/23-r8ZZlnvNvBY.html", "vid": "r8ZZlnvNvBY", "q": "「上即是下，下即是上」用顾客与厂商的关系如何解释？", "a": "流通上顾客在下游，但在选择权和对价上是上游——不是厂商说「做好了来买」，而是顾客「买给」厂商，王是顾客。同理，指示从上往下，但实际是从下往上请员工工作。", "t": 64}, {"cat": "A", "ep": "A-23 上即是下，下即是上", "u": "A/23-r8ZZlnvNvBY.html", "vid": "r8ZZlnvNvBY", "q": "樱井在团队里如何称呼和对待成员？", "a": "基本都在名字后加「さん」，使用礼貌语，哪怕是年轻的新人；看到有人直呼新人名字会有点退缩。对外邮件则不会过分谦卑。", "t": 138}, {"cat": "B", "ep": "B-1 风险与回报", "u": "B/01-FXqEykD5Ub4.html", "vid": "FXqEykD5Ub4", "q": "樱井如何定义「游戏性」？它与「攻略」有何区别？", "a": "游戏性 = 博弈，即风险与回报：压低风险、获得回报的乐趣（系统一侧）；攻略 = 压低风险、获得回报的方法（玩家一侧）。两者立场不同，本质相同。", "t": 139}, {"cat": "B", "ep": "B-1 风险与回报", "u": "B/01-FXqEykD5Ub4.html", "vid": "FXqEykD5Ub4", "q": "在《太空侵略者》中，为什么「迎击」比「追击」好？", "a": "侵略者一直横移，光束的实际攻击范围是斜的；从右追上去时风险一样高却距离不够打不到，从左侧迎击则同等风险下能命中。", "t": 168}, {"cat": "B", "ep": "B-1 风险与回报", "u": "B/01-FXqEykD5Ub4.html", "vid": "FXqEykD5Ub4", "q": "「名古屋打法」为什么体现了最大风险与最大回报？", "a": "侵略者到底即游戏结束（最大风险），但临近底部时炮台不再被光束击中（风险骤降），一步之差就是侵略或无敌。", "t": 312}, {"cat": "B", "ep": "B-1 风险与回报", "u": "B/01-FXqEykD5Ub4.html", "vid": "FXqEykD5Ub4", "q": "樱井提醒了哪两点限制？", "a": "① 游戏性只是游戏乐趣的一个侧面，不是全部；② 游戏性越高，大众性越低（如初代《星之卡比》故意降低游戏性提高大众性）。", "t": 545}, {"cat": "B", "ep": "B-2 施压与释放", "u": "B/02-TYh5SJb5gWk.html", "vid": "TYh5SJb5gWk", "q": "为什么樱井说不该把压力「像杂草一样拔掉」？", "a": "压力本身虽不好玩，但游戏的乐趣恰恰来自施加压力再释放；没有压力，游戏就不会有趣。", "t": 52}, {"cat": "B", "ep": "B-2 施压与释放", "u": "B/02-TYh5SJb5gWk.html", "vid": "TYh5SJb5gWk", "q": "释放压力之后，应该给玩家什么样的回报？", "a": "能更有效地释放压力的回报：经验值/技能让人变强、金钱买更好的装备；能往前走也算回报，但有一些选择幅度游戏性更高。", "t": 84}, {"cat": "B", "ep": "B-2 施压与释放", "u": "B/02-TYh5SJb5gWk.html", "vid": "TYh5SJb5gWk", "q": "本期最后给出的建议是什么？", "a": "重新审视「施压→释放→变得能应对」的流程，别照搬其他游戏的常见做法，重新思考原本的意义，可能做出更新颖的游戏。", "t": 127}, {"cat": "B", "ep": "B-3 RPG 的游戏性", "u": "B/03-BFGkFHb2lBw.html", "vid": "BFGkFHb2lBw", "q": "RPG 探索中的风险与回报体现在哪里？", "a": "越深入敌人越强越可怕，但回报可能越大，于是会犹豫是否继续还是回安全的地方；倒下会失去更多战利品。", "t": 18}, {"cat": "B", "ep": "B-3 RPG 的游戏性", "u": "B/03-BFGkFHb2lBw.html", "vid": "BFGkFHb2lBw", "q": "可以随时回到安全地点的 RPG 就无法有紧张感吗？", "a": "不是。它更偏休闲，但只要提高单场战斗的失误率等，从整体上平衡，也能带来紧张刺激的体验。", "t": 50}, {"cat": "B", "ep": "B-3 RPG 的游戏性", "u": "B/03-BFGkFHb2lBw.html", "vid": "BFGkFHb2lBw", "q": "回合制战斗中的「攻略」是什么？樱井举了哪个系统例子？", "a": "根据外观判断、试探敌人，攻击弱点，用同样的战力打出更好的结果。例：《女神异闻录》攻击弱点能连续攻击，系统促使玩家去找弱点。", "t": 90}, {"cat": "B", "ep": "B-4 游戏性之外的乐趣", "u": "B/04-Dq7X8-lB0is.html", "vid": "Dq7X8-lB0is", "q": "为什么樱井说「游戏的乐趣 ≠ 游戏性」？", "a": "游戏性只是乐趣的一部分；有很多游戏类型主要靠游戏性以外的乐趣（操作、故事、版权世界、真实再现、建造、音游等）。", "t": 4}, {"cat": "B", "ep": "B-4 游戏性之外的乐趣", "u": "B/04-Dq7X8-lB0is.html", "vid": "Dq7X8-lB0is", "q": "影像/故事本身不是游戏性，它对游戏性有什么帮助？", "a": "「想继续往下看」的欲望会成为更努力面对风险的动力；充分展示角色和世界也能加深玩家的想象、提高对画面的代入感。", "t": 95}, {"cat": "B", "ep": "B-4 游戏性之外的乐趣", "u": "B/04-Dq7X8-lB0is.html", "vid": "Dq7X8-lB0is", "q": "为什么在音游里把判定做得「柔软」反而会无聊？", "a": "若离 PERFECT 越远就越平滑地变成 BAD，博弈（风险回报）就会降低，显得有些无聊；像 beatmania 那样稍晚就失败，才有博弈。", "t": 304}, {"cat": "B", "ep": "B-5 恶魔之釜", "u": "B/05-ai7pBxHAcvU.html", "vid": "ai7pBxHAcvU", "q": "恶魔之釜如何把难度选择变成风险与回报？", "a": "往釜里投入红心提高认真度：难度越高（敌人更凶、更强），通关得到的红心、神器、奇迹越多；失误会洒掉红心、降低难度。", "t": 34}, {"cat": "B", "ep": "B-5 恶魔之釜", "u": "B/05-ai7pBxHAcvU.html", "vid": "ai7pBxHAcvU", "q": "恶魔之釜作为难度调整有哪些优点？", "a": "失败自动降难度，很少卡关，也没有被直白询问「换简单模式吗」的屈辱；避免一直用 Easy 变得没有手感；降到 0.0 又能照顾跟不上的人。", "t": 112}, {"cat": "B", "ep": "B-5 恶魔之釜", "u": "B/05-ai7pBxHAcvU.html", "vid": "ai7pBxHAcvU", "q": "樱井反省了哪些问题？", "a": "手感太硬、不够休闲（地面关卡太大、敌人太密、不能原地复活，3DS 小屏幕更累）；「降低认真度就变简单」的告知不足，本该更好地照顾初学者。", "t": 156}, {"cat": "B", "ep": "B-6 让玩家「钻空子」", "u": "B/06-MVsVTgJKuzU.html", "vid": "MVsVTgJKuzU", "q": "樱井如何定义「攻略」？", "a": "玩家自己如何不吃亏地推进（少损失、多收益）；也包括在一处付出更大代价以换取别处更大收获的玩法。", "t": 3}, {"cat": "B", "ep": "B-6 让玩家「钻空子」", "u": "B/06-MVsVTgJKuzU.html", "vid": "MVsVTgJKuzU", "q": "为什么樱井认为不必把所有「平衡破坏点」都在调试中消除？", "a": "那些能单方面占便宜的地方（如《黑暗之魂》敌人自灭、DQ 刷金属史莱姆）往往最有趣、最令人难忘。", "t": 90}, {"cat": "B", "ep": "B-6 让玩家「钻空子」", "u": "B/06-MVsVTgJKuzU.html", "vid": "MVsVTgJKuzU", "q": "哪些作弊可以容许，哪些不行？", "a": "游戏内能做到的一定程度的作弊（如钻空子、重置挑战）最好容许；改写参数之类则免谈。", "t": 137}, {"cat": "B", "ep": "B-7 「会坠落」才卖得出飞翔感", "u": "B/07-j45EIuChfqs.html", "vid": "j45EIuChfqs", "q": "想表现「自由飞翔」的快感，樱井建议首先加入什么？", "a": "坠落的机制或惩罚（也可换成起飞需要某种准备）；即加入与飞翔相反的要素。", "t": 2}, {"cat": "B", "ep": "B-7 「会坠落」才卖得出飞翔感", "u": "B/07-j45EIuChfqs.html", "vid": "j45EIuChfqs", "q": "在《皇牌空战》里钻桥为什么让人觉得爽？", "a": "因为有风险（撞桥、撞水面都出局），成功穿越时有过关的实感。", "t": 49}, {"cat": "B", "ep": "B-7 「会坠落」才卖得出飞翔感", "u": "B/07-j45EIuChfqs.html", "vid": "j45EIuChfqs", "q": "为什么宇宙空间的飞行游戏更难做好？", "a": "没有能撞上的地面与地形，就不会产生那种紧张感；空战以地面和起伏为舞台更容易做好。", "t": 75}, {"cat": "B", "ep": "B-8 真的需要敌人吗？", "u": "B/08-atqS7SImuBc.html", "vid": "atqS7SImuBc", "q": "樱井把游戏的乐趣拆成哪四个阶段？", "a": "压力（障碍）→ 释放（排除）→ 成长（奖励/经验变强）→ 进展（更容易排除下一个障碍，往前推进）。", "t": 59}, {"cat": "B", "ep": "B-8 真的需要敌人吗？", "u": "B/08-atqS7SImuBc.html", "vid": "atqS7SImuBc", "q": "《Undertale》不打倒敌人也能通关，说明了什么？", "a": "敌人可以去掉，但压力仍要施加；不杀通关时无法直接排除，压力可能更大，释放时也格外痛快。", "t": 112}, {"cat": "B", "ep": "B-8 真的需要敌人吗？", "u": "B/08-atqS7SImuBc.html", "vid": "atqS7SImuBc", "q": "除了敌人，还有哪些东西能扮演「压力」？", "a": "冒险游戏中主角或朋友遭遇危机；支付成本（有支付，积攒才有趣）。", "t": 130}, {"cat": "B", "ep": "B-9 先想好回报", "u": "B/09-SpwQkNzNsXk.html", "vid": "SpwQkNzNsXk", "q": "为什么樱井说回报可以「最先考虑」？", "a": "回报是推动玩家继续玩的欲望之源；视类型而定，但搭好游戏骨架后就可以最先考虑。", "t": 40}, {"cat": "B", "ep": "B-9 先想好回报", "u": "B/09-SpwQkNzNsXk.html", "vid": "SpwQkNzNsXk", "q": "「会积攒的数值」型回报要注意什么？", "a": "它和消费是一套的：消费后得到的东西若没有魅力或不合适，就不是好回报。用素材表现时，做出的东西必要度要高。", "t": 54}, {"cat": "B", "ep": "B-9 先想好回报", "u": "B/09-SpwQkNzNsXk.html", "vid": "SpwQkNzNsXk", "q": "樱井用《大乱斗 SPECIAL》的什么来说明回报的重要？", "a": "命魂（Spirits）：如果不作为回报、一开始就全部齐备，就毫无喜悦可言。", "t": 128}, {"cat": "B", "ep": "B-10 对战游戏一定要复杂吗？", "u": "B/10-1ggw9xXbzig.html", "vid": "1ggw9xXbzig", "q": "樱井如何用一步步加规格说明对战游戏需要的复杂度？", "a": "只有一种拳：只能连打，无博弈；加走路有了间距；拳和踢有破绽差、打空会被反击才开始博弈；跳、防、投让游戏越来越深。", "t": 22}, {"cat": "B", "ep": "B-10 对战游戏一定要复杂吗？", "u": "B/10-1ggw9xXbzig.html", "vid": "1ggw9xXbzig", "q": "《街头霸王 II》为什么点燃了格斗游戏？", "a": "设定了扎实的博弈，并给众多招式恰当地分配角色，变得极其深奥（此前《街霸》招式虽多但太难出）。", "t": 150}, {"cat": "B", "ep": "B-10 对战游戏一定要复杂吗？", "u": "B/10-1ggw9xXbzig.html", "vid": "1ggw9xXbzig", "q": "樱井推荐开发者每次开发都做什么？", "a": "重新审视系统和规则，不把理所当然当作理所当然（例：《大乱斗》每作的跳跃规格都不同）。", "t": 200}, {"cat": "B", "ep": "B-11 落块解谜的游戏性", "u": "B/11-QOkY6BULsgo.html", "vid": "QOkY6BULsgo", "q": "五格骨牌和《俄罗斯方块》的根本区别是什么？", "a": "五格骨牌像拼图一样没有游戏性；《俄罗斯方块》有风险与回报（堆积是风险，消行降低风险）。", "t": 49}, {"cat": "B", "ep": "B-11 落块解谜的游戏性", "u": "B/11-QOkY6BULsgo.html", "vid": "QOkY6BULsgo", "q": "落块解谜中，为什么一次消多行更爽？", "a": "因为为了一次消多行，事先承担了更高的风险（堆得更高），风险越高、释放时越爽。", "t": 66}, {"cat": "B", "ep": "B-11 落块解谜的游戏性", "u": "B/11-QOkY6BULsgo.html", "vid": "QOkY6BULsgo", "q": "樱井为什么能在 5 分钟内想出《Meteos》的核心点子？", "a": "尽管不擅长落块解谜，他事先理解了这个类型的游戏性是如何产生的（风险与回报的原理）。", "t": 122}, {"cat": "B", "ep": "B-12 被打倒反而松了一口气？", "u": "B/12-vDEJ0sXw8Ks.html", "vid": "vDEJ0sXw8Ks", "q": "那项研究发现了什么出人意料的结果？", "a": "对战型 FPS 中，打倒对手时会感到不安，被对手打倒时反而松了一口气。", "t": 3}, {"cat": "B", "ep": "B-12 被打倒反而松了一口气？", "u": "B/12-vDEJ0sXw8Ks.html", "vid": "vDEJ0sXw8Ks", "q": "樱井列出的三个可能原因是什么？", "a": "①角色可能不是感情投入的对象；②规则（重开很快）冲淡了遗憾；③打倒对手本身不是回报，最终目的是获胜，还不能大意。", "t": 43}, {"cat": "B", "ep": "B-12 被打倒反而松了一口气？", "u": "B/12-vDEJ0sXw8Ks.html", "vid": "vDEJ0sXw8Ks", "q": "樱井认为什么是「最好的娱乐」？", "a": "打倒的一方和被打倒的一方都各自觉得好玩；输了不甘心但还想再来——对战不等于压制的快感。", "t": 98}, {"cat": "B", "ep": "B-13 登山不只是爬坡", "u": "B/13-Be6km65CuuM.html", "vid": "Be6km65CuuM", "q": "为什么自机强度与敌人强度不该成正比直线上升？", "a": "就像一直爬同样角度的坡：风景单调、休息点只是定期出现，毫无喜悦，变成「作业」。", "t": 33}, {"cat": "B", "ep": "B-13 登山不只是爬坡", "u": "B/13-Be6km65CuuM.html", "vid": "Be6km65CuuM", "q": "樱井推荐什么样的平衡？Boss 应怎样配置？", "a": "凹凸起伏：有必须越过的难关，也有平地。不是按「Boss 比周围强」的定式，而是放置需要认真攻略的困难，并给通关者相应回报；也要有空无一物的空间和能赚的地方。", "t": 61}, {"cat": "B", "ep": "B-13 登山不只是爬坡", "u": "B/13-Be6km65CuuM.html", "vid": "Be6km65CuuM", "q": "加入「敌人随玩家变强」的系统有什么问题？", "a": "刷级（赚经验/钱）会失去意义；解决时应尽量保留攻略的空间。", "t": 133}, {"cat": "B", "ep": "B-14 让重试快一点", "u": "B/14-oSi0wEJHLuA.html", "vid": "oSi0wEJHLuA", "q": "为什么失误后要尽快重开？", "a": "从失败到能再次操作之间，玩家会迅速冷却；尽快交还操作权能让玩家不放弃、再挑战，也提高对难度的容忍度。", "t": 53}, {"cat": "B", "ep": "B-14 让重试快一点", "u": "B/14-oSi0wEJHLuA.html", "vid": "oSi0wEJHLuA", "q": "樱井说关键是「能操作」，而不是什么？", "a": "不是游戏单纯动起来；要让玩家能操作（哪怕只是翻消息），越早有反应越好。", "t": 84}, {"cat": "B", "ep": "B-14 让重试快一点", "u": "B/14-oSi0wEJHLuA.html", "vid": "oSi0wEJHLuA", "q": "快速重开时要注意哪些分寸？", "a": "别让无限原地复活变成不用动脑；失败要用 1 秒～数秒的华丽演出明确表现；避免复活后立刻被敌人袭击。", "t": 102}, {"cat": "B", "ep": "B-15 你的游戏值得一再重来吗？", "u": "B/15-atHnu2fKtZA.html", "vid": "atHnu2fKtZA", "q": "为什么「失败就重来」适合独立游戏？", "a": "游戏本质上就要反复做相似的事，这种机制对资源做不多的独立游戏很方便。", "t": 112}, {"cat": "B", "ep": "B-15 你的游戏值得一再重来吗？", "u": "B/15-atHnu2fKtZA.html", "vid": "atHnu2fKtZA", "q": "玩家愿意一再重来，需要什么？", "a": "动机——主要是「想看后面」；为此游戏要展示对后面的期待、有魅力和足够的变化，难度也要照顾。", "t": 135}, {"cat": "B", "ep": "B-15 你的游戏值得一再重来吗？", "u": "B/15-atHnu2fKtZA.html", "vid": "atHnu2fKtZA", "q": "樱井提醒开发者在设定难度时别怎么做？", "a": "别因为别的游戏难、或熟练的自己勉强能过就决定；推进速度应由体量、展开和内容决定，尤其要设想玩家在同一处反复死亡的情况。", "t": 210}, {"cat": "B", "ep": "B-16 射击游戏的游戏性", "u": "B/16-iN3IyqPjLkc.html", "vid": "iN3IyqPjLkc", "q": "《Darius》怎样用「子弹少」产生博弈？", "a": "画面上能同时存在的子弹少：待在后方易断弹，靠前（靠近敌人和地形）连射更强；Boss 战中贴近才能大量命中、快速击倒。", "t": 49}, {"cat": "B", "ep": "B-16 射击游戏的游戏性", "u": "B/16-iN3IyqPjLkc.html", "vid": "iN3IyqPjLkc", "q": "在《Gradius》中，Double 与 Laser 的取舍是什么？", "a": "Double 更容易打上方的敌人，但只能单发、向前攻击远不如 Laser——承受哪个缺点换取哪个优点，就是游戏性。", "t": 105}, {"cat": "B", "ep": "B-16 射击游戏的游戏性", "u": "B/16-iN3IyqPjLkc.html", "vid": "iN3IyqPjLkc", "q": "能把画面上所有敌人都打倒，有什么问题？", "a": "很痛快，但难以产生博弈；不过游戏性高也不是一切。", "t": 123}, {"cat": "B", "ep": "B-17 游戏性越高，大众性越低", "u": "B/17-ML5wdEWpTuA.html", "vid": "ML5wdEWpTuA", "q": "初代《星之卡比》用哪些设计降低风险？", "a": "吸入能在风险变高前让敌人无效；体力制可挨 6 次；吐出攻击范围更广；随时能飞，避免掉坑一击死。", "t": 66}, {"cat": "B", "ep": "B-17 游戏性越高，大众性越低", "u": "B/17-ML5wdEWpTuA.html", "vid": "ML5wdEWpTuA", "q": "为什么说照顾初学者的卡比也有缺点？", "a": "风险与回报大致成正比：风险降低，回报（克服时的喜悦）也降低，游戏本身就没那么刺激有趣。", "t": 125}, {"cat": "B", "ep": "B-17 游戏性越高，大众性越低", "u": "B/17-ML5wdEWpTuA.html", "vid": "ML5wdEWpTuA", "q": "樱井对「目标人群」的结论是什么？", "a": "要大致意识目标；瞄准哪里取决于企划和概念，没有正解，应在理解游戏性原理的基础上决定。", "t": 208}, {"cat": "B", "ep": "B-18 升龙拳指令", "u": "B/18-zswiCPS5CSM.html", "vid": "zswiCPS5CSM", "q": "升龙拳指令的输入过程为什么本身就是风险？", "a": "前 = 靠近对手（向后才是防御）；下 = 无法防空；斜前下 = 哪里都防不住、也无法立刻蹲防——摇杆姿势上是最大危机，按键时才放出对空技。", "t": 72}, {"cat": "B", "ep": "B-18 升龙拳指令", "u": "B/18-zswiCPS5CSM.html", "vid": "zswiCPS5CSM", "q": "升龙拳哪些规格让「越吸引对手越有利」？", "a": "根部判定强、出招瞬间无敌能弹开各种攻击；离对手越近越易被反击，但逆转机会也越大。", "t": 150}, {"cat": "B", "ep": "B-18 升龙拳指令", "u": "B/18-zswiCPS5CSM.html", "vid": "zswiCPS5CSM", "q": "《大乱斗》为什么不让指令版升龙拳强得多？", "a": "若平衡离不开指令，会拉大会与不会的人的差距，对多数人太难；所以兼顾休闲性，只给指令版威力和无敌时间上的优待。", "t": 228}, {"cat": "B", "ep": "B-19 排行榜的利与弊", "u": "B/19-g7nC6NtTMIk.html", "vid": "g7nC6NtTMIk", "q": "排行榜有哪两大好处？", "a": "给人目标意识（努力成果与向上动机相连）；作为匹配时寻找实力相近者的指针。", "t": 4}, {"cat": "B", "ep": "B-19 排行榜的利与弊", "u": "B/19-g7nC6NtTMIk.html", "vid": "g7nC6NtTMIk", "q": "排行榜的主要坏处是什么？", "a": "夸张说是永远的屈辱感：不是第 1 就永远没达成，像一直在输；努力后还显示第 4001 名之类也提不起劲。", "t": 61}, {"cat": "B", "ep": "B-19 排行榜的利与弊", "u": "B/19-g7nC6NtTMIk.html", "vid": "g7nC6NtTMIk", "q": "「世界战斗力」与 VIP 房间分别解决了什么？", "a": "世界战斗力：以全球玩家数为分母的逆向排名，越高越好、不显示顶层、能自然排除作弊数据；VIP 房间：给上位者满足感，并防止他们流入低排名玩家中。", "t": 95}, {"cat": "B", "ep": "B-20 什么是「游戏（玩耍）」？", "u": "B/20-g5uooUqdXXs.html", "vid": "g5uooUqdXXs", "q": "凯卢瓦《游戏与人》中玩耍的四要素是什么？", "a": "Agon（竞争）、Alea（偶然）、Mimicry（模拟）、Ilinx（眩晕）。", "t": 40}, {"cat": "B", "ep": "B-20 什么是「游戏（玩耍）」？", "u": "B/20-g5uooUqdXXs.html", "vid": "g5uooUqdXXs", "q": "樱井说的「游戏性/博弈」主要对应哪个要素？", "a": "Agon（竞争）——不是单纯的体能优劣，而是关键一手决定胜负。", "t": 82}, {"cat": "B", "ep": "B-20 什么是「游戏（玩耍）」？", "u": "B/20-g5uooUqdXXs.html", "vid": "g5uooUqdXXs", "q": "樱井对「玩耍」的个人看法是什么？", "a": "玩耍像让人获得活力、过好生活的训练，带来身体、精神、智力等无形价值；有时也是疗愈；看似无意义的乐趣，是人像人一样生活的尝试。", "t": 155}, {"cat": "B", "ep": "B-21 版权游戏首先要忠于原作", "u": "B/21-EgUvH3YMVCM.html", "vid": "EgUvH3YMVCM", "q": "为什么樱井认为版权游戏不如普通游戏好玩是自然的？", "a": "原作是游戏设计的束缚：游戏与其他媒介的故事呈现方式差别大，难以兼顾；原作故事设定难改；沿原作的故事已被剧透。", "t": 40}, {"cat": "B", "ep": "B-21 版权游戏首先要忠于原作", "u": "B/21-EgUvH3YMVCM.html", "vid": "EgUvH3YMVCM", "q": "樱井举出的「原作设定成为游戏核心」的幸运例子是什么？", "a": "《女神转生》系列：原作小说中「用电脑召唤恶魔战斗」的设定与游戏极其契合；恶魔合体则是游戏独有的设定。", "t": 70}, {"cat": "B", "ep": "B-21 版权游戏首先要忠于原作", "u": "B/21-EgUvH3YMVCM.html", "vid": "EgUvH3YMVCM", "q": "版权游戏最被需要的是什么？", "a": "像原作、回应粉丝的喜爱，作为产品群的一种形态在合适时机推出；博弈和乐趣的优先级较低。", "t": 103}, {"cat": "B", "ep": "B-22 动作游戏的游戏性", "u": "B/22-EzwCc2_8OzU.html", "vid": "EzwCc2_8OzU", "q": "冲刺（跑）的风险与回报分别是什么？", "a": "回报：移动更快；风险：难控制、有破绽、消耗体力，可能冲进敌人或危险区。", "t": 64}, {"cat": "B", "ep": "B-22 动作游戏的游戏性", "u": "B/22-EzwCc2_8OzU.html", "vid": "EzwCc2_8OzU", "q": "「招架（Parry）」为什么好玩？", "a": "把攻击引到最后一刻，把极高的风险在千钧一发间变成回报。", "t": 121}, {"cat": "B", "ep": "B-22 动作游戏的游戏性", "u": "B/22-EzwCc2_8OzU.html", "vid": "EzwCc2_8OzU", "q": "「躲藏」的风险与回报是什么关系？", "a": "躲着时无法攻击：压低风险，回报也减少；等待对手接近本身也是承受风险。", "t": 132}, {"cat": "B", "ep": "B-23 让「工作」类游戏变好玩", "u": "B/23-4SFOO23m-bI.html", "vid": "4SFOO23m-bI", "q": "本期介绍的几款游戏有哪些共同点？", "a": "取材于现实世界、会赚到什么、让人默默地玩下去、偶尔有浪费时间的感觉。", "t": 81}, {"cat": "B", "ep": "B-23 让「工作」类游戏变好玩", "u": "B/23-4SFOO23m-bI.html", "vid": "4SFOO23m-bI", "q": "为什么「取材于现实」能让作业更有干劲？", "a": "它增加脑中的信息量；同样的作业，翻新或清洗更能感到在朝「完成的样子」前进。", "t": 93}, {"cat": "B", "ep": "B-23 让「工作」类游戏变好玩", "u": "B/23-4SFOO23m-bI.html", "vid": "4SFOO23m-bI", "q": "樱井认为这类游戏要做出乐趣，什么最重要？", "a": "工作、赚钱与强化（变强）的平衡；再加上玩法上的妙处最好。「赚钱」的循环是应该最先考虑的要素。", "t": 170}, {"cat": "B", "ep": "B-24 总比打不通关好", "u": "B/24-G3eacnEqdV0.html", "vid": "G3eacnEqdV0", "q": "为什么动作游戏比传统 RPG 更容易出现「打不通关」？", "a": "RPG 可以耐心升级获得胜算；动作游戏等没有靠强化逃离的退路，而玩家技术的成长到某个程度就撑不住。", "t": 35}, {"cat": "B", "ep": "B-24 总比打不通关好", "u": "B/24-G3eacnEqdV0.html", "vid": "G3eacnEqdV0", "q": "樱井如何看待「建议降难度」或「跳过关卡」？", "a": "屈辱感高、甚至损害根本乐趣，但都比通不了关好；不能中途调整、只能从头再来的游戏甚至可说设计有问题。", "t": 52}, {"cat": "B", "ep": "B-24 总比打不通关好", "u": "B/24-G3eacnEqdV0.html", "vid": "G3eacnEqdV0", "q": "樱井的结论是什么？", "a": "在不带屈辱感的范围内提供某种救济手段，例如能在游戏中途改变难度；无视亲切的硬核概念也可以，但别以为所有玩家都会跟上。", "t": 128}, {"cat": "B", "ep": "B-25 指定攻略与攻略平衡", "u": "B/25-U1b2OXdNcUY.html", "vid": "U1b2OXdNcUY", "q": "樱井个人为什么不太喜欢「固定攻略」？他认为它错了吗？", "a": "有强制感、像教程，他不想被游戏指挥这样那样；但他认为这也是游戏的正确形态之一（能感到用心，也是被多数人接受的秘诀）。", "t": 25}, {"cat": "B", "ep": "B-25 指定攻略与攻略平衡", "u": "B/25-U1b2OXdNcUY.html", "vid": "U1b2OXdNcUY", "q": "自由攻略（如《恶魔城》）的代价是什么？", "a": "与人为设计的攻略相比偏粗糙，不易产生博弈。", "t": 60}, {"cat": "B", "ep": "B-25 指定攻略与攻略平衡", "u": "B/25-U1b2OXdNcUY.html", "vid": "U1b2OXdNcUY", "q": "樱井的结论是什么？", "a": "两者没有对错，但要确定方向：学习可学之处，配合自己游戏的系统取平衡，而不是单纯参考某款游戏。", "t": 81}, {"cat": "B", "ep": "B-26 策略游戏的游戏性", "u": "B/26-3eG3expp5KM.html", "vid": "3eG3expp5KM", "q": "策略模拟最根本的游戏性是什么？", "a": "同等战力相撞大致打平；用战略改变组合（利用克制关系），实现压倒性胜利。", "t": 44}, {"cat": "B", "ep": "B-26 策略游戏的游戏性", "u": "B/26-3eG3expp5KM.html", "vid": "3eG3expp5KM", "q": "除了克制关系，还有哪些差异能让策略游戏更深？", "a": "成本（如更便宜、能准备更多）、攻击力差异、特殊特性（如能越过对手攻击）；明确的长短处与使用成本。", "t": 55}, {"cat": "B", "ep": "B-26 策略游戏的游戏性", "u": "B/26-3eG3expp5KM.html", "vid": "3eG3expp5KM", "q": "将棋、国际象棋靠什么产生博弈？", "a": "不是单位战力，而是攻击范围：选择最能发挥效果的站位，用同等战力单方面打倒对手。", "t": 110}, {"cat": "B", "ep": "B-27 玩家做得有多好？", "u": "B/27-IGpEp0R1_xY.html", "vid": "IGpEp0R1_xY", "q": "决定奖励与惩罚时，樱井建议以什么为基准？", "a": "玩家做了多好（多坏）的事；并审视无法挽回的事能否挽回、要花多少力气。", "t": 3}, {"cat": "B", "ep": "B-27 玩家做得有多好？", "u": "B/27-IGpEp0R1_xY.html", "vid": "IGpEp0R1_xY", "q": "《大乱斗》为什么让 Smash 攻击比弱攻击更强？", "a": "Smash 出招慢、会露出破绽，风险更高，打中更了不起，所以给它相称的攻击力和击飞力。", "t": 72}, {"cat": "B", "ep": "B-27 玩家做得有多好？", "u": "B/27-IGpEp0R1_xY.html", "vid": "IGpEp0R1_xY", "q": "按「做得多好」评价做过头会怎样？如何补救？", "a": "游戏会变得圆滑、失去刺激；可以适度打破常识，例如设置能大赚但会逃跑或很硬的稀有敌人。", "t": 125}, {"cat": "B", "ep": "B-28 优点和缺点都要放大", "u": "B/28-fc-hOvTBTCc.html", "vid": "fc-hOvTBTCc", "q": "为什么樱井说「削强项、补短板」是毁灭之路？", "a": "性能趋同会接近同角色对战，游戏本身失去个性，单纯不好玩。", "t": 37}, {"cat": "B", "ep": "B-28 优点和缺点都要放大", "u": "B/28-fc-hOvTBTCc.html", "vid": "fc-hOvTBTCc", "q": "樱井的游戏对平衡的态度是什么？", "a": "以凹凸为好：各有强弱、有赞有否是理所当然的，「觉得谁强就用对战决胜负」；动态范围尽量大，不因社交媒体的偏见退缩。", "t": 56}, {"cat": "B", "ep": "B-28 优点和缺点都要放大", "u": "B/28-fc-hOvTBTCc.html", "vid": "fc-hOvTBTCc", "q": "不得不调整某个招式时，可以怎样做而不失个性？", "a": "保留个性（如高攻击力），改其他参数：如加长收招破绽、缩小判定；还有发生、持续、击飞力、削盾等许多要素可调。", "t": 113}, {"cat": "B", "ep": "B-29 调平衡时给自己加个让分", "u": "B/29-2T86JqRAKjc.html", "vid": "2T86JqRAKjc", "q": "为什么说「受苦游戏」的难度调整其实不难？", "a": "开发者熟悉游戏，只要调成开发者勉强能通关，就一定很难。", "t": 3}, {"cat": "B", "ep": "B-29 调平衡时给自己加个让分", "u": "B/29-2T86JqRAKjc.html", "vid": "2T86JqRAKjc", "q": "请不熟悉游戏的人试玩有什么局限？", "a": "通常没时间让对方玩到最后；对方也会逐渐熟悉，同一个人不能做第二、三次测试。", "t": 77}, {"cat": "B", "ep": "B-29 调平衡时给自己加个让分", "u": "B/29-2T86JqRAKjc.html", "vid": "2T86JqRAKjc", "q": "樱井用什么方法给自己加让分？", "a": "单手玩（熟悉但手忙脚乱）、减少体力等物理让分、让条件更严苛；并把难度调得比想象中更低。", "t": 91}, {"cat": "C", "ep": "C-1 帧率", "u": "C/01-Rjdmi7628GM.html", "vid": "Rjdmi7628GM", "q": "游戏业界说的「帧」通常指什么？标准是多少？", "a": "画面刷新的单位（像胶片的一格），通常每秒 60 帧，也常被当作游戏的单位时间。", "t": 30}, {"cat": "C", "ep": "C-1 帧率", "u": "C/01-Rjdmi7628GM.html", "vid": "Rjdmi7628GM", "q": "可变帧率与「处理落帧」有何不同？", "a": "可变帧率只在处理重时减少画面张数，游戏速度不变；处理落帧则是游戏本身变慢。", "t": 103}, {"cat": "C", "ep": "C-1 帧率", "u": "C/01-Rjdmi7628GM.html", "vid": "Rjdmi7628GM", "q": "为什么樱井早期游戏的 PAL 版会变慢？变成多少？", "a": "PAL 只有 50 帧，而游戏以画面中断次数为时间单位，所以速度变为 5/6。", "t": 191}, {"cat": "C", "ep": "C-2 先让玩家玩起来！", "u": "C/02-PlbwQ_rntCM.html", "vid": "PlbwQ_rntCM", "q": "为什么樱井强调「最初 3 分钟」？", "a": "玩家总之先玩、判断有趣与否；让人等更久就会被放弃（街机游戏式的思考）。", "t": 2}, {"cat": "C", "ep": "C-2 先让玩家玩起来！", "u": "C/02-PlbwQ_rntCM.html", "vid": "PlbwQ_rntCM", "q": "樱井对预告片和序章有什么意见？", "a": "很多预告片先放故事演出、迟迟不展示游戏画面——不知道是什么游戏就没法买；游戏开头的长序章也让慢热游戏吃亏，应尽早切进游戏。", "t": 26}, {"cat": "C", "ep": "C-2 先让玩家玩起来！", "u": "C/02-PlbwQ_rntCM.html", "vid": "PlbwQ_rntCM", "q": "需要导入的游戏，如何仍然「先让玩家玩」？", "a": "把时间线上靠后的部分放到开头先玩，或演出成主角之前的某人在战斗，迅速进入游戏。", "t": 90}, {"cat": "C", "ep": "C-3 让回报始终在视线内", "u": "C/03-KePsEzN-IAM.html", "vid": "KePsEzN-IAM", "q": "《伊苏》在画面上显示经验值为什么好？", "a": "显示当前经验值和升级所需数值，每打倒一个敌人数值就增加，收益和目标被明示，会忍不住努力到升下一级。", "t": 49}, {"cat": "C", "ep": "C-3 让回报始终在视线内", "u": "C/03-KePsEzN-IAM.html", "vid": "KePsEzN-IAM", "q": "《Faxanadu》的商店设计带来了什么乐趣？", "a": "道具少、价格高，但买到能大幅强化；一点点攒钱、想着还差多少就能买下一件装备而努力。", "t": 75}, {"cat": "C", "ep": "C-3 让回报始终在视线内", "u": "C/03-KePsEzN-IAM.html", "vid": "KePsEzN-IAM", "q": "本期的核心启示是什么？", "a": "把回报吊在眼前、把目标放在伸手可及处，并把达成的喜悦直接传达给玩家。", "t": 108}, {"cat": "C", "ep": "C-4 以做游戏为生", "u": "C/04-_-WyivvfibM.html", "vid": "_-WyivvfibM", "q": "樱井说进入游戏业最短、几乎唯一的方法是什么？", "a": "自己做游戏（美术、作曲等专业职除外）。", "t": 33}, {"cat": "C", "ep": "C-4 以做游戏为生", "u": "C/04-_-WyivvfibM.html", "vid": "_-WyivvfibM", "q": "为什么想当策划也要自己做游戏？", "a": "策划也一定需要程序思维；做游戏时能学到哪里困难、怎么解决，积累大量经验。", "t": 62}, {"cat": "C", "ep": "C-4 以做游戏为生", "u": "C/04-_-WyivvfibM.html", "vid": "_-WyivvfibM", "q": "把作品投给游戏公司时要注意什么？", "a": "先给人玩并改进；稍不符合应聘条件也可以投；但不能只是模仿，要加入闪光的原创性。", "t": 125}, {"cat": "C", "ep": "C-5 看世界的小窗口", "u": "C/05-DGIJk0Uh8jU.html", "vid": "DGIJk0Uh8jU", "q": "坐着面对显示器时，视野角度大约多少？", "a": "约 30 度，远小于肉眼的视野。", "t": 30}, {"cat": "C", "ep": "C-5 看世界的小窗口", "u": "C/05-DGIJk0Uh8jU.html", "vid": "DGIJk0Uh8jU", "q": "驾驶舱视角为什么不常被选用？", "a": "实际可玩的范围相对画面大幅减少，让人觉得难玩。", "t": 66}, {"cat": "C", "ep": "C-5 看世界的小窗口", "u": "C/05-DGIJk0Uh8jU.html", "vid": "DGIJk0Uh8jU", "q": "樱井为何推荐玩一次 VR 赛车，又提到它的哪些问题？", "a": "行进方向与视线独立的载具类与 VR 很搭；问题是分辨率低远处模糊，且只能转头不能用余光。", "t": 82}, {"cat": "C", "ep": "C-5 看世界的小窗口", "u": "C/05-DGIJk0Uh8jU.html", "vid": "DGIJk0Uh8jU", "q": "《帕尔提娜》如何弥补 FPS 式「目标太小」的问题？", "a": "把敌人做成玩家的数倍大小。", "t": 144}, {"cat": "C", "ep": "C-6 一个按钮的可能性", "u": "C/06-tafG03n89MY.html", "vid": "tafG03n89MY", "q": "一键游戏可以分为哪四类？", "a": "连打、时机、抢按（反应）、切换。", "t": 15}, {"cat": "C", "ep": "C-6 一个按钮的可能性", "u": "C/06-tafG03n89MY.html", "vid": "tafG03n89MY", "q": "为什么樱井说连打类可能不再流行？", "a": "个人差异大、难以逆转，而且很累。", "t": 27}, {"cat": "C", "ep": "C-6 一个按钮的可能性", "u": "C/06-tafG03n89MY.html", "vid": "tafG03n89MY", "q": "「抢按」类本是纯反射，怎样产生博弈？", "a": "用假动作等诱使对手按错时机。", "t": 70}, {"cat": "C", "ep": "C-7 分解、考察、再构建", "u": "C/07-7VD0K1Sr5u0.html", "vid": "7VD0K1Sr5u0", "q": "樱井推荐的发想三步骤是什么？", "a": "分解（乐趣的要素）→ 考察（为什么有趣）→ 再构建（以独特构成重建）。", "t": 14}, {"cat": "C", "ep": "C-7 分解、考察、再构建", "u": "C/07-7VD0K1Sr5u0.html", "vid": "7VD0K1Sr5u0", "q": "为什么樱井选择在「漂移结束时」加速，而不是给分或永久强化？", "a": "加分没多大好处；永久强化会拉大高手与他人的差距；整个漂移都加速不如在过弯完成时给回报。", "t": 93}, {"cat": "C", "ep": "C-7 分解、考察、再构建", "u": "C/07-7VD0K1Sr5u0.html", "vid": "7VD0K1Sr5u0", "q": "《卡比的空中滑翔》的漂移系统是怎样的？", "a": "刹车时开始蓄力、保持漂移，在弯道结束时释放蓄力加速——一键即可游玩。", "t": 121}, {"cat": "C", "ep": "C-8 好的跑腿与坏的跑腿", "u": "C/08-IM9P9NIKo10.html", "vid": "IM9P9NIKo10", "q": "樱井列出好跑腿的五个条件是什么？", "a": "① 报酬与回报合适 ② 获得喜悦的间隔短 ③ 给予攻略自由 ④ 有结果就迅速撤收 ⑤ 让人期待展开。", "t": 78}, {"cat": "C", "ep": "C-8 好的跑腿与坏的跑腿", "u": "C/08-IM9P9NIKo10.html", "vid": "IM9P9NIKo10", "q": "为什么要在达成目的后「迅速撤收」？", "a": "就像旅行的回程比去程无聊，只让玩家享受好玩的部分即可。", "t": 131}, {"cat": "C", "ep": "C-8 好的跑腿与坏的跑腿", "u": "C/08-IM9P9NIKo10.html", "vid": "IM9P9NIKo10", "q": "怎样把「去某处看看」的跑腿变得更吸引人？", "a": "加入设定背景与谜团，例如孩子接连失踪时去调查失踪少女的家，让人期待后续展开。", "t": 176}, {"cat": "C", "ep": "C-9 学会数帧！", "u": "C/09-JZ1Jd0u3b6U.html", "vid": "JZ1Jd0u3b6U", "q": "樱井推荐用什么方法大致数帧？", "a": "数秒时在中间加一拍「1 和 2 和 3」，每拍约 30 帧，半拍约 15 帧。", "t": 94}, {"cat": "C", "ep": "C-9 学会数帧！", "u": "C/09-JZ1Jd0u3b6U.html", "vid": "JZ1Jd0u3b6U", "q": "如何估计 20 帧？", "a": "以 15 帧、30 帧为参照点，看超出多少：20 帧比 15 帧稍多，约在 30 帧的中点再长一点。", "t": 142}, {"cat": "C", "ep": "C-9 学会数帧！", "u": "C/09-JZ1Jd0u3b6U.html", "vid": "JZ1Jd0u3b6U", "q": "为什么开发者本人需要能数帧？", "a": "指定动作帧数时需要自己能测；即使输入了数值，程序或数据也可能出错，靠体感能发现问题。", "t": 189}, {"cat": "C", "ep": "C-10 让教程显得自然", "u": "C/10-Xz53DEwuAcU.html", "vid": "Xz53DEwuAcU", "q": "为什么最好让玩家直接投入实战来学操作？", "a": "既满足玩家想快点玩的心情，也能调动情绪；无机质的练习场已是少数派。", "t": 30}, {"cat": "C", "ep": "C-10 让教程显得自然", "u": "C/10-Xz53DEwuAcU.html", "vid": "Xz53DEwuAcU", "q": "《超级大金刚 3》第一关是怎样做教程的？", "a": "背景里用香蕉摆成按钮形状，按下对应按钮就能做出合适的动作。", "t": 52}, {"cat": "C", "ep": "C-10 让教程显得自然", "u": "C/10-Xz53DEwuAcU.html", "vid": "Xz53DEwuAcU", "q": "显示按钮图标式操作指引时有什么麻烦？", "a": "必须对应按键设置，需涵盖所有按钮的图标。", "t": 96}, {"cat": "C", "ep": "C-10 让教程显得自然", "u": "C/10-Xz53DEwuAcU.html", "vid": "Xz53DEwuAcU", "q": "移动类技能常用的教程手法是？", "a": "把玩家关在狭小区域，不使用技能就无法前进。", "t": 138}, {"cat": "C", "ep": "C-11 夸奖玩家！", "u": "C/11-fryDyXROp8A.html", "vid": "fryDyXROp8A", "q": "为什么说「给报酬」不等于「夸奖玩家」？", "a": "报酬只是游戏的惯例，并非从夸奖玩家的角度设计；只有它会有些不够。", "t": 63}, {"cat": "C", "ep": "C-11 夸奖玩家！", "u": "C/11-fryDyXROp8A.html", "vid": "fryDyXROp8A", "q": "《大乱斗》里有哪些悄悄的「夸奖」？", "a": "大力击飞、击坠、胜利画面、崖边险抓时观众会响起欢呼。", "t": 14}, {"cat": "C", "ep": "C-11 夸奖玩家！", "u": "C/11-fryDyXROp8A.html", "vid": "fryDyXROp8A", "q": "为什么《大乱斗 特别版》在失误爆炸里加纸屑？", "a": "从击坠者的角度华丽地夸奖他——顺着玩家心情的演出。", "t": 107}, {"cat": "C", "ep": "C-12 别没有反应", "u": "C/12-eia2IAmvtKI.html", "vid": "eia2IAmvtKI", "q": "菜单等 UI 中，樱井对确定键有何建议？", "a": "把确定键分配给多个按钮；简单动作游戏也可让按钮功能重复。", "t": 14}, {"cat": "C", "ep": "C-12 别没有反应", "u": "C/12-eia2IAmvtKI.html", "vid": "eia2IAmvtKI", "q": "为什么「按了没反应」不好？", "a": "游戏是双向信息交换，从手发出的信息很重要；玩家做了动作却无反应会很寂寞。", "t": 57}, {"cat": "C", "ep": "C-12 别没有反应", "u": "C/12-eia2IAmvtKI.html", "vid": "eia2IAmvtKI", "q": "过场动画中按按钮时可以怎么反应？", "a": "给出某种反应，例如显示跳过之类的选项。", "t": 95}, {"cat": "C", "ep": "C-13 游戏剧本很特别", "u": "C/13-ssvIEm_2mYM.html", "vid": "ssvIEm_2mYM", "q": "游戏剧本与一般媒体的四个不同点是什么？", "a": "① 剧情可能妨碍游玩 ② 基本是主角视角 ③ 主角必须一直赢 ④ 同伴难以在剧情中死亡或离队。", "t": 17}, {"cat": "C", "ep": "C-13 游戏剧本很特别", "u": "C/13-ssvIEm_2mYM.html", "vid": "ssvIEm_2mYM", "q": "为什么「打赢却被剧情判输」会有问题？", "a": "因剧情需要白费玩家的成果，会带来不讲理感和压力。", "t": 70}, {"cat": "C", "ep": "C-13 游戏剧本很特别", "u": "C/13-ssvIEm_2mYM.html", "vid": "ssvIEm_2mYM", "q": "《新·光神话 帕尔提娜之镜》如何开场？", "a": "不做任务简报，关卡一开始就穿门开打，边玩边听任务说明。", "t": 148}, {"cat": "C", "ep": "C-14 选边站的乐趣", "u": "C/14-A_A4tgLIXO4.html", "vid": "A_A4tgLIXO4", "q": "樱井认为观战乐趣的秘诀是什么？", "a": "先偏向、支持其中一方。", "t": 30}, {"cat": "C", "ep": "C-14 选边站的乐趣", "u": "C/14-A_A4tgLIXO4.html", "vid": "A_A4tgLIXO4", "q": "《大乱斗》观战模式里押积分的真正目的是什么？", "a": "积分本身意义不大，是给「偏向某方」一个小小动机。", "t": 63}, {"cat": "C", "ep": "C-14 选边站的乐趣", "u": "C/14-A_A4tgLIXO4.html", "vid": "A_A4tgLIXO4", "q": "抽卡可以从「选边」得到什么启示？", "a": "让玩家从两三个中选，或权重有理由地不同，比纯随机掉落印象更好。", "t": 120}, {"cat": "C", "ep": "C-15 3D 游戏的晕动", "u": "C/15-OS4CZkBBbW4.html", "vid": "OS4CZkBBbW4", "q": "3D 晕的原理是什么？与晕车有何不同？", "a": "眼睛与内耳信息的矛盾；晕车是有加速度而视觉不符，游戏是画面有动作而内耳无感觉，作用相反。", "t": 21}, {"cat": "C", "ep": "C-15 3D 游戏的晕动", "u": "C/15-OS4CZkBBbW4.html", "vid": "OS4CZkBBbW4", "q": "玩家可以如何减轻 3D 晕？", "a": "稍微扩大视野、意识到电视外是静止的；试试晕车药；避免长时间游玩、减少压力与疲劳。", "t": 88}, {"cat": "C", "ep": "C-15 3D 游戏的晕动", "u": "C/15-OS4CZkBBbW4.html", "vid": "OS4CZkBBbW4", "q": "开发方有哪些防晕手段？", "a": "控制演出（如可关闭步行晃动）、把载具框架固定在画面上、增加画面固定的信息、提供防晕选项。", "t": 120}, {"cat": "C", "ep": "C-16 用分层大纲整理", "u": "C/16-ZzCfzwe23kw.html", "vid": "ZzCfzwe23kw", "q": "什么是分层大纲？", "a": "把文字分层级管理的系统，像用文字管理的文件夹结构，可折叠、展开、调换。", "t": 30}, {"cat": "C", "ep": "C-16 用分层大纲整理", "u": "C/16-ZzCfzwe23kw.html", "vid": "ZzCfzwe23kw", "q": "在 Word 中如何使用大纲格式？", "a": "选择「视图」中的「大纲」。", "t": 77}, {"cat": "C", "ep": "C-16 用分层大纲整理", "u": "C/16-ZzCfzwe23kw.html", "vid": "ZzCfzwe23kw", "q": "樱井说分层大纲主要是给谁用的？给别人看要注意什么？", "a": "主要用于整理自己的点子；给别人看需要先整理清楚。", "t": 103}, {"cat": "C", "ep": "C-17 规划游戏的奖励", "u": "C/17-44ONFHla-sw.html", "vid": "44ONFHla-sw", "q": "为什么奖励要在企划阶段就想好？", "a": "没有可给的东西就什么都做不了，需要提前设计能拿什么当奖励。", "t": 4}, {"cat": "C", "ep": "C-17 规划游戏的奖励", "u": "C/17-44ONFHla-sw.html", "vid": "44ONFHla-sw", "q": "为什么《大乱斗》不适合用「角色成长」做奖励？", "a": "对战游戏若角色随进度强化，可能要先把全部角色练完才能真正开始。", "t": 79}, {"cat": "C", "ep": "C-17 规划游戏的奖励", "u": "C/17-44ONFHla-sw.html", "vid": "44ONFHla-sw", "q": "列举《大乱斗》系列用过的三种奖励及其特点。", "a": "例：斗士解锁（以乱入挑战者形式出现）；手办（介绍背景但成本高）；贴纸（省建模、可放更多角色）；命魂（装备强化）；音乐；积分。", "t": 99}, {"cat": "C", "ep": "C-17 规划游戏的奖励", "u": "C/17-44ONFHla-sw.html", "vid": "44ONFHla-sw", "q": "挑战板的主要作用是什么？", "a": "与其说是奖励，更多是给游戏某种目的；体现动机与报酬一体两面。", "t": 250}, {"cat": "C", "ep": "C-18 避免「像某某一样」", "u": "C/18-gYuvggptkDM.html", "vid": "gYuvggptkDM", "q": "为什么企划书阶段传达新游戏特别难？", "a": "还没开始做，了解它的只有企划者（及少数商量的员工），却要说服各方给预算和人手。", "t": 33}, {"cat": "C", "ep": "C-18 避免「像某某一样」", "u": "C/18-gYuvggptkDM.html", "vid": "gYuvggptkDM", "q": "樱井给企划方的建议是什么？", "a": "尽量忍住，不要用「像某某一样」来说明自己的游戏。", "t": 68}, {"cat": "C", "ep": "C-18 避免「像某某一样」", "u": "C/18-gYuvggptkDM.html", "vid": "gYuvggptkDM", "q": "避免「像某某」的两个理由？", "a": "① 类似的话不如玩原作（只有续作适合以相同为卖点）② 「某某」的含义因世代与经历差异很大。", "t": 101}, {"cat": "C", "ep": "C-19 做续作", "u": "C/19-plPR6-Gqemc.html", "vid": "plPR6-Gqemc", "q": "樱井认为游戏续作多的最大理由是什么？", "a": "游戏需要开发系统（含工具），续作可沿用已建好的系统，改良并专心充实内容。", "t": 20}, {"cat": "C", "ep": "C-19 做续作", "u": "C/19-plPR6-Gqemc.html", "vid": "plPR6-Gqemc", "q": "照搬前作的续作会怎样？为什么？", "a": "销量约减半；规模内容相同就像已分出胜负的游戏，不太想玩。", "t": 3}, {"cat": "C", "ep": "C-19 做续作", "u": "C/19-plPR6-Gqemc.html", "vid": "plPR6-Gqemc", "q": "续作要卖得好需要什么？", "a": "前作让人满意、还想玩；且续作要让人觉得比第一作更好玩、有所强化，并认真投入制作。", "t": 158}, {"cat": "C", "ep": "C-20 玩家已经知道的话就容易了", "u": "C/20-ANerCiyfJjo.html", "vid": "ANerCiyfJjo", "q": "欧美 FPS 操作相似有什么好处？", "a": "可以省略对玩家已知操作的说明，大多只需在敌人出现时显示攻击按钮图标。", "t": 32}, {"cat": "C", "ep": "C-20 玩家已经知道的话就容易了", "u": "C/20-ANerCiyfJjo.html", "vid": "ANerCiyfJjo", "q": "樱井对按键设置的态度？", "a": "即使让操作变复杂也必须提供，玩家想用自由的操作玩，游戏应尽量回应。", "t": 80}, {"cat": "C", "ep": "C-20 玩家已经知道的话就容易了", "u": "C/20-ANerCiyfJjo.html", "vid": "ANerCiyfJjo", "q": "为什么《大乱斗》不能改用十字键玩？", "a": "模拟摇杆能取细腻数值，十字键只有 0 和 1，根本不同。", "t": 116}, {"cat": "C", "ep": "C-21 自定义让想象力去玩", "u": "C/21-rwE-EEn3hYU.html", "vid": "rwE-EEn3hYU", "q": "樱井认为自定义类游戏首先要做到什么？", "a": "自定义的作业本身就要好玩，不只结果，过程与 UI 也要照顾。", "t": 20}, {"cat": "C", "ep": "C-21 自定义让想象力去玩", "u": "C/21-rwE-EEn3hYU.html", "vid": "rwE-EEn3hYU", "q": "好玩自定义的五个要点？", "a": "① 效果可视化 ② 优缺点分明 ③ 易于挑选（排序分类、自动装备）④ 能迅速试用 ⑤ 外观帅气。", "t": 66}, {"cat": "C", "ep": "C-21 自定义让想象力去玩", "u": "C/21-rwE-EEn3hYU.html", "vid": "rwE-EEn3hYU", "q": "为什么说「自动装备强装备」不可或缺？", "a": "选项很多时，它让挑选更省事；樱井认为无论如何都必须有。", "t": 133}, {"cat": "C", "ep": "C-22 做「类似」的游戏", "u": "C/22-BO_q72ug1eA.html", "vid": "BO_q72ug1eA", "q": "樱井如何看待以喜爱的游戏为蓝本做作品？", "a": "是好事：业界就这样发展，做出来发布就值得称赞。", "t": 18}, {"cat": "C", "ep": "C-22 做「类似」的游戏", "u": "C/22-BO_q72ug1eA.html", "vid": "BO_q72ug1eA", "q": "做类似游戏时要警惕玩家的什么想法？", "a": "「玩原作不就好了？」", "t": 42}, {"cat": "C", "ep": "C-22 做「类似」的游戏", "u": "C/22-BO_q72ug1eA.html", "vid": "BO_q72ug1eA", "q": "为什么类似作品要在别处加倍努力？", "a": "省掉了最难的游戏系统企划与构建，需要在其他方面堆积多项原作没有的魅力。", "t": 82}, {"cat": "C", "ep": "C-23 呈现分数", "u": "C/23-FeekeBW26AI.html", "vid": "FeekeBW26AI", "q": "为什么现在分数的意义变淡了？", "a": "游戏规模变大后「推进」成了主要目的，还有经验值、金钱、技能、排行榜等众多激励。", "t": 20}, {"cat": "C", "ep": "C-23 呈现分数", "u": "C/23-FeekeBW26AI.html", "vid": "FeekeBW26AI", "q": "樱井认为最犀利的分数呈现是什么？为什么？", "a": "《脑锻炼》的「脑年龄」：把练习变好表现得像有意义一样，连游戏的意义都改变了。", "t": 69}, {"cat": "C", "ep": "C-23 呈现分数", "u": "C/23-FeekeBW26AI.html", "vid": "FeekeBW26AI", "q": "列举两个「给分数套上尺度」的例子。", "a": "例：游戏偏差值（Mighty Bomb Jack、所罗门之钥）、被害总额（Burnout）、世界战斗力（大乱斗）、Wii Fit 的年龄。", "t": 132}, {"cat": "C", "ep": "C-24 用参数让角色立起来", "u": "C/24-zwiS1L6QVY0.html", "vid": "zwiS1L6QVY0", "q": "樱井说增加角色时性能该怎么调？", "a": "调得更尖：以中性为基准，看能偏离多少、带来多少不同可能，但不能变得无用。", "t": 20}, {"cat": "C", "ep": "C-24 用参数让角色立起来", "u": "C/24-zwiS1L6QVY0.html", "vid": "zwiS1L6QVY0", "q": "戈尔多为什么能成为印象深刻的敌人？", "a": "本身无敌、不攻击、无固定动作，单放无聊；但通过配置与其他敌人组合产生了各种意义。", "t": 62}, {"cat": "C", "ep": "C-24 用参数让角色立起来", "u": "C/24-zwiS1L6QVY0.html", "vid": "zwiS1L6QVY0", "q": "什么是特殊规格（固有规格）？举例。", "a": "为只有该角色能做的事专门写的程序；如大乱斗 DLC 斗士的反逆系统、双臂系统、方块建造、瞬间切换等。", "t": 108}, {"cat": "C", "ep": "C-25 色彩更少的世界", "u": "C/25-obnjR8KJ9nk.html", "vid": "obnjR8KJ9nk", "q": "樱井为《流星方块》做了哪些色弱支持？", "a": "用色弱滤镜检查画面，对看起来相近的颜色拉开明度差，并用方块图案补足。", "t": 43}, {"cat": "C", "ep": "C-25 色彩更少的世界", "u": "C/25-obnjR8KJ9nk.html", "vid": "obnjR8KJ9nk", "q": "除了解谜，哪些地方也可能因色弱无法分辨？", "a": "道具强化的区别、关卡机关等。", "t": 96}, {"cat": "C", "ep": "C-25 色彩更少的世界", "u": "C/25-obnjR8KJ9nk.html", "vid": "obnjR8KJ9nk", "q": "把画面转成黑白检查有什么用？", "a": "只剩明暗，能清楚看出哪里醒目，例如防止背景比前景更醒目。", "t": 130}, {"cat": "C", "ep": "C-26 电脑控制的玩家（CP）", "u": "C/26-uleauI0IwZM.html", "vid": "uleauI0IwZM", "q": "为什么 CP 做出人类无法反应的动作会出问题？", "a": "会让玩家感到极强的不讲理感（如开招就防、硬直中反击）。", "t": 39}, {"cat": "C", "ep": "C-26 电脑控制的玩家（CP）", "u": "C/26-uleauI0IwZM.html", "vid": "uleauI0IwZM", "q": "动作游戏的 CP 依据什么做决定？", "a": "与对手的距离和对手状态、数据化的招式攻击/移动范围（射程、时机）、对手的攻击数据等。", "t": 136}, {"cat": "C", "ep": "C-26 电脑控制的玩家（CP）", "u": "C/26-uleauI0IwZM.html", "vid": "uleauI0IwZM", "q": "《大乱斗 特别版》的 CP 做了哪些调整？为什么？", "a": "加入反射神经避免瞬间反应；提高攻击性、对防守待机较弱——因为想打强 CP 的人要的是有趣的对战，而不是机械反应。", "t": 211}, {"cat": "C", "ep": "C-27 游戏内过场动画", "u": "C/27-VZRh0P40RAM.html", "vid": "VZRh0P40RAM", "q": "为什么最尖端游戏中预渲染影片可能比实机画质低？", "a": "预渲染影片的分辨率与帧率可能下降，而实机画面已经很高质量。", "t": 4}, {"cat": "C", "ep": "C-27 游戏内过场动画", "u": "C/27-VZRh0P40RAM.html", "vid": "VZRh0P40RAM", "q": "过场动画的优点有哪些？", "a": "让故事更清楚、促进代入；细微动作的意义；激烈动作中让人喘口气；也可作卖点或奖励。", "t": 44}, {"cat": "C", "ep": "C-27 游戏内过场动画", "u": "C/27-VZRh0P40RAM.html", "vid": "VZRh0P40RAM", "q": "樱井对过场的跳过有什么主张？", "a": "能逐句跳过或跳到中途、快进更友好；所有影片（含制作人员表）都必须能一并跳过，即使是二周目。", "t": 140}, {"cat": "C", "ep": "C-28 从高潮开始", "u": "C/28-eAd0pt-uv8g.html", "vid": "eAd0pt-uv8g", "q": "「从高潮开始」是什么意思？", "a": "尽可能一开始就带出精彩的看点、先让玩家操作，前因后果之后再交代。", "t": 4}, {"cat": "C", "ep": "C-28 从高潮开始", "u": "C/28-eAd0pt-uv8g.html", "vid": "eAd0pt-uv8g", "q": "《新·光神话 帕尔提娜之镜》第 1 章如何开场？", "a": "开门立即空战，不到 1 分钟最终 Boss 美杜莎就登场，大胆省略开头的种种说明。", "t": 72}, {"cat": "C", "ep": "C-28 从高潮开始", "u": "C/28-eAd0pt-uv8g.html", "vid": "eAd0pt-uv8g", "q": "如果构成上难以把高潮放在开头，至少该怎么做？", "a": "让序章非常短，并迅速把操作交给玩家。", "t": 128}, {"cat": "C", "ep": "C-29 对新手温柔一点", "u": "C/29-R7rd4-ua2AI.html", "vid": "R7rd4-ua2AI", "q": "樱井在《拳皇 '95》中的苦涩经历是什么？", "a": "他用豪华连段痛扁了乱入者，结果对面是一对随便来玩的普通情侣，从此几乎不再野战。", "t": 41}, {"cat": "C", "ep": "C-29 对新手温柔一点", "u": "C/29-R7rd4-ua2AI.html", "vid": "R7rd4-ua2AI", "q": "樱井认为对战时放水是否没礼貌？", "a": "不是；只有对方明确希望你全力时才算。游戏要玩得开心才有意义。", "t": 100}, {"cat": "C", "ep": "C-29 对新手温柔一点", "u": "C/29-R7rd4-ua2AI.html", "vid": "R7rd4-ua2AI", "q": "引导新手时要注意避免什么？", "a": "指导过头、像牵着手被带走，反而让人冷掉；要留有适度自由度和自己走进去的演出。", "t": 122}, {"cat": "C", "ep": "C-30 珍惜玩家给你的时间", "u": "C/30--49L25Q0YAU.html", "vid": "-49L25Q0YAU", "q": "为什么樱井说游戏时间应视为成本？", "a": "从玩之前的感觉看，长时间意味着要放弃其他事，花在游戏上的时间应是好玩的结果而不是卖点。", "t": 51}, {"cat": "C", "ep": "C-30 珍惜玩家给你的时间", "u": "C/30--49L25Q0YAU.html", "vid": "-49L25Q0YAU", "q": "游戏与手机/SNS 相比处于什么劣势？", "a": "开始前的门槛和下决心较大（需专注、需空出时间），而 SNS 多样且开始障碍少，游戏需要超越它的魅力。", "t": 98}, {"cat": "C", "ep": "C-30 珍惜玩家给你的时间", "u": "C/30--49L25Q0YAU.html", "vid": "-49L25Q0YAU", "q": "作为创作者樱井会留意哪种时间？", "a": "玩家实际操作游玩的时间，把操作交给玩家的时间越长越好。", "t": 130}, {"cat": "D", "ep": "D-1 大场面就要停一下！", "u": "D/01-OdVkEOzdCPw.html", "vid": "OdVkEOzdCPw", "q": "什么是命中停顿？", "a": "攻击命中时短暂停住的时间；有无它手感完全不同。", "t": 33}, {"cat": "D", "ep": "D-1 大场面就要停一下！", "u": "D/01-OdVkEOzdCPw.html", "vid": "OdVkEOzdCPw", "q": "什么是樱井说的「Boss 停顿」？从哪部作品开始？", "a": "打倒 Boss 时作为演出停住画面；从 FC《星之卡比 梦之泉物语》就已实装。", "t": 62}, {"cat": "D", "ep": "D-1 大场面就要停一下！", "u": "D/01-OdVkEOzdCPw.html", "vid": "OdVkEOzdCPw", "q": "为什么射击游戏被弹时也该停顿？", "a": "否则玩家常不知不觉被打倒只觉得「咦？」；停住能让人看清子弹、增强「糟了」的手感（如《Fantasy Zone》）。", "t": 106}, {"cat": "D", "ep": "D-2 赋予按钮「重量」", "u": "D/02-9qzUwoKT9T8.html", "vid": "9qzUwoKT9T8", "q": "同一个物理按钮为什么会感觉轻重不同？", "a": "因画面上操作对象的规格：移动快慢、惯性大小、跳跃规格、延迟、帧率等。", "t": 30}, {"cat": "D", "ep": "D-2 赋予按钮「重量」", "u": "D/02-9qzUwoKT9T8.html", "vid": "9qzUwoKT9T8", "q": "樱井说电子游戏的信息交换里常被忽略的是什么？", "a": "从手得到的触感——手也能接收信息，不只是单向输出。", "t": 72}, {"cat": "D", "ep": "D-2 赋予按钮「重量」", "u": "D/02-9qzUwoKT9T8.html", "vid": "9qzUwoKT9T8", "q": "换主机时《大乱斗》要重设什么？", "a": "模拟摇杆规格不同，需要重组，包括识别摇杆倾斜的最低值（游隙）。", "t": 122}, {"cat": "D", "ep": "D-3 跳跃物理", "u": "D/03-noKsDZ-UPq8.html", "vid": "noKsDZ-UPq8", "q": "一般的跳跃是怎么程序化的？", "a": "先给向上速度，空中每帧加固定下落加速度；平地上大约回到起跳速度时着地；X 轴大致保持速度。", "t": 21}, {"cat": "D", "ep": "D-3 跳跃物理", "u": "D/03-noKsDZ-UPq8.html", "vid": "noKsDZ-UPq8", "q": "《魔界村》跳跃的特点及其带来的游戏性？", "a": "跳得低、空中几乎不能横移、起跳就确定落点；需要认真思考跳跃，也能边退边打。", "t": 144}, {"cat": "D", "ep": "D-3 跳跃物理", "u": "D/03-noKsDZ-UPq8.html", "vid": "noKsDZ-UPq8", "q": "《大乱斗》的起跳蓄力为什么不能为零？", "a": "去掉的话玩家来不及输入上 Smash 就会先跳起来。", "t": 201}, {"cat": "D", "ep": "D-3 跳跃物理", "u": "D/03-noKsDZ-UPq8.html", "vid": "noKsDZ-UPq8", "q": "特别版采用的「隐藏味道」跳跃是什么？目的？", "a": "开头给极强上升速度并在数帧内强烈减速，再恢复普通下落；让反应稍慢的玩家也能应对。", "t": 236}, {"cat": "D", "ep": "D-4 八种命中停顿技巧", "u": "D/04-tycbMSjDDLg.html", "vid": "tycbMSjDDLg", "q": "大乱斗的命中停顿与「只停住」有何不同？", "a": "停顿同时还会微振动，并含多项特殊规格。", "t": 46}, {"cat": "D", "ep": "D-4 八种命中停顿技巧", "u": "D/04-tycbMSjDDLg.html", "vid": "tycbMSjDDLg", "q": "为什么受击判定不跟着抖？", "a": "斗士直接振动会让判定位置偏移，本应命中的攻击打不中；所以只抖外观。", "t": 87}, {"cat": "D", "ep": "D-4 八种命中停顿技巧", "u": "D/04-tycbMSjDDLg.html", "vid": "tycbMSjDDLg", "q": "为什么地面上只横向抖？", "a": "地面纵向抖会让脚陷进地面；空中则全方向抖。", "t": 98}, {"cat": "D", "ep": "D-4 八种命中停顿技巧", "u": "D/04-tycbMSjDDLg.html", "vid": "tycbMSjDDLg", "q": "马尔斯剑尖与剑根的手感差如何实现？", "a": "不只是攻击力差，还给命中停顿量乘了系数。", "t": 147}, {"cat": "D", "ep": "D-4 八种命中停顿技巧", "u": "D/04-tycbMSjDDLg.html", "vid": "tycbMSjDDLg", "q": "第 7 项「攻击方微动」是什么？", "a": "停顿中以不足 1 帧的微量速度推进攻击方动画（如剑尖缓缓前进），解除后照常继续；可开关。", "t": 230}, {"cat": "D", "ep": "D-5 别把注视点黏死", "u": "D/05-kLmd2F8LaLk.html", "vid": "kLmd2F8LaLk", "q": "为什么不能把注视点黏死在角色上？", "a": "跳跃时角色始终在中央，看不出跳了多高；会让演出乏味。", "t": 70}, {"cat": "D", "ep": "D-5 别把注视点黏死", "u": "D/05-kLmd2F8LaLk.html", "vid": "kLmd2F8LaLk", "q": "《超级马里奥 64》跳跃时镜头怎么处理？", "a": "走路时马里奥在中央，跳跃时注视点不（完全）跟随 Y 方向，马里奥往画面上方移动，能感受高度。", "t": 49}, {"cat": "D", "ep": "D-5 别把注视点黏死", "u": "D/05-kLmd2F8LaLk.html", "vid": "kLmd2F8LaLk", "q": "《卡比的空中滑翔》为什么让机器在漂移时偏离注视点？", "a": "增强操作的实感，以及漂移中穿过墙边的感觉。", "t": 125}, {"cat": "D", "ep": "D-6 对「慢」说不！", "u": "D/06-3qEKNxp_-Qs.html", "vid": "3qEKNxp_-Qs", "q": "樱井说的「慢」主要指什么？", "a": "不只移动速度慢，更是做什么都花时间、什么都没在做的空白时间——玩家没在玩游戏的时间。", "t": 38}, {"cat": "D", "ep": "D-6 对「慢」说不！", "u": "D/06-3qEKNxp_-Qs.html", "vid": "3qEKNxp_-Qs", "q": "无法缩短的读取时间该怎么看？其他时间呢？", "a": "读取有时优化不了；但能缩短的时间就要压缩，为玩家提供更浓密的时间。", "t": 84}, {"cat": "D", "ep": "D-6 对「慢」说不！", "u": "D/06-3qEKNxp_-Qs.html", "vid": "3qEKNxp_-Qs", "q": "樱井在制作时会留意什么？", "a": "实际操作时间：启动后操作了多少、没操作多少、多少是空白。", "t": 133}, {"cat": "D", "ep": "D-7 速度的单位", "u": "D/07-_B0cpF8fQ4s.html", "vid": "_B0cpF8fQ4s", "q": "速度、距离、时间三者是什么关系？", "a": "速度 = 距离 ÷ 时间，知道其中两个就能求出第三个。", "t": 4}, {"cat": "D", "ep": "D-7 速度的单位", "u": "D/07-_B0cpF8fQ4s.html", "vid": "_B0cpF8fQ4s", "q": "为什么在 GB、FC、SFC 上设同样的「点/帧」会得到不同效果？", "a": "三者分辨率（点数）不同，相当于擂台大小不同，所以同样数值的实际速度感完全不同。", "t": 60}, {"cat": "D", "ep": "D-7 速度的单位", "u": "D/07-_B0cpF8fQ4s.html", "vid": "_B0cpF8fQ4s", "q": "《卡比的空气骑乘》里时速数字为什么显得很低？", "a": "因为设定前提是卡比只有 20cm 见方，看着慢其实很快。", "t": 109}, {"cat": "D", "ep": "D-8 悬崖边的行为", "u": "D/08-rcuihq0j7VM.html", "vid": "rcuihq0j7VM", "q": "为什么攻击时的小踏步最好不要让角色掉下崖？", "a": "每次小前进都掉下去，会像动作被取消一样，体验不好。", "t": 34}, {"cat": "D", "ep": "D-8 悬崖边的行为", "u": "D/08-rcuihq0j7VM.html", "vid": "rcuihq0j7VM", "q": "「按动作区分掉不掉」时还要注意什么？", "a": "速度的继承，否则可能突然以高速冲出崖外。", "t": 64}, {"cat": "D", "ep": "D-8 悬崖边的行为", "u": "D/08-rcuihq0j7VM.html", "vid": "rcuihq0j7VM", "q": "3D 游戏中有哪些有效的崖边规格？", "a": "用力推摇杆才掉、方向夹角浅时补正不让掉、自动跳跃等。", "t": 104}, {"cat": "D", "ep": "D-9 地图也是游戏画面", "u": "D/09--Fhj07C1ou0.html", "vid": "-Fhj07C1ou0", "q": "樱井觉得一直盯着小地图玩有什么问题？", "a": "画面广阔、风景精美，却在角落玩游戏，很可惜；立体空间也难用小地图表达。", "t": 3}, {"cat": "D", "ep": "D-9 地图也是游戏画面", "u": "D/09--Fhj07C1ou0.html", "vid": "-Fhj07C1ou0", "q": "《不可思议的迷宫》系列的地图有何特点？", "a": "在整个画面半透明叠加地图，可边看边玩；按按钮可只看地图。", "t": 60}, {"cat": "D", "ep": "D-9 地图也是游戏画面", "u": "D/09--Fhj07C1ou0.html", "vid": "-Fhj07C1ou0", "q": "除了充实地图，还有什么办法？", "a": "增加主画面信息量：如赛车游戏的引导标识、叠加信息、用地形布置引导。", "t": 84}, {"cat": "D", "ep": "D-10 意料之外的结果", "u": "D/10-6P8zwwQ9OhU.html", "vid": "6P8zwwQ9OhU", "q": "《Meteos》为什么比预想更难？", "a": "后期优化让游戏变快，而内部处理依赖游戏速度，难度上升曲线因此改变。", "t": 38}, {"cat": "D", "ep": "D-10 意料之外的结果", "u": "D/10-6P8zwwQ9OhU.html", "vid": "6P8zwwQ9OhU", "q": "甲虫王者掌机为何虫子饿得太快？", "a": "在大型开发板上调整，开发板与产品版处理速度可能不同。", "t": 98}, {"cat": "D", "ep": "D-10 意料之外的结果", "u": "D/10-6P8zwwQ9OhU.html", "vid": "6P8zwwQ9OhU", "q": "《大乱斗 SP》CPU 偏强后采取了什么对策？", "a": "通过在线更新调低挑战者对战难度、给灯火之星加入「非常简单」。", "t": 160}, {"cat": "D", "ep": "D-11 弹摇杆输入", "u": "D/11-ChNceKFm2kI.html", "vid": "ChNceKFm2kI", "q": "「弹摇杆输入」利用了模拟摇杆的什么信息？", "a": "摇杆推到边缘所花的时间（推的快慢），而不只是方向和深度。", "t": 30}, {"cat": "D", "ep": "D-11 弹摇杆输入", "u": "D/11-ChNceKFm2kI.html", "vid": "ChNceKFm2kI", "q": "弹摇杆相比以前的冲刺操作好在哪里？", "a": "以前需两次输入或配合按键；弹摇杆一步完成，用快慢区分强弱，有感情又好懂。", "t": 48}, {"cat": "D", "ep": "D-11 弹摇杆输入", "u": "D/11-ChNceKFm2kI.html", "vid": "ChNceKFm2kI", "q": "弹摇杆的缺点是什么？《大乱斗 SP》怎么处理？", "a": "容易误触（如误冲刺）；SP 可调节弹摇杆灵敏度。", "t": 78}, {"cat": "D", "ep": "D-12 教玩家怎么玩", "u": "D/12-Icl-jMlz1iY.html", "vid": "Icl-jMlz1iY", "q": "樱井认为最差的教程方式是什么？其次要避免的呢？", "a": "最差是让玩家读说明书似的长文；其次是在无机质的练习场里操作。", "t": 38}, {"cat": "D", "ep": "D-12 教玩家怎么玩", "u": "D/12-Icl-jMlz1iY.html", "vid": "Icl-jMlz1iY", "q": "初代《大乱斗》的「打靶」为何每个角色都不同？", "a": "因为它是以让玩家熟练该角色操作为目的来布置的。", "t": 82}, {"cat": "D", "ep": "D-12 教玩家怎么玩", "u": "D/12-Icl-jMlz1iY.html", "vid": "Icl-jMlz1iY", "q": "樱井最懊悔的是什么？", "a": "《大乱斗 SP》计划的边操作边学技巧的模式因日程原因流产。", "t": 107}, {"cat": "D", "ep": "D-13 随机性为游戏添彩", "u": "D/13-e9v_FwUGOwY.html", "vid": "e9v_FwUGOwY", "q": "为什么说随机反而能带来策略性？", "a": "它给玩家「应对各种状况」的策略，而不是一套固定解法。", "t": 44}, {"cat": "D", "ep": "D-13 随机性为游戏添彩", "u": "D/13-e9v_FwUGOwY.html", "vid": "e9v_FwUGOwY", "q": "随机的主要缺点是什么？", "a": "不公平：运气左右结果，因运气差而输很难让玩家接受。", "t": 60}, {"cat": "D", "ep": "D-13 随机性为游戏添彩", "u": "D/13-e9v_FwUGOwY.html", "vid": "e9v_FwUGOwY", "q": "《大乱斗》中勇者的随机指令为何被保留？", "a": "项目随机出现，但能否用好它就是实力。", "t": 150}, {"cat": "D", "ep": "D-13 随机性为游戏添彩", "u": "D/13-e9v_FwUGOwY.html", "vid": "e9v_FwUGOwY", "q": "电脑生成随机时要注意什么？", "a": "严格来说不能真随机，特定操作可能必出特定值；应参考内置时钟等不确定值。", "t": 198}, {"cat": "D", "ep": "D-14 让分系统", "u": "D/14--aA_mjpCPMg.html", "vid": "-aA_mjpCPMg", "q": "为什么樱井认为休闲游戏应该加入追赶机制？", "a": "实力第一的人一直第一并不好玩；家庭里有输有赢，是维持休闲游戏的条件之一。", "t": 50}, {"cat": "D", "ep": "D-14 让分系统", "u": "D/14--aA_mjpCPMg.html", "vid": "-aA_mjpCPMg", "q": "《大乱斗》的共通系统中唯一的让分要素是什么？", "a": "领先者更难拿到 Smash 球（终极必杀槽也是落后方更易积攒）。", "t": 104}, {"cat": "D", "ep": "D-14 让分系统", "u": "D/14--aA_mjpCPMg.html", "vid": "-aA_mjpCPMg", "q": "樱井认为最有效的让分是什么？", "a": "人力让分：如和孩子、新手玩时让对方捡 Smash 球、故意挨打。", "t": 182}, {"cat": "D", "ep": "D-15 平均就是平庸", "u": "D/15-KW4x-_Y8BmM.html", "vid": "KW4x-_Y8BmM", "q": "为什么只看强弱调平衡会出问题？", "a": "性能会被平均化：短处补上、长处削掉，最后变得平庸无趣。", "t": 20}, {"cat": "D", "ep": "D-15 平均就是平庸", "u": "D/15-KW4x-_Y8BmM.html", "vid": "KW4x-_Y8BmM", "q": "樱井监修时采用什么方向？", "a": "不扼杀个性，例如有长处的就把短处加大。", "t": 40}, {"cat": "D", "ep": "D-15 平均就是平庸", "u": "D/15-KW4x-_Y8BmM.html", "vid": "KW4x-_Y8BmM", "q": "《大乱斗 SP》线上胜率的最高和最低是多少？", "a": "最高 51.43%，最低 47.18%，87 名斗士都在这个范围内。", "t": 168}, {"cat": "D", "ep": "D-16 在线更新", "u": "D/16-e89D_CG9P0g.html", "vid": "e89D_CG9P0g", "q": "为什么现代游戏很难以「万全状态」发售？", "a": "只有流程与完成形态都确定时才可能；而且现代游戏极其复杂，全部正确运行已近乎奇迹。", "t": 40}, {"cat": "D", "ep": "D-16 在线更新", "u": "D/16-e89D_CG9P0g.html", "vid": "e89D_CG9P0g", "q": "为什么调试很难发现所有 bug？", "a": "千分之一的 bug 调试中难遇到；上市后尝试次数是完全不同的量级，且调试期条件不断变化。", "t": 115}, {"cat": "D", "ep": "D-16 在线更新", "u": "D/16-e89D_CG9P0g.html", "vid": "e89D_CG9P0g", "q": "樱井对更新的最终提醒是什么？", "a": "玩家一开始就弃游，更新再好也没用；应力求一开始就更好。", "t": 210}, {"cat": "D", "ep": "D-17 快速的画面切换", "u": "D/17-9ic7LEHtekM.html", "vid": "9ic7LEHtekM", "q": "为什么画面切换要尽量快？", "a": "慢是罪：慢速淡出、长黑屏、长时间无法操作会夺走玩家宝贵时间。", "t": 3}, {"cat": "D", "ep": "D-17 快速的画面切换", "u": "D/17-9ic7LEHtekM.html", "vid": "9ic7LEHtekM", "q": "初代《生化危机》的开门演出有什么作用？", "a": "兼作读取时间与恐怖演出；有僵尸处开门会稍久。", "t": 52}, {"cat": "D", "ep": "D-17 快速的画面切换", "u": "D/17-9ic7LEHtekM.html", "vid": "9ic7LEHtekM", "q": "什么情况下值得用复杂的 wipe？", "a": "贴合游戏主题，且速度不成问题时。", "t": 114}, {"cat": "D", "ep": "D-18 偏移重心会怎样？", "u": "D/18-jeA-m-Bzs04.html", "vid": "jeA-m-Bzs04", "q": "「晃晃弹」是怎么做的？", "a": "偏移精灵显示位置，6 帧一圈按上、右上、右下、下、左下、左上循环。", "t": 38}, {"cat": "D", "ep": "D-18 偏移重心会怎样？", "u": "D/18-jeA-m-Bzs04.html", "vid": "jeA-m-Bzs04", "q": "《大乱斗 SP》投掷炸弹时旋转轴如何设置？为什么？", "a": "稍微偏离炸弹中心，带出不稳定感；固定中心会更无机质。", "t": 70}, {"cat": "D", "ep": "D-18 偏移重心会怎样？", "u": "D/18-jeA-m-Bzs04.html", "vid": "jeA-m-Bzs04", "q": "为什么规格实现的运动更容易显得乏味？", "a": "程序做法常默认直进或匀速圆周旋转，被机器的常识带着走。", "t": 125}, {"cat": "E", "ep": "E-1 团队内的信息共享", "u": "E/01-40ryMOr36fw.html", "vid": "40ryMOr36fw", "q": "为什么樱井重视团队内的信息共享？", "a": "大型项目中个人容易看不清目的和全貌，这种工作有压力；共享信息还能打破倦怠。", "t": 26}, {"cat": "E", "ep": "E-1 团队内的信息共享", "u": "E/01-40ryMOr36fw.html", "vid": "40ryMOr36fw", "q": "樱井用的三个办法是什么？", "a": "内部进度页面（带评论栏）、每日一张开发截图、每隔几个月的项目发表会。", "t": 62}, {"cat": "E", "ep": "E-1 团队内的信息共享", "u": "E/01-40ryMOr36fw.html", "vid": "40ryMOr36fw", "q": "项目发表会好在哪里？", "a": "由团队亲自发表成果，能从单纯制造的工作中获得更俯瞰的视角，并带来刺激与成就感。", "t": 150}, {"cat": "E", "ep": "E-2 游戏开发的职种", "u": "E/02-Hk2npGxEQRo.html", "vid": "Hk2npGxEQRo", "q": "总监和策划的分工有何不同？", "a": "总监出点子、汇总并几乎决定一切；策划把总监的构想写成规格书分发给各职种，并做平衡、调试指挥、写脚本等。", "t": 30}, {"cat": "E", "ep": "E-2 游戏开发的职种", "u": "E/02-Hk2npGxEQRo.html", "vid": "Hk2npGxEQRo", "q": "为什么说素材都汇集到程序这里？", "a": "程序把规格书落实为可运行的游戏，其他职种做的素材都在这里组合完成。", "t": 85}, {"cat": "E", "ep": "E-2 游戏开发的职种", "u": "E/02-Hk2npGxEQRo.html", "vid": "Hk2npGxEQRo", "q": "监测（Play Tester）和调试（Debugger）有什么区别？", "a": "监测找问题和需调整处（调整由策划进行）；调试专门找 bug 并附复现方法报告。", "t": 297}, {"cat": "E", "ep": "E-3 有想法别憋着", "u": "E/03-f3UjN6cCBYY.html", "vid": "f3UjN6cCBYY", "q": "樱井认为面对不满时最不好的做法是什么？", "a": "在团队里不说，等工作结束后才说「其实我当时这么想」——事后诸葛。", "t": 30}, {"cat": "E", "ep": "E-3 有想法别憋着", "u": "E/03-f3UjN6cCBYY.html", "vid": "f3UjN6cCBYY", "q": "为什么说团队成员处于有利位置？", "a": "玩家不满只能抱怨，而开发中的成员有可能实际改善作品。", "t": 60}, {"cat": "E", "ep": "E-3 有想法别憋着", "u": "E/03-f3UjN6cCBYY.html", "vid": "f3UjN6cCBYY", "q": "提出否定意见时应该附带什么？", "a": "改善案：否定与改善案配成一套才是建设性的。", "t": 104}, {"cat": "E", "ep": "E-4 十个人只能做出七个人的工作", "u": "E/04-1-iZFmenARA.html", "vid": "1-iZFmenARA", "q": "为什么 10 人团队一般只能产出约 7 人份的工作？", "a": "团队需要花时间在管理上：工作量管理、对外沟通、方向监修等。", "t": 3}, {"cat": "E", "ep": "E-4 十个人只能做出七个人的工作", "u": "E/04-1-iZFmenARA.html", "vid": "1-iZFmenARA", "q": "优秀的人转做领导会带来什么取舍？", "a": "失去其个人产出，但他成为团队的「大脑」，决定方向、维持品质并推动团队。", "t": 61}, {"cat": "E", "ep": "E-4 十个人只能做出七个人的工作", "u": "E/04-1-iZFmenARA.html", "vid": "1-iZFmenARA", "q": "樱井推荐的成果发表会有什么好处？", "a": "让全队看到彼此的工作、培养发表能力、加深为他人制作的意识。", "t": 117}, {"cat": "E", "ep": "E-5 向所有人一次讲清", "u": "E/05-CafmzxRBo4Y.html", "vid": "CafmzxRBo4Y", "q": "《新·光神话》开发时遇到了什么问题？", "a": "总监→策划→程序层层转述，解释和成品有时完全相反；各员工文化差异太大。", "t": 3}, {"cat": "E", "ep": "E-5 向所有人一次讲清", "u": "E/05-CafmzxRBo4Y.html", "vid": "CafmzxRBo4Y", "q": "从《大乱斗 3DS/Wii U》开始的新体制是什么？", "a": "监修内容由与该要素相关的全体员工一起听（策划、程序、模型、动作、特效、声音等）。", "t": 44}, {"cat": "E", "ep": "E-5 向所有人一次讲清", "u": "E/05-CafmzxRBo4Y.html", "vid": "CafmzxRBo4Y", "q": "这种做法的代价和好处是什么？", "a": "代价是占用更多时间；好处是理解更深、各职种都知道方向、大型项目更通风。", "t": 137}, {"cat": "E", "ep": "E-6 写日报的建议", "u": "E/06-T6XgiBzYbzs.html", "vid": "T6XgiBzYbzs", "q": "樱井的日报一般包含什么？", "a": "顶部一张「今日一张」截图，然后 3～5 个话题：新闻、监修内容、检查项、bug 报告、闲话等，可评论。", "t": 24}, {"cat": "E", "ep": "E-6 写日报的建议", "u": "E/06-T6XgiBzYbzs.html", "vid": "T6XgiBzYbzs", "q": "为什么日报比全体邮件更能传达信息？", "a": "邮件意外地常没人读；日报页面每天变化，很多人自发来看。", "t": 100}, {"cat": "E", "ep": "E-6 写日报的建议", "u": "E/06-T6XgiBzYbzs.html", "vid": "T6XgiBzYbzs", "q": "列出日报的几项好处。", "a": "让团队认识外来者的他、信息共享、输出训练、每日给团队刺激、确认进度。", "t": 66}, {"cat": "E", "ep": "E-7 调试永无止境", "u": "E/07-yIXB0vGJBuw.html", "vid": "yIXB0vGJBuw", "q": "为什么现代游戏难以完全消灭 bug？", "a": "规模太大，组合（斗士×招式×时机×道具×人数×场地×命魂…）是天文数字，不可能全部穷举。", "t": 38}, {"cat": "E", "ep": "E-7 调试永无止境", "u": "E/07-yIXB0vGJBuw.html", "vid": "yIXB0vGJBuw", "q": "《大乱斗 SP》中特别容易出 bug 的地方有哪些？", "a": "抓投等强制控制、终极必杀（尤其有场景切换的）、地形（V 字凹陷）、命魂。", "t": 113}, {"cat": "E", "ep": "E-7 调试永无止境", "u": "E/07-yIXB0vGJBuw.html", "vid": "yIXB0vGJBuw", "q": "为什么补丁不能修完马上发布？", "a": "修正可能引入新 bug，需要重新做大量检查。", "t": 190}, {"cat": "E", "ep": "E-8 在公司里做游戏", "u": "E/08-fiCLKUQtKg0.html", "vid": "fiCLKUQtKg0", "q": "为什么卖不好不能简单归咎于某个人？", "a": "原因很多：外观、标题、宣传、竞争作品、时机、机种等；「不好玩」的优先度比想象低。", "t": 52}, {"cat": "E", "ep": "E-8 在公司里做游戏", "u": "E/08-fiCLKUQtKg0.html", "vid": "fiCLKUQtKg0", "q": "樱井为什么说公司是「温柔的世界」？", "a": "即使作品卖不出去，员工工资仍有保障，责任在公司。", "t": 76}, {"cat": "E", "ep": "E-8 在公司里做游戏", "u": "E/08-fiCLKUQtKg0.html", "vid": "fiCLKUQtKg0", "q": "樱井对公司里工作的人有什么建议？", "a": "别有被迫工作的意识，公司是互相支撑的地方，要互相帮助。", "t": 160}, {"cat": "E", "ep": "E-9 当天的事当天做完", "u": "E/09-j1qLM0yfOuY.html", "vid": "j1qLM0yfOuY", "q": "樱井团队的监修顺序如何决定？", "a": "按监修委托邮件到达的时间，先到先得。", "t": 50}, {"cat": "E", "ep": "E-9 当天的事当天做完", "u": "E/09-j1qLM0yfOuY.html", "vid": "j1qLM0yfOuY", "q": "为什么樱井坚持当天回完邮件？", "a": "回复前的时间就是别人的等待时间；关键人物的延迟直接变成团队延迟；拖延让第二天更痛苦。", "t": 97}, {"cat": "E", "ep": "E-9 当天的事当天做完", "u": "E/09-j1qLM0yfOuY.html", "vid": "j1qLM0yfOuY", "q": "总监如何确保自己的工作时间？", "a": "设定「不监修时间」，如上午或某时刻之后不接受监修。", "t": 136}, {"cat": "E", "ep": "E-10 别把决定往后推", "u": "E/10-NaWuNgpYDi4.html", "vid": "NaWuNgpYDi4", "q": "有判断权的人在会议中应该怎么做？", "a": "当场即决，不把决定带回去推迟。", "t": 24}, {"cat": "E", "ep": "E-10 别把决定往后推", "u": "E/10-NaWuNgpYDi4.html", "vid": "NaWuNgpYDi4", "q": "为什么判断不能拖？", "a": "方向错误会浪费大量时间，但多数时候没空犹豫；等待期间案件悬空，即时判断能帮到很多人。", "t": 44}, {"cat": "E", "ep": "E-10 别把决定往后推", "u": "E/10-NaWuNgpYDi4.html", "vid": "NaWuNgpYDi4", "q": "「不推迟」和「弹性」如何兼顾？", "a": "当场决定，但发现错误时不错着走下去，而是再判断；细小多次地修正轨道。", "t": 101}, {"cat": "E", "ep": "E-11 调试体制", "u": "E/11-mQJEWMmZutA.html", "vid": "mQJEWMmZutA", "q": "调试的大前提是什么？", "a": "统一每天更新的 ROM 版本，不同版本上的 bug 没有参考价值。", "t": 47}, {"cat": "E", "ep": "E-11 调试体制", "u": "E/11-mQJEWMmZutA.html", "vid": "mQJEWMmZutA", "q": "S 级和 A 级 bug 分别指什么？", "a": "S 级：卡死或可能损坏存档；A 级：妨碍游戏进行。", "t": 94}, {"cat": "E", "ep": "E-11 调试体制", "u": "E/11-mQJEWMmZutA.html", "vid": "mQJEWMmZutA", "q": "bug 修好后工单如何处理？", "a": "回到调试员确认；不删除，以完成状态保存以防再发。", "t": 128}, {"cat": "E", "ep": "E-11 调试体制", "u": "E/11-mQJEWMmZutA.html", "vid": "mQJEWMmZutA", "q": "bug 最麻烦的一点是什么？", "a": "修 bug 可能引入新 bug，且不是小心就能防住。", "t": 218}, {"cat": "E", "ep": "E-12 测试游玩永不停歇", "u": "E/12-TayNJ4603Hc.html", "vid": "TayNJ4603Hc", "q": "《大乱斗》到 DX 为止参数由谁调整？", "a": "樱井独断调整全部参数（攻击、移动性能等）。", "t": 48}, {"cat": "E", "ep": "E-12 测试游玩永不停歇", "u": "E/12-TayNJ4603Hc.html", "vid": "TayNJ4603Hc", "q": "《大乱斗 SP》在平衡调整上有何进步？", "a": "监测组人数和实力大幅提升，并能参考线上对战与大赛数据。", "t": 114}, {"cat": "E", "ep": "E-12 测试游玩永不停歇", "u": "E/12-TayNJ4603Hc.html", "vid": "TayNJ4603Hc", "q": "樱井什么时候会对监测组的调整插嘴？", "a": "多半是在个性快要被扼杀的时候。", "t": 196}, {"cat": "E", "ep": "E-13 总监与制作人", "u": "E/13-isEMP5_Eems.html", "vid": "isEMP5_Eems", "q": "总监在游戏开发中扮演什么角色？", "a": "「监督」：拥有游戏内容几乎全部判断权，通常一队一人，多半也负责构思企划。", "t": 30}, {"cat": "E", "ep": "E-13 总监与制作人", "u": "E/13-isEMP5_Eems.html", "vid": "isEMP5_Eems", "q": "制作人主要负责什么？", "a": "团队管理、资金运营、人员配置、计算成本效益和宣传。", "t": 98}, {"cat": "E", "ep": "E-13 总监与制作人", "u": "E/13-isEMP5_Eems.html", "vid": "isEMP5_Eems", "q": "两者在责任视角上有何不同？", "a": "总监对一款软件的品质负责；制作人从全公司角度俯瞰项目进展，常兼顾多个项目。", "t": 190}, {"cat": "E", "ep": "E-14 小学生测试员", "u": "E/14-aACUZ769djE.html", "vid": "aACUZ769djE", "q": "小学生监测的理想氛围是什么样的？", "a": "准备零食，像游乐场一样，而不是一般的测试印象。", "t": 20}, {"cat": "E", "ep": "E-14 小学生测试员", "u": "E/14-aACUZ769djE.html", "vid": "aACUZ769djE", "q": "小学生监测主要观察什么？", "a": "真实反应：反应好的地方、操作卡住的地方、快玩腻的地方——观察气氛而非听意见。", "t": 34}, {"cat": "E", "ep": "E-14 小学生测试员", "u": "E/14-aACUZ769djE.html", "vid": "aACUZ769djE", "q": "为什么现在难以举办？", "a": "SNS 时代、需要高度保密，以及要保障小学生安全。", "t": 63}, {"cat": "E", "ep": "E-15 总监的工作是「削减」", "u": "E/15-MS2Tf3nXhZE.html", "vid": "MS2Tf3nXhZE", "q": "计划不如预期时，总监要做什么？", "a": "预见损失，扔掉太重或会起火的「货物」，修正航线。", "t": 30}, {"cat": "E", "ep": "E-15 总监的工作是「削减」", "u": "E/15-MS2Tf3nXhZE.html", "vid": "MS2Tf3nXhZE", "q": "樱井为什么说总监自己调整最快？", "a": "与其制作人与总监边吵边折中，不如由总监理解问题并直接调整。", "t": 54}, {"cat": "E", "ep": "E-15 总监的工作是「削减」", "u": "E/15-MS2Tf3nXhZE.html", "vid": "MS2Tf3nXhZE", "q": "总监最困扰的是什么情况？", "a": "计划内的东西一直不顺利却拖着，最后关头才说做不出来。", "t": 98}, {"cat": "F", "ep": "F-1 画光，而不是画素材", "u": "F/01-FuAtKjEuck8.html", "vid": "FuAtKjEuck8", "q": "樱井常对背景美术说的一句话是什么？", "a": "不要画素材，要画反射在素材上的光。", "t": 50}, {"cat": "F", "ep": "F-1 画光，而不是画素材", "u": "F/01-FuAtKjEuck8.html", "vid": "FuAtKjEuck8", "q": "为什么不能指望渲染自动把简单贴图变好看？", "a": "大多数环境渲染能力不够，且有硬件性能问题；处理越轻能显示越多，所以要用简单手法让它更好看。", "t": 90}, {"cat": "F", "ep": "F-1 画光，而不是画素材", "u": "F/01-FuAtKjEuck8.html", "vid": "FuAtKjEuck8", "q": "森林例子中提升画面的三个步骤是什么？", "a": "加入光（带色光与明暗）、错开色相、加入空气感。", "t": 120}, {"cat": "F", "ep": "F-2 强调有判定的东西", "u": "F/02-FfPN4ZGgBpo.html", "vid": "FfPN4ZGgBpo", "q": "舞台绘制的核心原则是什么？", "a": "强调有接触判定的东西，不强调其他东西。", "t": 30}, {"cat": "F", "ep": "F-2 强调有判定的东西", "u": "F/02-FfPN4ZGgBpo.html", "vid": "FfPN4ZGgBpo", "q": "为什么不能简单地给远景加空气透视了事？", "a": "判定也许变清楚，但外观会大受损害；画面漂亮也很重要，卖不出去就没意义。", "t": 100}, {"cat": "F", "ep": "F-2 强调有判定的东西", "u": "F/02-FfPN4ZGgBpo.html", "vid": "FfPN4ZGgBpo", "q": "为什么背景越讲究，地形反而可能越不显眼？", "a": "精细的远景会在信息量上压过有判定的地形，3D 透视又让判定位置难懂。", "t": 62}, {"cat": "F", "ep": "F-3 分辨大事与小事", "u": "F/03-NBXt-Uq7dHg.html", "vid": "NBXt-Uq7dHg", "q": "为什么要分辨大事与小事？", "a": "游戏机性能比想象的低，必须精打细算，把资源分给效果最高的地方。", "t": 15}, {"cat": "F", "ep": "F-3 分辨大事与小事", "u": "F/03-NBXt-Uq7dHg.html", "vid": "NBXt-Uq7dHg", "q": "斗士为什么不一定要无限优先？", "a": "斗士常以小尺寸显示，重要的是占画面比例；但因会被放大做素材，也有一定优待。", "t": 65}, {"cat": "F", "ep": "F-3 分辨大事与小事", "u": "F/03-NBXt-Uq7dHg.html", "vid": "NBXt-Uq7dHg", "q": "樱井要求减轻的「看不见的讲究」是什么？", "a": "墨水舞台远景里汽车的轮胎在转。", "t": 130}, {"cat": "F", "ep": "F-4 把握好尺度感", "u": "F/04-A6Rbb5sK4nI.html", "vid": "A6Rbb5sK4nI", "q": "尺度感问题通常表现为什么？", "a": "大东西看起来比应有的小；反过来很少见。", "t": 33}, {"cat": "F", "ep": "F-4 把握好尺度感", "u": "F/04-A6Rbb5sK4nI.html", "vid": "A6Rbb5sK4nI", "q": "列举三个影响尺度感的贴图/材质因素。", "a": "贴图循环与材质尺寸、饱和度、高光、法线贴图、污渍与色相变化（任选三）。", "t": 80}, {"cat": "F", "ep": "F-4 把握好尺度感", "u": "F/04-A6Rbb5sK4nI.html", "vid": "A6Rbb5sK4nI", "q": "为什么樱井没有提模型形状？", "a": "实物与模型形状相同；形状的优先级低于贴图与材质等因素。", "t": 170}, {"cat": "F", "ep": "F-5 用修图来监修美术", "u": "F/05-s08NT-TVCvU.html", "vid": "s08NT-TVCvU", "q": "为什么樱井用修图来做监修？", "a": "这种调整口头难传达；修图约 5～10 分钟就能做完，比口头说明有效。", "t": 90}, {"cat": "F", "ep": "F-5 用修图来监修美术", "u": "F/05-s08NT-TVCvU.html", "vid": "s08NT-TVCvU", "q": "洞窟修图的步骤是什么？", "a": "读入 Photoshop，复制图层提高对比，错开色相，在受光处用橡皮擦，最后整理色调。", "t": 110}, {"cat": "F", "ep": "F-5 用修图来监修美术", "u": "F/05-s08NT-TVCvU.html", "vid": "s08NT-TVCvU", "q": "灯火之星通路的熔岩为什么不做太耀眼？", "a": "因为伤眼。", "t": 70}, {"cat": "F", "ep": "F-6 近看《大乱斗》的舞台", "u": "F/06-lvYN7JciOdk.html", "vid": "lvYN7JciOdk", "q": "《特别版》的基础舞台大约有多少个？运行条件是什么？", "a": "约 115 个；要在 Switch 上 8 人同屏、60 帧运行，几乎没有余裕。", "t": 5}, {"cat": "F", "ep": "F-6 近看《大乱斗》的舞台", "u": "F/06-lvYN7JciOdk.html", "vid": "lvYN7JciOdk", "q": "樱井认为这一集对谁特别有参考价值？", "a": "有志于游戏美术的人——可以近看舞台组的成果。", "t": 35}, {"cat": "F", "ep": "F-6 近看《大乱斗》的舞台", "u": "F/06-lvYN7JciOdk.html", "vid": "lvYN7JciOdk", "q": "樱井如何形容制作这么多舞台？", "a": "很有挑战，但俯瞰众多游戏也是乐趣，大家都全力以赴也很开心。", "t": 1025}, {"cat": "F", "ep": "F-7 像素画的基础", "u": "F/07-NDno0U5UxSI.html", "vid": "NDno0U5UxSI", "q": "在 16×16 的精灵里画圆，为什么 15 点更好？", "a": "15 点（奇数）能取到中线，更接近正圆。", "t": 70}, {"cat": "F", "ep": "F-7 像素画的基础", "u": "F/07-NDno0U5UxSI.html", "vid": "NDno0U5UxSI", "q": "只有黑白两色时，怎么画出铁球？", "a": "涂黑，只画高光。", "t": 110}, {"cat": "F", "ep": "F-7 像素画的基础", "u": "F/07-NDno0U5UxSI.html", "vid": "NDno0U5UxSI", "q": "多一种颜色时可以加哪些表现？", "a": "柔边（中间色），以及表现地面反射的反光。", "t": 120}, {"cat": "F", "ep": "F-8 统一画风", "u": "F/08-BLzEMMcwUKk.html", "vid": "BLzEMMcwUKk", "q": "什么是概念图（Image Board）？由谁来画？", "a": "把背景、世界观、角色、道具画出来的图，用于统一笔触；数量不多，由优秀的人带头画。", "t": 60}, {"cat": "F", "ep": "F-8 统一画风", "u": "F/08-BLzEMMcwUKk.html", "vid": "BLzEMMcwUKk", "q": "《大乱斗》为什么给马力欧的工装裤加牛仔布纹理？", "a": "为了在写实与卡通角色混在一起时尽量对齐笔触，避免「动画和真人在打架」。", "t": 90}, {"cat": "F", "ep": "F-8 统一画风", "u": "F/08-BLzEMMcwUKk.html", "vid": "BLzEMMcwUKk", "q": "为什么硬件机能越高，统一画风越难？", "a": "表现越精细，对齐笔触与质感所需的成本就越高。", "t": 117}, {"cat": "F", "ep": "F-9 动画与真人之战", "u": "F/09-luB-5GqW55Q.html", "vid": "luB-5GqW55Q", "q": "为什么《大乱斗》的角色要降低饱和度？", "a": "稍淡更容易受光源影响；大红在任何环境光下都几乎是大红，常和沉稳角色不搭。", "t": 60}, {"cat": "F", "ep": "F-9 动画与真人之战", "u": "F/09-luB-5GqW55Q.html", "vid": "luB-5GqW55Q", "q": "纹理刻画如何填补卡通与写实的差距？", "a": "给卡通系增加刻画，给写实系减轻厚重感。", "t": 90}, {"cat": "F", "ep": "F-9 动画与真人之战", "u": "F/09-luB-5GqW55Q.html", "vid": "luB-5GqW55Q", "q": "大金刚和耀西的眼睛在《大乱斗》中做了什么改变？", "a": "原作只闭上瞳孔（漫画表现），《大乱斗》获准改为闭上眼皮，更像现实中存在。", "t": 195}, {"cat": "F", "ep": "F-10 画面好坏影响乐趣吗？", "u": "F/10-VM-kH-j9_OQ.html", "vid": "VM-kH-j9_OQ", "q": "背景的「存在感」由什么影响？", "a": "由游戏内容影响——例如在容易死的游戏里会警惕地观察每个角落，背景存在感更突出。", "t": 60}, {"cat": "F", "ep": "F-10 画面好坏影响乐趣吗？", "u": "F/10-VM-kH-j9_OQ.html", "vid": "VM-kH-j9_OQ", "q": "为什么说画面与乐趣是「乘法」？", "a": "网店里玩家看横幅决定是否点进去，画面不吸引人就不会被玩。", "t": 125}, {"cat": "F", "ep": "F-10 画面好坏影响乐趣吗？", "u": "F/10-VM-kH-j9_OQ.html", "vid": "VM-kH-j9_OQ", "q": "「背景只是布景」是什么意思？", "a": "背景是没有判定、没有重力的多边形布景，其存在感取决于游戏内容。", "t": 40}, {"cat": "F", "ep": "F-11 监修杂谈", "u": "F/11-wKQ2v9kno9I.html", "vid": "wKQ2v9kno9I", "q": "远程办公后樱井如何监修？为什么还要修图画图？", "a": "基本靠邮件文字；但实际展示更好懂，所以修图、画图来指示。", "t": 10}, {"cat": "F", "ep": "F-11 监修杂谈", "u": "F/11-wKQ2v9kno9I.html", "vid": "wKQ2v9kno9I", "q": "阿尔斯特云海的风车出了什么问题？", "a": "风车转向与风向相反；要看清风向和叶片方向（已修正）。", "t": 366}, {"cat": "F", "ep": "F-11 监修杂谈", "u": "F/11-wKQ2v9kno9I.html", "vid": "wKQ2v9kno9I", "q": "一八着地时翅膀为何要调整？", "a": "着地只用 2 帧就收起，留不下印象太可惜。", "t": 465}, {"cat": "F", "ep": "F-11 监修杂谈", "u": "F/11-wKQ2v9kno9I.html", "vid": "wKQ2v9kno9I", "q": "三岛道场为何要在左右远景投入信息量？", "a": "左右远景比较容易被看到，信息量应分配给常被看见的地方。", "t": 500}, {"cat": "F", "ep": "F-12 让东西看起来像微缩模型", "u": "F/12-omeFOX21-wc.html", "vid": "omeFOX21-wc", "q": "微缩照片的四个步骤是什么？", "a": "俯拍、上下模糊（景深）、提高饱和度、降低蓝色（去掉空气透视）。", "t": 25}, {"cat": "F", "ep": "F-12 让东西看起来像微缩模型", "u": "F/12-omeFOX21-wc.html", "vid": "omeFOX21-wc", "q": "为什么景深要少用？", "a": "注视点因人而异，自己看的地方变糊生理上不舒服；除非有意图，不要加。", "t": 70}, {"cat": "F", "ep": "F-12 让东西看起来像微缩模型", "u": "F/12-omeFOX21-wc.html", "vid": "omeFOX21-wc", "q": "大的东西饱和度应该怎样处理？为什么？", "a": "要克制，因为大东西会有空气透视。", "t": 100}, {"cat": "F", "ep": "F-13 应对显示器色差", "u": "F/13-240NQ--7xvU.html", "vid": "240NQ--7xvU", "q": "为什么显示器色差对美术和监修者是「生死攸关」？", "a": "他们靠颜色判断画面；检查用的显示器偏色会导致整体判断错误。", "t": 40}, {"cat": "F", "ep": "F-13 应对显示器色差", "u": "F/13-240NQ--7xvU.html", "vid": "240NQ--7xvU", "q": "樱井团队最终如何统一颜色判断？", "a": "把一台显示器放在大家都能看见的地方，从远处目测调整平衡。", "t": 70}, {"cat": "F", "ep": "F-13 应对显示器色差", "u": "F/13-240NQ--7xvU.html", "vid": "240NQ--7xvU", "q": "在黄色照明的办公室里，画面会出什么问题？", "a": "绘图整体会偏蓝；照明应尽量没个性。", "t": 120}, {"cat": "F", "ep": "F-14 动态模糊", "u": "F/14-xAgkRtpAUFI.html", "vid": "xAgkRtpAUFI", "q": "什么是模糊（Blur）？有什么作用？", "a": "运动的残影表现，填补两帧之间，减少逐帧感，增加动感。", "t": 44}, {"cat": "F", "ep": "F-14 动态模糊", "u": "F/14-xAgkRtpAUFI.html", "vid": "xAgkRtpAUFI", "q": "游戏中表现模糊有哪两种方法？", "a": "手绘（如替换贴图）与硬件计算。", "t": 90}, {"cat": "F", "ep": "F-14 动态模糊", "u": "F/14-xAgkRtpAUFI.html", "vid": "xAgkRtpAUFI", "q": "模糊做过头会怎样？怎么应对？", "a": "反而违和、画面模糊难懂；可提供模糊调节选项让玩家按喜好调。", "t": 100}, {"cat": "F", "ep": "F-15 让不存在的东西显得真实", "u": "F/15-bVEPp5n-ysE.html", "vid": "bVEPp5n-ysE", "q": "为什么说游戏世界是「布景」？", "a": "没有质量；不放判定会被穿过，没有程序连掉落都不会，只是多边形组合。", "t": 20}, {"cat": "F", "ep": "F-15 让不存在的东西显得真实", "u": "F/15-bVEPp5n-ysE.html", "vid": "bVEPp5n-ysE", "q": "樱井所说的「表现」是什么？", "a": "让本不存在的东西，感觉就在那里——由画面、声音、程序、参数等综合实现。", "t": 60}, {"cat": "F", "ep": "F-15 让不存在的东西显得真实", "u": "F/15-bVEPp5n-ysE.html", "vid": "bVEPp5n-ysE", "q": "容易被忽视的真实感要素是什么？《大乱斗》怎么做？", "a": "空气流动；环境风让摆动物飘动，爆炸附近产生微风。", "t": 125}, {"cat": "F", "ep": "F-16 最终输出", "u": "F/16-MGPwDINsVbU.html", "vid": "MGPwDINsVbU", "q": "什么是帧缓冲区？", "a": "游戏机生成的图先存放的地方；在其中绘制背景、角色、UI 并做着色与渲染，全部画完再传到画面。", "t": 30}, {"cat": "F", "ep": "F-16 最终输出", "u": "F/16-MGPwDINsVbU.html", "vid": "MGPwDINsVbU", "q": "《DX》与《特别版》的画面有何差别？", "a": "DX 各物体颜色分明；特别版色彩混合、加入反光等，最终输出更好。", "t": 65}, {"cat": "F", "ep": "F-16 最终输出", "u": "F/16-MGPwDINsVbU.html", "vid": "MGPwDINsVbU", "q": "樱井认为什么样的人能大幅提高影像品质？", "a": "拉远视角、控制恰当后处理的「最终输出协调人」。", "t": 125}, {"cat": "F", "ep": "F-17 只为破坏一面墙", "u": "F/17-rV1Vnt1dVlQ.html", "vid": "rV1Vnt1dVlQ", "q": "板面「软塌塌地弯曲」时，樱井给出的指示是什么？", "a": "保持板面的 X 坐标，只在 Y 和 Z 方向做锯齿。", "t": 66}, {"cat": "F", "ep": "F-17 只为破坏一面墙", "u": "F/17-rV1Vnt1dVlQ.html", "vid": "rV1Vnt1dVlQ", "q": "樱井判断 OK 的标准是什么？", "a": "只要真正表现出木板被破坏、品质有保障，即使偏离他的想象也 OK。", "t": 160}, {"cat": "F", "ep": "F-17 只为破坏一面墙", "u": "F/17-rV1Vnt1dVlQ.html", "vid": "rV1Vnt1dVlQ", "q": "多次监修仍不行时怎么办？", "a": "只能决断，按原样产品化——但会后悔，最好清爽完成。", "t": 185}, {"cat": "F", "ep": "F-18 漫画式表现", "u": "F/18-U9lQpn67Wos.html", "vid": "U9lQpn67Wos", "q": "《洛克人 DASH》侧脸的嘴为何适合动画？", "a": "不动下巴只换赛璐珞就能表现，嘴的动作也更易懂。", "t": 50}, {"cat": "F", "ep": "F-18 漫画式表现", "u": "F/18-U9lQpn67Wos.html", "vid": "U9lQpn67Wos", "q": "樱井对「不写实就避免漫画表现」怎么看？", "a": "完全不认同，反而推荐；增加有趣的表现是应该欢迎的。", "t": 100}, {"cat": "F", "ep": "F-18 漫画式表现", "u": "F/18-U9lQpn67Wos.html", "vid": "U9lQpn67Wos", "q": "卡比/胖丁嘴型修改后，哪一种更好？", "a": "实际断面旧版更接近，但作为表现修改后的更好。", "t": 155}, {"cat": "F", "ep": "F-19 用设计立住角色", "u": "F/19-PDjdquhVHU4.html", "vid": "PDjdquhVHU4", "q": "娜可露露的完成版和《KOF XIV》版有什么关系？", "a": "回到经典形象，但保留了红色部分的新花纹等长处。", "t": 40}, {"cat": "F", "ep": "F-19 用设计立住角色", "u": "F/19-PDjdquhVHU4.html", "vid": "PDjdquhVHU4", "q": "樱井立住角色时最重视什么？", "a": "剪影：涂黑也要夸张分明、可辨识、能与他人区分。", "t": 100}, {"cat": "F", "ep": "F-19 用设计立住角色", "u": "F/19-PDjdquhVHU4.html", "vid": "PDjdquhVHU4", "q": "《侍魂》角色的形体有什么特点？", "a": "头部体量大、手脚细却强调到位，变形与张弛出色，与索尼克相近。", "t": 55}, {"cat": "F", "ep": "F-20 监修杂谈：苏菈篇", "u": "F/20-qqjXBzWX3_A.html", "vid": "qqjXBzWX3_A", "q": "前空中攻击姿势不佳时，樱井用了什么方法指示？", "a": "用手办摆出姿势给员工参考，上身扭转增加信息量。", "t": 96}, {"cat": "F", "ep": "F-20 监修杂谈：苏菈篇", "u": "F/20-qqjXBzWX3_A.html", "vid": "qqjXBzWX3_A", "q": "必杀技一定要检查什么？", "a": "地上版与空中版都要检查（音速剑两版姿势差太多）。", "t": 228}, {"cat": "F", "ep": "F-20 监修杂谈：苏菈篇", "u": "F/20-qqjXBzWX3_A.html", "vid": "qqjXBzWX3_A", "q": "空洞堡垒管道的问题是什么？", "a": "同一素材应手前强、远处弱的对比却反过来了，且缺乏张弛。", "t": 400}, {"cat": "G", "ep": "G-1 动作的委托方式", "u": "G/01-fV8xIP480qk.html", "vid": "fV8xIP480qk", "q": "动作列表要写哪些信息？", "a": "全部动作的文字描述、动作长度、攻击发生时间；循环动作标为「循环」。", "t": 50}, {"cat": "G", "ep": "G-1 动作的委托方式", "u": "G/01-fV8xIP480qk.html", "vid": "fV8xIP480qk", "q": "关键姿势是怎么指定的？每个斗士大约多少张？", "a": "用手办摆姿势拍照、调对比、落到规格书；约 70～80 张。", "t": 100}, {"cat": "G", "ep": "G-1 动作的委托方式", "u": "G/01-fV8xIP480qk.html", "vid": "fV8xIP480qk", "q": "为什么规格书只是起点？", "a": "要做好需要大量细节思考；手办的可动范围与游戏模型差很多，要靠设计师努力。", "t": 215}, {"cat": "G", "ep": "G-2 过头才刚好", "u": "G/02-zNBKzLzDKtM.html", "vid": "zNBKzLzDKtM", "q": "樱井如何看待「扭到模型破绽」的动作？", "a": "是好动作；攻击动作几乎不存在过头，反而常常不够。", "t": 15}, {"cat": "G", "ep": "G-2 过头才刚好", "u": "G/02-zNBKzLzDKtM.html", "vid": "zNBKzLzDKtM", "q": "为什么攻击动作要做过头？", "a": "小画面上的小动作，比自己认为 OK 的再夸张才刚好。", "t": 45}, {"cat": "G", "ep": "G-2 过头才刚好", "u": "G/02-zNBKzLzDKtM.html", "vid": "zNBKzLzDKtM", "q": "直线运动有什么技巧？", "a": "冲过头再稍微回来（如卡比针刺的第 3→4 帧）。", "t": 140}, {"cat": "G", "ep": "G-3 攻击动作的拆解", "u": "G/03-LewXWM7HDd8.html", "vid": "LewXWM7HDd8", "q": "攻击动作分为哪四段？", "a": "待机、预备、攻击、收招。", "t": 10}, {"cat": "G", "ep": "G-3 攻击动作的拆解", "u": "G/03-LewXWM7HDd8.html", "vid": "LewXWM7HDd8", "q": "为什么预备动作要在第 1 帧大幅变化？", "a": "立即显示输入被接受，也促使对手立即回避。", "t": 55}, {"cat": "G", "ep": "G-3 攻击动作的拆解", "u": "G/03-LewXWM7HDd8.html", "vid": "LewXWM7HDd8", "q": "委托动作时明示的四点是什么？", "a": "待机姿势、攻击姿势、攻击发生帧、总帧数（到取消为止）。", "t": 165}, {"cat": "G", "ep": "G-4 预备动作要瞬时且有力", "u": "G/04-E8DKndKkHw8.html", "vid": "E8DKndKkHw8", "q": "《大乱斗》的预备动作有什么特点？为什么？", "a": "按下瞬间姿势就大幅改变；重视响应，接受输入就立即反应。", "t": 50}, {"cat": "G", "ep": "G-4 预备动作要瞬时且有力", "u": "G/04-E8DKndKkHw8.html", "vid": "E8DKndKkHw8", "q": "举一个几乎没有预备的攻击例子。", "a": "零装萨姆斯的弱攻击，1 帧就出。", "t": 85}, {"cat": "G", "ep": "G-4 预备动作要瞬时且有力", "u": "G/04-E8DKndKkHw8.html", "vid": "E8DKndKkHw8", "q": "为什么预备不能一味缩短？", "a": "网络对战中蓄力可填补延迟；没有预备，打击缺乏冲击感。", "t": 110}, {"cat": "G", "ep": "G-5 攻击姿势", "u": "G/05-99gdMDF7V2E.html", "vid": "99gdMDF7V2E", "q": "为什么命中瞬间的姿势最重要？", "a": "《大乱斗》命中有顿帧，那一刻的构图最留在脑中。", "t": 30}, {"cat": "G", "ep": "G-5 攻击姿势", "u": "G/05-99gdMDF7V2E.html", "vid": "99gdMDF7V2E", "q": "攻击为什么要跨过中线？", "a": "偏向画面深处或前方，本该打中的也会打不中。", "t": 62}, {"cat": "G", "ep": "G-5 攻击姿势", "u": "G/05-99gdMDF7V2E.html", "vid": "99gdMDF7V2E", "q": "攻击姿势最重要的是什么？", "a": "剪影漂亮——侧面看的游戏中侧面剪影是绝对。", "t": 115}, {"cat": "G", "ep": "G-6 收招决定冲击力", "u": "G/06-cIB0BUe6Ihk.html", "vid": "cIB0BUe6Ihk", "q": "为什么收招最常入眼？", "a": "攻击发生在总时长的 1/3～1/4，剩下全是收招；被看的时间最长。", "t": 65}, {"cat": "G", "ep": "G-6 收招决定冲击力", "u": "G/06-cIB0BUe6Ihk.html", "vid": "cIB0BUe6Ihk", "q": "收招应该怎样表现？", "a": "不只是补间回待机；在给定时间里充分表现攻击，坚持到极限。", "t": 200}, {"cat": "G", "ep": "G-6 收招决定冲击力", "u": "G/06-cIB0BUe6Ihk.html", "vid": "cIB0BUe6Ihk", "q": "取消帧时的姿势要注意什么？", "a": "要恢复到看起来能操作的程度。", "t": 225}, {"cat": "G", "ep": "G-7 夸张以弥补信息损失", "u": "G/07-Ivwt37x-2EU.html", "vid": "Ivwt37x-2EU", "q": "深作欣二导演如何解释夸张的演技？", "a": "多边形角色失去了人类的各种信息，所以必须演得更大。", "t": 40}, {"cat": "G", "ep": "G-7 夸张以弥补信息损失", "u": "G/07-Ivwt37x-2EU.html", "vid": "Ivwt37x-2EU", "q": "角色在画面中的大小如何影响动作？", "a": "角色小或远时动作显得拘谨，需要更大的动作。", "t": 88}, {"cat": "G", "ep": "G-7 夸张以弥补信息损失", "u": "G/07-Ivwt37x-2EU.html", "vid": "Ivwt37x-2EU", "q": "动作捕捉数据可以原样使用吗？", "a": "通常不行，要大幅加工、移动得更大才刚好。", "t": 70}, {"cat": "G", "ep": "G-8 摆姿势的建议", "u": "G/08-LsSF_H-W-w8.html", "vid": "LsSF_H-W-w8", "q": "为什么樱井推荐玩可动手办？", "a": "姿势定格最重要，摆弄立体物能学会怎样定格、什么是好角度。", "t": 35}, {"cat": "G", "ep": "G-8 摆姿势的建议", "u": "G/08-LsSF_H-W-w8.html", "vid": "LsSF_H-W-w8", "q": "列举三条站姿要点。", "a": "避开对称与正面；上身腰腿不成直线（S 曲线）；重心稍偏、双臂不同角度、手腕不直等。", "t": 75}, {"cat": "G", "ep": "G-8 摆姿势的建议", "u": "G/08-LsSF_H-W-w8.html", "vid": "LsSF_H-W-w8", "q": "姿势好坏最终靠什么判断？", "a": "不是理论或诀窍，而是什么让人觉得好。", "t": 140}, {"cat": "G", "ep": "G-9 挤压与缩放", "u": "G/09-Sm0LAm4sJKc.html", "vid": "Sm0LAm4sJKc", "q": "CG 运动的三要素是什么？", "a": "缩放、旋转、平移。", "t": 25}, {"cat": "G", "ep": "G-9 挤压与缩放", "u": "G/09-Sm0LAm4sJKc.html", "vid": "Sm0LAm4sJKc", "q": "挤压与拉伸的前提是什么？", "a": "保持质量：竖压则横伸。", "t": 82}, {"cat": "G", "ep": "G-9 挤压与缩放", "u": "G/09-Sm0LAm4sJKc.html", "vid": "Sm0LAm4sJKc", "q": "为什么卡比不能单纯压扁？", "a": "会缺乏量感，只是个椭圆；要按点阵图那样的量感来做。", "t": 105}, {"cat": "G", "ep": "G-10 受伤动作", "u": "G/10-0xHE3ypX96U.html", "vid": "0xHE3ypX96U", "q": "为什么受伤动作的第 1 帧特别重要？", "a": "有顿帧，看得清楚；要做成与待机截然不同的极端痛苦姿势。", "t": 25}, {"cat": "G", "ep": "G-10 受伤动作", "u": "G/10-0xHE3ypX96U.html", "vid": "0xHE3ypX96U", "q": "《大乱斗》的地面受伤反应有几种？如何组合？", "a": "9 种：上中下（位置）× 小中大（强度）。", "t": 140}, {"cat": "G", "ep": "G-10 受伤动作", "u": "G/10-0xHE3ypX96U.html", "vid": "0xHE3ypX96U", "q": "为什么《大乱斗》难以复用受伤动作？", "a": "体型过于独特，人形也有持剑、盾、武器等变化。", "t": 165}, {"cat": "G", "ep": "G-11 补间的陷阱", "u": "G/11-oFwamE6Hy04.html", "vid": "oFwamE6Hy04", "q": "为什么 2D 搬到 3D 的动作常显得软？", "a": "工具自动补间，中间动作被看到留下印象。", "t": 40}, {"cat": "G", "ep": "G-11 补间的陷阱", "u": "G/11-oFwamE6Hy04.html", "vid": "oFwamE6Hy04", "q": "到达关键帧应该怎么做？", "a": "偏极端：几乎不要中间帧，时间给预备和攻击，预备拉得更大。", "t": 105}, {"cat": "G", "ep": "G-11 补间的陷阱", "u": "G/11-oFwamE6Hy04.html", "vid": "oFwamE6Hy04", "q": "隆的上勾拳在《特别版》中做了哪些调整？", "a": "右前臂往后拉更多；接近原作的 3 个姿势各 1 帧送出；收招不走相同轨迹。", "t": 160}, {"cat": "G", "ep": "G-12 表情动画", "u": "G/12-TUHL7Ex-RH8.html", "vid": "TUHL7Ex-RH8", "q": "《特别版》的表情方针是什么？", "a": "不需要口型同步与细微变化，整体要有活力、夸张。", "t": 36}, {"cat": "G", "ep": "G-12 表情动画", "u": "G/12-TUHL7Ex-RH8.html", "vid": "TUHL7Ex-RH8", "q": "狼的受伤脸修图说明了什么？", "a": "交上来的变化太小；觉得努力了再更大幅地动才对。", "t": 66}, {"cat": "G", "ep": "G-12 表情动画", "u": "G/12-TUHL7Ex-RH8.html", "vid": "TUHL7Ex-RH8", "q": "举两个表情的易错点。", "a": "睁眼时上下都露眼白；上下门牙不咬合。", "t": 80}, {"cat": "G", "ep": "G-13 翻转动作", "u": "G/13-TJDMDxnWU5g.html", "vid": "TJDMDxnWU5g", "q": "什么是翻转动作？", "a": "把姿势和动作做镜像，让左右两侧的角色都朝向镜头。", "t": 20}, {"cat": "G", "ep": "G-13 翻转动作", "u": "G/13-TJDMDxnWU5g.html", "vid": "TJDMDxnWU5g", "q": "翻转动作有什么代价？", "a": "管理麻烦：右拳变左拳、道具换手，左右不对称（持剑）角色不适用。", "t": 60}, {"cat": "G", "ep": "G-13 翻转动作", "u": "G/13-TJDMDxnWU5g.html", "vid": "TJDMDxnWU5g", "q": "为什么 DJ 裤子写 MAXIMUM？", "a": "这组字母左右反转也成立。", "t": 150}, {"cat": "G", "ep": "G-14 动作混合", "u": "G/14-HYHajZ0wBfU.html", "vid": "HYHajZ0wBfU", "q": "动作混合在取消帧中起什么作用？", "a": "把操作产生的动作和取消帧后的动作合成，避免突然切换。", "t": 25}, {"cat": "G", "ep": "G-14 动作混合", "u": "G/14-HYHajZ0wBfU.html", "vid": "HYHajZ0wBfU", "q": "为什么混合不能花太长时间？", "a": "中间动作增加会失去张弛，机械补间也可能破绽。", "t": 100}, {"cat": "G", "ep": "G-14 动作混合", "u": "G/14-HYHajZ0wBfU.html", "vid": "HYHajZ0wBfU", "q": "动作混合在哪类游戏更有用？举例。", "a": "3D 游戏：上下半身分控、地形脚步、状态迁移等。", "t": 140}, {"cat": "G", "ep": "G-15 手指的表现", "u": "G/15-nCvdmQKrjf8.html", "vid": "nCvdmQKrjf8", "q": "什么时候应该斜着握持物体？", "a": "需要配合前臂动作（如挥剑）时。", "t": 30}, {"cat": "G", "ep": "G-15 手指的表现", "u": "G/15-nCvdmQKrjf8.html", "vid": "nCvdmQKrjf8", "q": "处理负荷紧张时手指常被怎么处理？", "a": "固定住看似在动，或做几种手指图案替换。", "t": 66}, {"cat": "G", "ep": "G-15 手指的表现", "u": "G/15-nCvdmQKrjf8.html", "vid": "nCvdmQKrjf8", "q": "关于手指的总原则是什么？", "a": "考虑性价比：省该省的，把处理用在重要处。", "t": 115}, {"cat": "G", "ep": "G-16 时刻意识攻击判定", "u": "G/16-rwwF_4blK-o.html", "vid": "rwwF_4blK-o", "q": "为什么《大乱斗》的攻击判定偏大？", "a": "坐标移动激烈快速，判定小就很难命中、压力大。", "t": 40}, {"cat": "G", "ep": "G-16 时刻意识攻击判定", "u": "G/16-rwwF_4blK-o.html", "vid": "rwwF_4blK-o", "q": "攻击没过中线时，为什么不只靠策划调判定？", "a": "外观与命中会差得更大；连动作位置都不同，破绽更大。", "t": 80}, {"cat": "G", "ep": "G-16 时刻意识攻击判定", "u": "G/16-rwwF_4blK-o.html", "vid": "rwwF_4blK-o", "q": "为什么挥剑时会在稍挥出的位置才出判定？", "a": "判定时有顿帧，那一刻要是攻击感强的姿势。", "t": 115}, {"cat": "G", "ep": "G-17 骨骼的局限", "u": "G/17-q77TZaISg1Y.html", "vid": "q77TZaISg1Y", "q": "FK 和 IK 的区别是什么？", "a": "FK 由根部依次带动末端；IK 拖动末端（手）位置，反算肩肘角度。", "t": 40}, {"cat": "G", "ep": "G-17 骨骼的局限", "u": "G/17-q77TZaISg1Y.html", "vid": "q77TZaISg1Y", "q": "樱井希望骨骼能做到什么？", "a": "超过 180°、弯过笔直，让动画更有活力。", "t": 95}, {"cat": "G", "ep": "G-17 骨骼的局限", "u": "G/17-q77TZaISg1Y.html", "vid": "q77TZaISg1Y", "q": "为什么《大乱斗》没实现？", "a": "处理负荷，以及需要动作设计师有卡通动画感；反向关节也会让日常使用困难。", "t": 135}, {"cat": "G", "ep": "G-18 双轴旋转", "u": "G/18-Mh7nTn9_r40.html", "vid": "Mh7nTn9_r40", "q": "为什么不能只用 Y 轴转头？", "a": "看起来很机械；非机械的东西要意识双轴扭转。", "t": 40}, {"cat": "G", "ep": "G-18 双轴旋转", "u": "G/18-Mh7nTn9_r40.html", "vid": "Mh7nTn9_r40", "q": "转头的两种双轴组合是什么？", "a": "低头再转（X+Y）、侧倾再转（Z+Y）。", "t": 65}, {"cat": "G", "ep": "G-18 双轴旋转", "u": "G/18-Mh7nTn9_r40.html", "vid": "Mh7nTn9_r40", "q": "让旋转更进一步的技巧有哪些？", "a": "错开两轴时机、偶尔加反动、联动肩与锁骨；终点相同但过程不同带来不同性格。", "t": 130}, {"cat": "H", "ep": "H-1 让特效「脆」起来", "u": "H/01-kcYDrtRvuKg.html", "vid": "kcYDrtRvuKg", "q": "颜色加算和半透明有什么不同？", "a": "加算是把颜色加到背景上，结果趋近白色；不是趋近特效原色。", "t": 40}, {"cat": "H", "ep": "H-1 让特效「脆」起来", "u": "H/01-kcYDrtRvuKg.html", "vid": "kcYDrtRvuKg", "q": "过度依赖加算特效有哪些问题？", "a": "太朦胧、失去张弛、太亮、只在暗背景显眼。", "t": 70}, {"cat": "H", "ep": "H-1 让特效「脆」起来", "u": "H/01-kcYDrtRvuKg.html", "vid": "kcYDrtRvuKg", "q": "樱井推荐怎么做？", "a": "以清脆的多边形/实色特效为主体，与加算并用，并混入暗色形成对比。", "t": 100}, {"cat": "H", "ep": "H-2 让角色从特效中凸显", "u": "H/02-0ucvynuIe-o.html", "vid": "0ucvynuIe-o", "q": "2D 和 3D 游戏处理特效遮挡有何不同？", "a": "2D 提高角色显示优先级即可；3D 强行优先会像视差出错，印象不好。", "t": 35}, {"cat": "H", "ep": "H-2 让角色从特效中凸显", "u": "H/02-0ucvynuIe-o.html", "vid": "0ucvynuIe-o", "q": "舞台中央特效的「内外高度不同」有什么作用？", "a": "内侧更低，不会挡住中央的角色。", "t": 88}, {"cat": "H", "ep": "H-2 让角色从特效中凸显", "u": "H/02-0ucvynuIe-o.html", "vid": "0ucvynuIe-o", "q": "除了改特效形状，还有什么让角色显眼的方法？", "a": "给角色模型描边。", "t": 106}, {"cat": "H", "ep": "H-3 闪光、爆炎与烟", "u": "H/03-ZDopYzDX-Jg.html", "vid": "ZDopYzDX-Jg", "q": "《大乱斗》爆炸的四个阶段是什么？", "a": "闪光、爆炎、黑烟、收束。", "t": 50}, {"cat": "H", "ep": "H-3 闪光、爆炎与烟", "u": "H/03-ZDopYzDX-Jg.html", "vid": "ZDopYzDX-Jg", "q": "闪光为什么要混入黑色？", "a": "纯白在白背景上看不见。", "t": 75}, {"cat": "H", "ep": "H-3 闪光、爆炎与烟", "u": "H/03-ZDopYzDX-Jg.html", "vid": "ZDopYzDX-Jg", "q": "为什么爆炸不能太短？", "a": "太短没有手感；收束也是「这里发生过爆炸」的通知。", "t": 130}, {"cat": "H", "ep": "H-4 慢动作下的视觉特效", "u": "H/04-353K_6kPqeE.html", "vid": "353K_6kPqeE", "q": "本集为什么用慢动作、关掉背景录特效？", "a": "特效一瞬间传达大量信息难以看全；仔细观察是成功的捷径，也能看清动作。", "t": 15}, {"cat": "H", "ep": "H-4 慢动作下的视觉特效", "u": "H/04-353K_6kPqeE.html", "vid": "353K_6kPqeE", "q": "关掉特效后的游戏画面给人什么感觉？", "a": "非常朴素——同一游戏会因特效感觉大不相同。", "t": 672}, {"cat": "H", "ep": "H-4 慢动作下的视觉特效", "u": "H/04-353K_6kPqeE.html", "vid": "353K_6kPqeE", "q": "观看展示时可以对照哪些前几集的要点？", "a": "闪光→爆炎→烟的顺序、清脆实色形状、混入暗色、火花与冲击波等点缀。", "t": 40}, {"cat": "H", "ep": "H-5 画面震动", "u": "H/05-2JXR7IASSog.html", "vid": "2JXR7IASSog", "q": "两种画面震动方法各有什么缺点？", "a": "移动摄像机：远景几乎不动；移动绘制后画面：边缘可能露出黑边。", "t": 54}, {"cat": "H", "ep": "H-5 画面震动", "u": "H/05-2JXR7IASSog.html", "vid": "2JXR7IASSog", "q": "《大乱斗》的大中小震动只是缩放吗？", "a": "不是，震动模式本身不同：小只纵震，中加入横震。", "t": 108}, {"cat": "H", "ep": "H-5 画面震动", "u": "H/05-2JXR7IASSog.html", "vid": "2JXR7IASSog", "q": "为什么要按镜头远近调整震动幅度？", "a": "画角不同时同样的震动观感不同，例如平面世界画角窄会震得过大。", "t": 153}, {"cat": "H", "ep": "H-6 命中标记（Hit Marks）", "u": "H/06-B-P4ysHSjCg.html", "vid": "B-P4ysHSjCg", "q": "为什么《大乱斗》的命中位置较难处理？", "a": "镜头拉远，攻击判定偏大，判定重叠处与视觉位置关系难把握。", "t": 120}, {"cat": "H", "ep": "H-6 命中标记（Hit Marks）", "u": "H/06-B-P4ysHSjCg.html", "vid": "B-P4ysHSjCg", "q": "命中标记为什么要「做出明度差」？", "a": "只用亮色在亮背景下不显眼，配置暗色（如铺黑）后明暗背景都看得清。", "t": 216}, {"cat": "H", "ep": "H-6 命中标记（Hit Marks）", "u": "H/06-B-P4ysHSjCg.html", "vid": "B-P4ysHSjCg", "q": "《特别版》受击方在 hit stop 中操作时出现的特效表示什么？", "a": "吹飞方向：受击方能稍微改变矢量，特效显示该方向。", "t": 264}, {"cat": "H", "ep": "H-7 广告牌（Billboard）", "u": "H/07-_o29OOOarPY.html", "vid": "_o29OOOarPY", "q": "什么是广告牌？", "a": "永远正对镜头的平面物体，大多由两个多边形组成。", "t": 5}, {"cat": "H", "ep": "H-7 广告牌（Billboard）", "u": "H/07-_o29OOOarPY.html", "vid": "_o29OOOarPY", "q": "为什么特效常用广告牌？", "a": "2D 物体绘制成本低，适合闪光等无实体的特效。", "t": 70}, {"cat": "H", "ep": "H-7 广告牌（Billboard）", "u": "H/07-_o29OOOarPY.html", "vid": "_o29OOOarPY", "q": "Y 轴广告牌用于特效有什么风险？", "a": "只绕 Y 轴面向镜头，从某些角度看图会显得太瘦。", "t": 98}, {"cat": "H", "ep": "H-8 刀光（风切）", "u": "H/08-X0GdWg2Q7z8.html", "vid": "X0GdWg2Q7z8", "q": "剑的风切两种做法是什么？", "a": "沿剑轨迹生成多边形（扇形，大多数）；放置一枚板多边形瞬间显示（1 帧挥完时）。", "t": 50}, {"cat": "H", "ep": "H-8 刀光（风切）", "u": "H/08-X0GdWg2Q7z8.html", "vid": "X0GdWg2Q7z8", "q": "为什么经常要为风切修改动作？", "a": "侧面看的画面中水平斩的轨迹几乎看不见。", "t": 85}, {"cat": "H", "ep": "H-8 刀光（风切）", "u": "H/08-X0GdWg2Q7z8.html", "vid": "X0GdWg2Q7z8", "q": "板多边形的风切只显示一瞬，为什么还能被看到？", "a": "命中时有顿帧。", "t": 120}, {"cat": "H", "ep": "H-9 特效的尺度要对", "u": "H/09-rXwo0qcKJDk.html", "vid": "rXwo0qcKJDk", "q": "大火焰为什么常看起来像蜡烛？", "a": "密度（信息量）不够。", "t": 30}, {"cat": "H", "ep": "H-9 特效的尺度要对", "u": "H/09-rXwo0qcKJDk.html", "vid": "rXwo0qcKJDk", "q": "让火焰接近合适尺寸的两种方法是什么？", "a": "增加循环次数；用更小、更细的粒子。", "t": 75}, {"cat": "H", "ep": "H-9 特效的尺度要对", "u": "H/09-rXwo0qcKJDk.html", "vid": "rXwo0qcKJDk", "q": "特效为什么不必画得太细？", "a": "特效一直在动，粗犷、快速更重要；太细还会吃贴图内存。", "t": 88}, {"cat": "H", "ep": "H-10 闪烁效果", "u": "H/10-Mmw39T_dBLI.html", "vid": "Mmw39T_dBLI", "q": "画面闪光与角色闪光的作用分别是什么？", "a": "画面闪光用大面积增加手感；角色闪光强调状态变化。", "t": 40}, {"cat": "H", "ep": "H-10 闪烁效果", "u": "H/10-Mmw39T_dBLI.html", "vid": "Mmw39T_dBLI", "q": "颜色加算闪烁有哪些问题？如何解决？", "a": "均匀加色降低对比，白闪在亮画面不显眼；混入暗色、加阴影。", "t": 120}, {"cat": "H", "ep": "H-10 闪烁效果", "u": "H/10-Mmw39T_dBLI.html", "vid": "Mmw39T_dBLI", "q": "白色和黄色闪烁分别表示什么？", "a": "白：无敌时间；黄：被投后不能被抓的时间。", "t": 190}, {"cat": "H", "ep": "H-11 粒子特效的局限", "u": "H/11-jAQv4PTQvQE.html", "vid": "jAQv4PTQvQE", "q": "节省粒子数量的方法有哪些？", "a": "寿命短（用速度补偿）、多个画在一枚板上、错开时机、错开位置、每枚画大一点。", "t": 90}, {"cat": "H", "ep": "H-11 粒子特效的局限", "u": "H/11-jAQv4PTQvQE.html", "vid": "jAQv4PTQvQE", "q": "初代卡比的打倒敌人特效是怎么做的？", "a": "手工逐帧摆放星星，只有座标数据，没有移动程序。", "t": 205}, {"cat": "H", "ep": "H-11 粒子特效的局限", "u": "H/11-jAQv4PTQvQE.html", "vid": "jAQv4PTQvQE", "q": "吸入粒子为什么混入黑白点？", "a": "让任何背景色上都看得见。", "t": 242}, {"cat": "I", "ep": "I-1 让节奏配合游戏", "u": "I/01-hGp2Jw5dLH8.html", "vid": "hGp2Jw5dLH8", "q": "BPM 60 和 120 大约对应什么？", "a": "每秒一拍约 60，每秒两拍约 120。", "t": 60}, {"cat": "I", "ep": "I-1 让节奏配合游戏", "u": "I/01-hGp2Jw5dLH8.html", "vid": "hGp2Jw5dLH8", "q": "《大乱斗》对战曲的节奏大约多少？", "a": "多为 130～170，少数约 200。", "t": 85}, {"cat": "I", "ep": "I-1 让节奏配合游戏", "u": "I/01-hGp2Jw5dLH8.html", "vid": "hGp2Jw5dLH8", "q": "《DQ1》的地下城音乐有什么机关？", "a": "越往深处，音乐节奏越慢。", "t": 120}, {"cat": "I", "ep": "I-2 平衡效果音", "u": "I/02-qKjD5qbLUeI.html", "vid": "qKjD5qbLUeI", "q": "决定效果音大小的原则是什么？", "a": "与玩家关系越大的声音越大，而不是只看声源大小。", "t": 50}, {"cat": "I", "ep": "I-2 平衡效果音", "u": "I/02-qKjD5qbLUeI.html", "vid": "qKjD5qbLUeI", "q": "《大乱斗》中音量最大的是什么声音？为什么？", "a": "击坠声：决定博弈和胜负的大事件。", "t": 70}, {"cat": "I", "ep": "I-2 平衡效果音", "u": "I/02-qKjD5qbLUeI.html", "vid": "qKjD5qbLUeI", "q": "脚步声要注意什么？", "a": "做出变化，避免同一声音连续太机械；3D 游戏可按地面材质变化、优先度更高。", "t": 215}, {"cat": "I", "ep": "I-3 在多种环境中试听", "u": "I/03-WUy4lTUhj80.html", "vid": "WUy4lTUhj80", "q": "樱井检查声音的三个环境是什么？", "a": "耳机、电脑音箱、廉价电视。", "t": 10}, {"cat": "I", "ep": "I-3 在多种环境中试听", "u": "I/03-WUy4lTUhj80.html", "vid": "WUy4lTUhj80", "q": "为什么廉价电视特别重要？", "a": "低音几乎没有，但它最普及、最多人用。", "t": 30}, {"cat": "I", "ep": "I-3 在多种环境中试听", "u": "I/03-WUy4lTUhj80.html", "vid": "WUy4lTUhj80", "q": "为什么不能只用录音室大喇叭收尾？", "a": "在那里细腻的声音，在民用喇叭上可能完全听不好。", "t": 50}, {"cat": "I", "ep": "I-4 游戏音乐与环境音", "u": "I/04-t_tRnBj9tqc.html", "vid": "t_tRnBj9tqc", "q": "为什么现代游戏音乐不那么突出？", "a": "画面进化、视觉信息增多，写实画面还需要大量环境音，音乐太突出就不合适。", "t": 90}, {"cat": "I", "ep": "I-4 游戏音乐与环境音", "u": "I/04-t_tRnBj9tqc.html", "vid": "t_tRnBj9tqc", "q": "曲子太多有什么问题？", "a": "记不住、难嗨。", "t": 130}, {"cat": "I", "ep": "I-4 游戏音乐与环境音", "u": "I/04-t_tRnBj9tqc.html", "vid": "t_tRnBj9tqc", "q": "樱井常用的音乐策略是什么？", "a": "做主题曲，再把改编版用于各种场景。", "t": 145}, {"cat": "I", "ep": "I-5 虚构与写实的声音", "u": "I/05-6Ns03q8noEA.html", "vid": "6Ns03q8noEA", "q": "《街霸 2》升龙拳的声音体现了什么？", "a": "夸张的声音文化，像昭和黑帮电影；真实声音反而不会被接受。", "t": 40}, {"cat": "I", "ep": "I-5 虚构与写实的声音", "u": "I/05-6Ns03q8noEA.html", "vid": "6Ns03q8noEA", "q": "完全写实的打击声有什么问题？", "a": "打人只有「啪」，不够有手感；格斗游戏本就和真实格斗相距甚远。", "t": 77}, {"cat": "I", "ep": "I-5 虚构与写实的声音", "u": "I/05-6Ns03q8noEA.html", "vid": "6Ns03q8noEA", "q": "写实声音的好处是什么？举例。", "a": "能补足信息、赋予意义：《我的世界》的方块靠声音有了木石的重量。", "t": 130}, {"cat": "I", "ep": "I-6 语音录制", "u": "I/06-C3ANiCI1Em4.html", "vid": "C3ANiCI1Em4", "q": "《大乱斗》每个斗士的语音录制大约多长？", "a": "约 1 小时，含影片台词也不到 2 小时。", "t": 30}, {"cat": "I", "ep": "I-6 语音录制", "u": "I/06-C3ANiCI1Em4.html", "vid": "C3ANiCI1Em4", "q": "为什么《大乱斗》台词偏短、频率低？", "a": "长台词和频繁说话主张太强，会降低沉浸感。", "t": 130}, {"cat": "I", "ep": "I-6 语音录制", "u": "I/06-C3ANiCI1Em4.html", "vid": "C3ANiCI1Em4", "q": "海外语音由谁主导？", "a": "NOA（任天堂美国）和 NOE（任天堂欧洲），以日本录音为基础。", "t": 210}, {"cat": "I", "ep": "I-7 音乐的改编", "u": "I/07-qahwb7_67f0.html", "vid": "qahwb7_67f0", "q": "改编要点中关于时长的要求是什么？", "a": "限时 2 分（《特别版》2 分半）内结束，刚好听到一点循环开头。", "t": 95}, {"cat": "I", "ep": "I-7 音乐的改编", "u": "I/07-qahwb7_67f0.html", "vid": "qahwb7_67f0", "q": "为什么樱井的监修要经过声音导演？", "a": "他感觉上懂但没有音乐专业术语，通过声音导演转达最好。", "t": 175}, {"cat": "I", "ep": "I-7 音乐的改编", "u": "I/07-qahwb7_67f0.html", "vid": "qahwb7_67f0", "q": "樱井改编时最看重什么？", "a": "主旋律与原曲相同，哼出来大致一样，保持同一性。", "t": 210}, {"cat": "I", "ep": "I-8 原曲永远是对的", "u": "I/08-2iWqCSO98jU.html", "vid": "2iWqCSO98jU", "q": "《雅典娜》改编的误解是什么？", "a": "玩家听来主旋律是 A，乐理上却是 B；原作中听到的才是正确的。", "t": 90}, {"cat": "I", "ep": "I-8 原曲永远是对的", "u": "I/08-2iWqCSO98jU.html", "vid": "2iWqCSO98jU", "q": "《超能力战士》英语版在《大乱斗》中怎么处理？为什么？", "a": "第一段人声、第二段器乐、第三段人声回归；因为原作第一段后切换为内置音源。", "t": 240}, {"cat": "I", "ep": "I-8 原曲永远是对的", "u": "I/08-2iWqCSO98jU.html", "vid": "2iWqCSO98jU", "q": "本集的核心原则是什么？", "a": "原曲永远是对的，不要损害玩家各自的体验。", "t": 380}, {"cat": "I", "ep": "I-9 起音要强，余响要轻", "u": "I/09--nWjT49-cds.html", "vid": "-nWjT49-cds", "q": "为什么《大乱斗》的命中音要起音强？", "a": "立刻返回攻击反应，且在声音洪流中得到手感。", "t": 70}, {"cat": "I", "ep": "I-9 起音要强，余响要轻", "u": "I/09--nWjT49-cds.html", "vid": "-nWjT49-cds", "q": "余响太长有什么问题？", "a": "下一个音响起时糊在一起，连打感消失，听不清起点。", "t": 110}, {"cat": "I", "ep": "I-9 起音要强，余响要轻", "u": "I/09--nWjT49-cds.html", "vid": "-nWjT49-cds", "q": "强攻击的命中音理想上何时结束主要部分？", "a": "在顿帧（画面停住）期间结束。", "t": 150}, {"cat": "I", "ep": "I-10 如何对效果音下指示", "u": "I/10-B9CokyQ2Tes.html", "vid": "B9CokyQ2Tes", "q": "樱井给效果音下指示的方法有哪些？", "a": "具体表达（如起音强）、人人都知道的比喻、相似声音的视频链接。", "t": 40}, {"cat": "I", "ep": "I-10 如何对效果音下指示", "u": "I/10-B9CokyQ2Tes.html", "vid": "B9CokyQ2Tes", "q": "为什么尽量避免拟声词？例外是什么？", "a": "文字中的拟声词传达不了脑中的声音；但声音负责人说偶尔有拟声词能增加线索。", "t": 90}, {"cat": "I", "ep": "I-10 如何对效果音下指示", "u": "I/10-B9CokyQ2Tes.html", "vid": "B9CokyQ2Tes", "q": "什么情况下即使和他想象不同也 OK？", "a": "只要扎实地合乎游戏目的。", "t": 130}, {"cat": "I", "ep": "I-11 环境音的平衡", "u": "I/11-jAgi6Uk1CU0.html", "vid": "jAgi6Uk1CU0", "q": "环境音在优先度中处于什么位置？", "a": "最低：太响会盖住关键效果音。", "t": 40}, {"cat": "I", "ep": "I-11 环境音的平衡", "u": "I/11-jAgi6Uk1CU0.html", "vid": "jAgi6Uk1CU0", "q": "为什么环境音仍很重要？", "a": "好音箱环境下需要它；停手时死寂没氛围；主观/越肩视角要身临其境。", "t": 70}, {"cat": "I", "ep": "I-11 环境音的平衡", "u": "I/11-jAgi6Uk1CU0.html", "vid": "jAgi6Uk1CU0", "q": "环境音与一般效果音在风格上有何不同？", "a": "一般效果音需夸张，环境音可以相当写实，卡通风游戏也行。", "t": 85}, {"cat": "I", "ep": "I-12 用其他曲子作参考", "u": "I/12-heFZ6qQXfDw.html", "vid": "heFZ6qQXfDw", "q": "用现有曲作参考有什么好处？", "a": "给作曲家相当具体的线索。", "t": 25}, {"cat": "I", "ep": "I-12 用其他曲子作参考", "u": "I/12-heFZ6qQXfDw.html", "vid": "heFZ6qQXfDw", "q": "用现有曲作参考有哪些危险？", "a": "导演被支配不接受其他；作曲家被支配难做「相似但不同」；不清楚该改哪里而迷失目标。", "t": 50}, {"cat": "I", "ep": "I-12 用其他曲子作参考", "u": "I/12-heFZ6qQXfDw.html", "vid": "heFZ6qQXfDw", "q": "《俺之尸》的「花」是怎么用进游戏的？", "a": "企划者增田直接与版权方谈判，使用原曲。", "t": 140}, {"cat": "I", "ep": "I-13 红白机与 NES 的音源", "u": "I/13-eyQSb_tC0Fg.html", "vid": "eyQSb_tC0Fg", "q": "红白机内置哪 5 个声道？", "a": "方波 ×2、三角波 ×1、噪声 ×1、DPCM ×1。", "t": 25}, {"cat": "I", "ep": "I-13 红白机与 NES 的音源", "u": "I/13-eyQSb_tC0Fg.html", "vid": "eyQSb_tC0Fg", "q": "为什么 DPCM 在初中期很少用？", "a": "采样吃容量；后期容量提升才大幅进化。", "t": 165}, {"cat": "I", "ep": "I-13 红白机与 NES 的音源", "u": "I/13-eyQSb_tC0Fg.html", "vid": "eyQSb_tC0Fg", "q": "为什么一些游戏日美音乐不同？", "a": "海外没有磁碟机，NES 删除了卡带扩展音源的针脚，不能用扩展音源芯片。", "t": 230}, {"cat": "I", "ep": "I-14 没有哪部名作的声音是差的", "u": "I/14-5fqTlWgfCL0.html", "vid": "5fqTlWgfCL0", "q": "樱井的结论是什么？", "a": "没有哪部名作的声音是差的。", "t": 18}, {"cat": "I", "ep": "I-14 没有哪部名作的声音是差的", "u": "I/14-5fqTlWgfCL0.html", "vid": "5fqTlWgfCL0", "q": "「画面差的名作」与「声音差的名作」有何区别？", "a": "前者存在，后者他一个也想不到。", "t": 54}, {"cat": "I", "ep": "I-14 没有哪部名作的声音是差的", "u": "I/14-5fqTlWgfCL0.html", "vid": "5fqTlWgfCL0", "q": "这个规则有哪些例外情况？", "a": "很早期完全无声的游戏；手游、静音玩的掌机、环境嘈杂时。", "t": 112}, {"cat": "J", "ep": "J-1 易懂与风格", "u": "J/01-UjW_TTNtXEM.html", "vid": "UjW_TTNtXEM", "q": "为什么说易懂和风格可能对立？举例。", "a": "《女神异闻录》UI 风格首屈一指，但一眼难懂、难说整齐。", "t": 60}, {"cat": "J", "ep": "J-1 易懂与风格", "u": "J/01-UjW_TTNtXEM.html", "vid": "UjW_TTNtXEM", "q": "判断 UI 好坏的标准是什么？", "a": "不是单纯好懂与否，而是是否合乎该游戏的目的。", "t": 100}, {"cat": "J", "ep": "J-1 易懂与风格", "u": "J/01-UjW_TTNtXEM.html", "vid": "UjW_TTNtXEM", "q": "列举三个菜单应下功夫的地方。", "a": "视线诱导、要素大小、窗口关联、亮度饱和度、字体（任选三）。", "t": 150}, {"cat": "J", "ep": "J-2 文字大小", "u": "J/02-W1ubngQNJpw.html", "vid": "W1ubngQNJpw", "q": "日语与英语在文本空间上有什么不同？", "a": "日语一字信息多、字需较大但句子短；英语字母小也能认但句子长。", "t": 40}, {"cat": "J", "ep": "J-2 文字大小", "u": "J/02-W1ubngQNJpw.html", "vid": "W1ubngQNJpw", "q": "什么样的布局会导致字太小？", "a": "只以英语为前提、对文本变化没有灵活性的布局。", "t": 75}, {"cat": "J", "ep": "J-2 文字大小", "u": "J/02-W1ubngQNJpw.html", "vid": "W1ubngQNJpw", "q": "字号过大有什么副作用？", "a": "酷感（时尚感）会减少。", "t": 135}, {"cat": "J", "ep": "J-3 现代的便利功能（设置项）", "u": "J/03-j2BX4yw8Z4Y.html", "vid": "j2BX4yw8Z4Y", "q": "什么是无障碍（Accessibility）？", "a": "追求利用的方便与便利的设计，也让有障碍的人能充分操作。", "t": 40}, {"cat": "J", "ep": "J-3 现代的便利功能（设置项）", "u": "J/03-j2BX4yw8Z4Y.html", "vid": "j2BX4yw8Z4Y", "q": "《最后生还者》怎么防止玩家误开降低难度的选项？", "a": "战斗无障碍项目先上锁，需要多一步「解锁」才能开。", "t": 305}, {"cat": "J", "ep": "J-3 现代的便利功能（设置项）", "u": "J/03-j2BX4yw8Z4Y.html", "vid": "j2BX4yw8Z4Y", "q": "为什么如今需要丰富的设置？", "a": "手柄已不简单，玩家经验与价值观多样，需要按喜好调整。", "t": 640}, {"cat": "J", "ep": "J-4 读盘画面", "u": "J/04-JKV-30FD6NY.html", "vid": "JKV-30FD6NY", "q": "初代《生化危机》的开门演出为什么是好例子？", "a": "必要的读取时间与必然的演出完美契合。", "t": 45}, {"cat": "J", "ep": "J-4 读盘画面", "u": "J/04-JKV-30FD6NY.html", "vid": "JKV-30FD6NY", "q": "为什么现在应该显示读取标志？", "a": "讲求速度，单纯等待不受欢迎；显示在读取更容易让人接受。", "t": 78}, {"cat": "J", "ep": "J-4 读盘画面", "u": "J/04-JKV-30FD6NY.html", "vid": "JKV-30FD6NY", "q": "为什么不要依赖演出来掩盖读取？", "a": "开发中与完成时读取时间不同（优化后更短）。", "t": 105}, {"cat": "J", "ep": "J-5 文字的强调", "u": "J/05-bZSNYX5CVpw.html", "vid": "bZSNYX5CVpw", "q": "文字演出可以控制哪些方面？", "a": "大小、颜色、动画、字体。", "t": 10}, {"cat": "J", "ep": "J-5 文字的强调", "u": "J/05-bZSNYX5CVpw.html", "vid": "bZSNYX5CVpw", "q": "为什么要让翻译者能直接调整脚本？", "a": "各语言合适的强调方法不同，最好由各国母语者连演出一起考虑。", "t": 70}, {"cat": "J", "ep": "J-5 文字的强调", "u": "J/05-bZSNYX5CVpw.html", "vid": "bZSNYX5CVpw", "q": "什么是「漫符」？", "a": "人物旁的汗珠、青筋等现实中不存在、作为符号画出的情感表现。", "t": 95}, {"cat": "J", "ep": "J-6 菜单决定世界观", "u": "J/06-pivfg2DrFfY.html", "vid": "pivfg2DrFfY", "q": "改变 UI 与字体能带来什么？", "a": "即使游戏性和内容相同，也能改变目标人群与世界观印象。", "t": 10}, {"cat": "J", "ep": "J-6 菜单决定世界观", "u": "J/06-pivfg2DrFfY.html", "vid": "pivfg2DrFfY", "q": "为什么说换字体「轻松」未必恰当？", "a": "有时要从零做整套字体，还需配合背景、框、图标。", "t": 70}, {"cat": "J", "ep": "J-6 菜单决定世界观", "u": "J/06-pivfg2DrFfY.html", "vid": "pivfg2DrFfY", "q": "「为世界打包」是什么意思？", "a": "字体和 UI 包裹着游戏世界，决定玩家对世界的第一印象。", "t": 95}, {"cat": "J", "ep": "J-7 给游戏做色彩分区", "u": "J/07-CWvLMK4OKko.html", "vid": "CWvLMK4OKko", "q": "《特别版》的菜单怎么分色？", "a": "「大乱斗」以红为基调，「命魂」以绿为基调，子菜单沿用。", "t": 25}, {"cat": "J", "ep": "J-7 给游戏做色彩分区", "u": "J/07-CWvLMK4OKko.html", "vid": "CWvLMK4OKko", "q": "菜单色彩分区有什么风险？", "a": "涂满颜色可能显得面向低龄；要看游戏调性。", "t": 45}, {"cat": "J", "ep": "J-7 给游戏做色彩分区", "u": "J/07-CWvLMK4OKko.html", "vid": "CWvLMK4OKko", "q": "为什么菜单中的大幅角色画反而有利？", "a": "图像会被刷进记忆，找图比读字快得多、更直觉。", "t": 100}, {"cat": "J", "ep": "J-8 重要的东西就做大", "u": "J/08-va8wt2yGviY.html", "vid": "va8wt2yGviY", "q": "樱井的菜单为什么按重要度改变图标大小？", "a": "用大小表示优先级，引导玩家访问常用/重要的模式。", "t": 36}, {"cat": "J", "ep": "J-8 重要的东西就做大", "u": "J/08-va8wt2yGviY.html", "vid": "va8wt2yGviY", "q": "GameCube 手柄怎样体现同样的思想？", "a": "A 键大、X/Y 键小，看和摸都知道最该按哪个。", "t": 54}, {"cat": "J", "ep": "J-8 重要的东西就做大", "u": "J/08-va8wt2yGviY.html", "vid": "va8wt2yGviY", "q": "这种做法有哪些缺点？", "a": "损失通用性，选项等价时难操作；翻译成长语言时文字易溢出。", "t": 90}, {"cat": "J", "ep": "J-9 我想快点选！", "u": "J/09--_3ZnSiwlnc.html", "vid": "-_3ZnSiwlnc", "q": "樱井多次向任天堂提议的手柄功能是什么？", "a": "滚轮（飞梭 / jog dial），用来快速选择菜单等。", "t": 22}, {"cat": "J", "ep": "J-9 我想快点选！", "u": "J/09--_3ZnSiwlnc.html", "vid": "-_3ZnSiwlnc", "q": "为什么他希望滚轮有「咔哒」的段落感？", "a": "游戏是玩乐，有手感会让操作更有实在感。", "t": 76}, {"cat": "J", "ep": "J-9 我想快点选！", "u": "J/09--_3ZnSiwlnc.html", "vid": "-_3ZnSiwlnc", "q": "本集真正想强调什么？难点又是什么？", "a": "重新审视理所当然的菜单/UI 操作；难点是只为熟手准备的捷径会降低普适性。", "t": 130}, {"cat": "J", "ep": "J-10 让玩家跳过，让玩家暂停", "u": "J/10-Y4-eS6Ezui8.html", "vid": "Y4-eS6Ezui8", "q": "「跳过后玩家看不懂剧情」这一顾虑为何不成立？", "a": "即使没有存档，玩家也不一定是第一次看；而且不能跳过本身就是不便。", "t": 36}, {"cat": "J", "ep": "J-10 让玩家跳过，让玩家暂停", "u": "J/10-Y4-eS6Ezui8.html", "vid": "Y4-eS6Ezui8", "q": "对于因规定不能跳过的公司标志，樱井怎么看？", "a": "那已不流行；制定规定的人也应以可跳过为前提。", "t": 62}, {"cat": "J", "ep": "J-10 让玩家跳过，让玩家暂停", "u": "J/10-Y4-eS6Ezui8.html", "vid": "Y4-eS6Ezui8", "q": "除了跳过，过场影片还必须具备什么？为什么？", "a": "必须能暂停；来电、来客、饭好了等停手理由太多。", "t": 81}, {"cat": "J", "ep": "J-11 按键设置", "u": "J/11-8nfMt4oG6hg.html", "vid": "8nfMt4oG6hg", "q": "为什么樱井不用「直接按下要换的键」的方式？", "a": "键位画面也是菜单，需要退出键；按退出键时可能被当作要改键。", "t": 80}, {"cat": "J", "ep": "J-11 按键设置", "u": "J/11-8nfMt4oG6hg.html", "vid": "8nfMt4oG6hg", "q": "《大乱斗》如何让客人多时也方便？", "a": "把按键设置记在名字里，对战时选名字即套用，还可存进手柄带走。", "t": 108}, {"cat": "J", "ep": "J-11 按键设置", "u": "J/11-8nfMt4oG6hg.html", "vid": "8nfMt4oG6hg", "q": "为什么游戏内仍需要按键设置，即使 Switch 系统能换键？", "a": "系统换键会影响所有软件，确认键差异等问题只能靠游戏内设置应对。", "t": 160}, {"cat": "J", "ep": "J-12 推进文字", "u": "J/12-CkXSIUX5l_s.html", "vid": "CkXSIUX5l_s", "q": "樱井用什么比喻说明文字和过场推进的差别？", "a": "翻书和看电影的差别。", "t": 49}, {"cat": "J", "ep": "J-12 推进文字", "u": "J/12-CkXSIUX5l_s.html", "vid": "CkXSIUX5l_s", "q": "他推荐了哪两种做法？", "a": "让台词可逐句跳过/快速推进；或让玩家边玩边听对话。", "t": 78}, {"cat": "J", "ep": "J-12 推进文字", "u": "J/12-CkXSIUX5l_s.html", "vid": "CkXSIUX5l_s", "q": "为什么说快速消费已是现代文化？", "a": "影像内容看不完，倍速播放普及，大家想用最少时间享受最多。", "t": 118}, {"cat": "J", "ep": "J-13 给菜单加上说明文字", "u": "J/13-mWIbb1l7Wlw.html", "vid": "mWIbb1l7Wlw", "q": "写帮助文字时樱井最在意的规则是什么？", "a": "绝不用和菜单项相同的词来说明。", "t": 56}, {"cat": "J", "ep": "J-13 给菜单加上说明文字", "u": "J/13-mWIbb1l7Wlw.html", "vid": "mWIbb1l7Wlw", "q": "为什么「选项：前往选项」是糟糕的帮助？", "a": "帮助是给不懂这个词的人看的，用同样的词等于没说明。", "t": 70}, {"cat": "J", "ep": "J-13 给菜单加上说明文字", "u": "J/13-mWIbb1l7Wlw.html", "vid": "mWIbb1l7Wlw", "q": "想好帮助文字后还应做什么？", "a": "再嚼碎：客观看意思、去冗余、意译不直译，并避免专业术语。", "t": 105}, {"cat": "J", "ep": "J-14 不靠文字也能明白", "u": "J/14-psGx8fOlus0.html", "vid": "psGx8fOlus0", "q": "图标里放入画面/角色有什么作用？", "a": "看起来开心，并且看图就能知道能做什么，不懂语言也能理解。", "t": 23}, {"cat": "J", "ep": "J-14 不靠文字也能明白", "u": "J/14-psGx8fOlus0.html", "vid": "psGx8fOlus0", "q": "为什么频道尽量使用英文画面？", "a": "日本人读英文还能大概理解，英语母语者读日语却非常困难。", "t": 50}, {"cat": "J", "ep": "J-14 不靠文字也能明白", "u": "J/14-psGx8fOlus0.html", "vid": "psGx8fOlus0", "q": "「连按确认键」设计的目的是什么？举一个例子。", "a": "让人不读文字也能进入基本主游戏；如《特别版》连按会到大乱斗的斗士选择。", "t": 80}, {"cat": "J", "ep": "J-15 HUD（抬头显示）", "u": "J/15-a_HB81ujHHE.html", "vid": "a_HB81ujHHE", "q": "樱井认为日本与海外作品的 HUD 有什么倾向差异？", "a": "日本作品信息较多；海外作品较克制，重视沉浸，常可隐藏信息。", "t": 60}, {"cat": "J", "ep": "J-15 HUD（抬头显示）", "u": "J/15-a_HB81ujHHE.html", "vid": "a_HB81ujHHE", "q": "《大乱斗X》起 HUD 显示斗士头像有什么好处？", "a": "画面中斗士常很小，头像能强化角色性，也适合观战者。", "t": 99}, {"cat": "J", "ep": "J-15 HUD（抬头显示）", "u": "J/15-a_HB81ujHHE.html", "vid": "a_HB81ujHHE", "q": "《卡比赛车》为什么用图标显示击败的对手？", "a": "3D 空间中难以看出伤到了几个对手，图标能清楚传达。", "t": 153}, {"cat": "K", "ep": "K-1 文件名要有逻辑", "u": "K/01-XMzR5mJHPDg.html", "vid": "XMzR5mJHPDg", "q": "《大乱斗》中 Attack 和 Special 分别对应什么？", "a": "Attack：A 键普通攻击；Special：B 键必杀技。", "t": 70}, {"cat": "K", "ep": "K-1 文件名要有逻辑", "u": "K/01-XMzR5mJHPDg.html", "vid": "XMzR5mJHPDg", "q": "为什么方向放在名称后面而不是前面？", "a": "排序时能按 Attack/Special 及强度整齐排列；方向在前会排得乱七八糟。", "t": 145}, {"cat": "K", "ep": "K-1 文件名要有逻辑", "u": "K/01-XMzR5mJHPDg.html", "vid": "XMzR5mJHPDg", "q": "樱井对日本开发者的命名提醒是什么？", "a": "尽量别用罗马字文件名，海外成员难以理解。", "t": 252}, {"cat": "K", "ep": "K-2 让游戏便于调整", "u": "K/02-nGaajB8m5Q0.html", "vid": "nGaajB8m5Q0", "q": "为什么要把参数放在程序外面？", "a": "直接写进程序每次调整都要改程序；放在外面策划可以随时调整。", "t": 33}, {"cat": "K", "ep": "K-2 让游戏便于调整", "u": "K/02-nGaajB8m5Q0.html", "vid": "nGaajB8m5Q0", "q": "用 Excel 管理参数有哪些好处？", "a": "可隐藏低频参数避免失误、可写公式做相对调整（如某招总是另一招的 1/2）。", "t": 86}, {"cat": "K", "ep": "K-2 让游戏便于调整", "u": "K/02-nGaajB8m5Q0.html", "vid": "nGaajB8m5Q0", "q": "什么是「转换」？现在如何进行？", "a": "把参数反映到开发机的作业；现在用 Excel 插件一键送到运行中的开发机。", "t": 140}, {"cat": "K", "ep": "K-3 把参数放进括号", "u": "K/03-v6ozfbqNa54.html", "vid": "v6ozfbqNa54", "q": "程序和参数的区别是什么？", "a": "程序是处理命令的步骤书；参数是填充血肉的数值（速度、攻击力等）。", "t": 3}, {"cat": "K", "ep": "K-3 把参数放进括号", "u": "K/03-v6ozfbqNa54.html", "vid": "v6ozfbqNa54", "q": "樱井写规格书时的三条参数规则是什么？", "a": "参数名用口语写、用【】括起来、要数值化的地方写 ○。", "t": 145}, {"cat": "K", "ep": "K-3 把参数放进括号", "u": "K/03-v6ozfbqNa54.html", "vid": "v6ozfbqNa54", "q": "这种写法适用于什么情况？", "a": "需要个别规格时（如角色专属动作）；不适合通用的攻击参数等。", "t": 259}, {"cat": "K", "ep": "K-4 用工单管理任务", "u": "K/04-7NpLxkkeh6Y.html", "vid": "7NpLxkkeh6Y", "q": "什么是工单？", "a": "用工具在服务器上管理的数字任务；在负责人间交接，持有者就是负责人。", "t": 3}, {"cat": "K", "ep": "K-4 用工单管理任务", "u": "K/04-7NpLxkkeh6Y.html", "vid": "7NpLxkkeh6Y", "q": "工单有哪些状态？", "a": "进行中、完成、保留、废弃等。", "t": 95}, {"cat": "K", "ep": "K-4 用工单管理任务", "u": "K/04-7NpLxkkeh6Y.html", "vid": "7NpLxkkeh6Y", "q": "工单如何用于调试？", "a": "bug 写成工单报告，先给部门组长，再分配负责人，必要时转给他人。", "t": 138}, {"cat": "K", "ep": "K-5 家庭 BASIC（Family BASIC）", "u": "K/05-89_FhHQ5n-g.html", "vid": "89_FhHQ5n-g", "q": "家庭 BASIC 的程序容量有多大？", "a": "只有 2KB，约 2000 个字。", "t": 50}, {"cat": "K", "ep": "K-5 家庭 BASIC（Family BASIC）", "u": "K/05-89_FhHQ5n-g.html", "vid": "89_FhHQ5n-g", "q": "6 行 MOVE 程序中，DEF MOVE 里的 N+1 代表什么？", "a": "方向——0～7 号分别分配 8 个方向。", "t": 300}, {"cat": "K", "ep": "K-5 家庭 BASIC（Family BASIC）", "u": "K/05-89_FhHQ5n-g.html", "vid": "89_FhHQ5n-g", "q": "MOVE 命令的缺点是什么？", "a": "手轻但难用：只能设定 8 个方向，移动等也不能马上响应。", "t": 385}, {"cat": "K", "ep": "K-5 家庭 BASIC（Family BASIC）", "u": "K/05-89_FhHQ5n-g.html", "vid": "89_FhHQ5n-g", "q": "用 SPRITE 命令写的程序让樱井学到了什么？", "a": "惯性等因素如何影响操作手感，并用在了初代《星之卡比》的开发上。", "t": 470}, {"cat": "K", "ep": "K-5 家庭 BASIC（Family BASIC）", "u": "K/05-89_FhHQ5n-g.html", "vid": "89_FhHQ5n-g", "q": "红白机的「属性」问题是什么？", "a": "调色板以 16×16 区块共用，物件放错位置颜色会变，需要挪位对齐。", "t": 550}, {"cat": "K", "ep": "K-6 《大乱斗》的击飞", "u": "K/06-HVktK4a9Yfo.html", "vid": "HVktK4a9Yfo", "q": "《大乱斗》中什么决定被击飞得多远？", "a": "攻击方的攻击力越高、被打方累积伤害越高，飞得越远。", "t": 32}, {"cat": "K", "ep": "K-6 《大乱斗》的击飞", "u": "K/06-HVktK4a9Yfo.html", "vid": "HVktK4a9Yfo", "q": "反应加算值的作用是什么？为何常与影响值并用？", "a": "无条件加击飞力，保证低伤害时也有一定反应；单纯加算会太大，所以用影响值压住。", "t": 100}, {"cat": "K", "ep": "K-6 《大乱斗》的击飞", "u": "K/06-HVktK4a9Yfo.html", "vid": "HVktK4a9Yfo", "q": "超级跳跃拳为什么连续命中部分用固定反应？", "a": "否则对方伤害太低或太高时后续会打不中；固定反应保证连段，只有最后一发正常击飞。", "t": 150}, {"cat": "K", "ep": "K-7 多人如何编辑同一批文件", "u": "K/07-s5u7VqDl-1I.html", "vid": "s5u7VqDl-1I", "q": "多人编辑时，管理工具的基本流程是什么？", "a": "文件都在服务器上；编辑前上锁、编辑后上传服务器、再解锁。", "t": 56}, {"cat": "K", "ep": "K-7 多人如何编辑同一批文件", "u": "K/07-s5u7VqDl-1I.html", "vid": "s5u7VqDl-1I", "q": "两人编辑撞车时工具会怎么做？", "a": "尝试合并——比对编辑处缝合；仍有矛盾时需要手工编辑。", "t": 91}, {"cat": "K", "ep": "K-7 多人如何编辑同一批文件", "u": "K/07-s5u7VqDl-1I.html", "vid": "s5u7VqDl-1I", "q": "什么是「回退」？如何补救？", "a": "某人的编辑消失、文件回到编辑前；管理工具每次编辑有备份，运气好退回上一版即可恢复。", "t": 116}, {"cat": "K", "ep": "K-8 调试模式", "u": "K/08-AdBcCQtuATc.html", "vid": "AdBcCQtuATc", "q": "没有「设定所有人伤害」的功能时，以前是怎么测试的？", "a": "把狐狸横强攻击力设为 100 来试。", "t": 50}, {"cat": "K", "ep": "K-8 调试模式", "u": "K/08-AdBcCQtuATc.html", "vid": "AdBcCQtuATc", "q": "「今日一张」用调试模式拍有哪些限制？", "a": "不能把斗士放到画面深处或前方，手持物会消失等。", "t": 98}, {"cat": "K", "ep": "K-8 调试模式", "u": "K/08-AdBcCQtuATc.html", "vid": "AdBcCQtuATc", "q": "樱井对调试操作的手柄有什么建议？为什么？", "a": "用平时的一个手柄（按键组合）就能完成；事后找另一个手柄很麻烦。", "t": 112}, {"cat": "K", "ep": "K-9 透明化功能", "u": "K/09-Ie5wG3LlBNs.html", "vid": "Ie5wG3LlBNs", "q": "部分透明功能主要用来做什么？", "a": "仔细确认动作，例如披风挡住姿势时让披风透明。", "t": 30}, {"cat": "K", "ep": "K-9 透明化功能", "u": "K/09-Ie5wG3LlBNs.html", "vid": "Ie5wG3LlBNs", "q": "除了部分透明，还有什么更一般的显示功能？", "a": "按元素开关显示：UI、2P、特效、阴影、后期效果等。", "t": 90}, {"cat": "K", "ep": "K-9 透明化功能", "u": "K/09-Ie5wG3LlBNs.html", "vid": "Ie5wG3LlBNs", "q": "以前没有透明化功能时，怎么去掉挡视线的披风？", "a": "只能靠把它缩放到很小或修改模型来去掉。", "t": 40}, {"cat": "L", "ep": "L-1 宣传是乘法", "u": "L/01-iwOgFiJNCoU.html", "vid": "iwOgFiJNCoU", "q": "为什么樱井说「不被知道就等于不存在」？", "a": "游戏再好，没人知道它存在就无法发挥价值；被知道和好玩同等重要。", "t": 21}, {"cat": "L", "ep": "L-1 宣传是乘法", "u": "L/01-iwOgFiJNCoU.html", "vid": "iwOgFiJNCoU", "q": "「开发与宣传是乘法」是什么意思？", "a": "一方的成果与另一方成比例，哪一方为零都不行。", "t": 122}, {"cat": "L", "ep": "L-1 宣传是乘法", "u": "L/01-iwOgFiJNCoU.html", "vid": "iwOgFiJNCoU", "q": "樱井在宣传上具体做哪些事？", "a": "制作参战影片、以单独使用为前提做原画、检查官方推特/网站文案并提案等。", "t": 57}, {"cat": "L", "ep": "L-2 准确传达游戏的样子", "u": "L/02-tb6GJUvJGpM.html", "vid": "tb6GJUvJGpM", "q": "宣传游戏时绝对不能做的是什么？", "a": "拿出与商品印象不符的东西；购买时的印象必须和游戏中的乐趣一致。", "t": 33}, {"cat": "L", "ep": "L-2 准确传达游戏的样子", "u": "L/02-tb6GJUvJGpM.html", "vid": "tb6GJUvJGpM", "q": "商品印象与实际脱节会造成什么后果？", "a": "触达不到真正会感兴趣的顾客，还会让误买的人失望。", "t": 90}, {"cat": "L", "ep": "L-2 准确传达游戏的样子", "u": "L/02-tb6GJUvJGpM.html", "vid": "tb6GJUvJGpM", "q": "《星之卡比 超级豪华版》日版包装的概念是什么？", "a": "糸井重里提出的「把豪华的作品装进上等桐木盒」，看似脱节却抓住本质。", "t": 119}, {"cat": "L", "ep": "L-3 体验版", "u": "L/03-PfNtg0tSGDY.html", "vid": "PfNtg0tSGDY", "q": "为什么做体验版不只是「切一段游戏」？", "a": "要防剧透数据泄露、管理两个版本并分别更新调试、剔除要素易出 bug，工作量可能相当于一款小游戏。", "t": 44}, {"cat": "L", "ep": "L-3 体验版", "u": "L/03-PfNtg0tSGDY.html", "vid": "PfNtg0tSGDY", "q": "体验版平衡的两难是什么？", "a": "发售前推出可能平衡未调好被看扁；要同等平衡就只能发售后推出，效果又微妙。", "t": 113}, {"cat": "L", "ep": "L-3 体验版", "u": "L/03-PfNtg0tSGDY.html", "vid": "PfNtg0tSGDY", "q": "樱井对体验版的结论是什么？", "a": "非常有效，被知道比不被知道好；做不做取决于厂商方针。", "t": 200}, {"cat": "L", "ep": "L-4 官方网站", "u": "L/04-ABow3YMNg1Q.html", "vid": "ABow3YMNg1Q", "q": "为什么樱井认为官网仍然重要？", "a": "大作需要系统、正确地发布完整信息，官网是信息枢纽。", "t": 20}, {"cat": "L", "ep": "L-4 官方网站", "u": "L/04-ABow3YMNg1Q.html", "vid": "ABow3YMNg1Q", "q": "初代「大乱斗拳」是怎么诞生的？", "a": "初代不被理解，寄给杂志的玩法资料几乎没人采用，于是转用为技巧指南并亲写 HTML 做成网站。", "t": 190}, {"cat": "L", "ep": "L-4 官方网站", "u": "L/04-ABow3YMNg1Q.html", "vid": "ABow3YMNg1Q", "q": "樱井从初代的挫折中得出什么？", "a": "苦涩经历只要积极寻找突破口就能成为养分，SP 的参战影片也许与此一脉相承。", "t": 230}, {"cat": "L", "ep": "L-5 参战影片", "u": "L/05-K_z28RqWDU4.html", "vid": "K_z28RqWDU4", "q": "为什么《大乱斗X》之后不再在游戏中途插入剧情影片？", "a": "发售前就被大量上传（连海外媒体都上传），无法再作为奖励。", "t": 46}, {"cat": "L", "ep": "L-5 参战影片", "u": "L/05-K_z28RqWDU4.html", "vid": "K_z28RqWDU4", "q": "CG 部分的制作流程是什么？", "a": "樱井写剧情大纲 → 开会细化 → 分镜 → 动态分镜 → 预演 → 正式制作（模型、背景、特效等）→ 音响。", "t": 110}, {"cat": "L", "ep": "L-5 参战影片", "u": "L/05-K_z28RqWDU4.html", "vid": "K_z28RqWDU4", "q": "游戏部分是如何拍摄的？", "a": "由制作团队员工活用调试与回放功能移动镜头拍摄，多次送樱井检查打磨。", "t": 253}, {"cat": "L", "ep": "L-6 快让人看到实际游戏！", "u": "L/06--4oPgNbnJCI.html", "vid": "-4oPgNbnJCI", "q": "宣传影片常见的问题是什么？", "a": "开场动画、角色介绍、logo 拖太久，迟迟不进游戏画面，有的甚至完全没有游戏画面。", "t": 30}, {"cat": "L", "ep": "L-6 快让人看到实际游戏！", "u": "L/06--4oPgNbnJCI.html", "vid": "-4oPgNbnJCI", "q": "什么情况下可以用预告片式的呈现？", "a": "备受瞩目的系列作或著名制作者的作品；新作、第一作、独立游戏应马上展示游戏。", "t": 52}, {"cat": "L", "ep": "L-6 快让人看到实际游戏！", "u": "L/06--4oPgNbnJCI.html", "vid": "-4oPgNbnJCI", "q": "什么例外可以不从游戏画面开始？", "a": "巧妙融入游戏系统的影片，或处理负荷等毫无虚假的技术演示。", "t": 105}, {"cat": "L", "ep": "L-7 在别人面前玩游戏", "u": "L/07-j6pnwcuP78g.html", "vid": "j6pnwcuP78g", "q": "樱井在「樱井政博的○○」演示时注意哪些事？", "a": "必杀技和终极必杀全部用出、不赢得太悬殊、多展示普通招式——尽量多拿素材。", "t": 66}, {"cat": "L", "ep": "L-7 在别人面前玩游戏", "u": "L/07-j6pnwcuP78g.html", "vid": "j6pnwcuP78g", "q": "为什么樱井认为当面演示很有效？", "a": "亲眼看到最有说服力（Seeing is believing），可能是效果最高的演示。", "t": 106}, {"cat": "L", "ep": "L-7 在别人面前玩游戏", "u": "L/07-j6pnwcuP78g.html", "vid": "j6pnwcuP78g", "q": "即使不真的在人前演示，设想演示有什么好处？", "a": "能整理自己的想法，想象顾客反应能发现东西。", "t": 125}, {"cat": "L", "ep": "L-8 目标客群与市场调研", "u": "L/08-Y0sf-emY5oE.html", "vid": "Y0sf-emY5oE", "q": "目标定位和营销分别指什么？", "a": "目标定位：瞄准支持度高的层或弥补弱层来卖商品；营销：调查这些倾向的数据化工作。", "t": 40}, {"cat": "L", "ep": "L-8 目标客群与市场调研", "u": "L/08-Y0sf-emY5oE.html", "vid": "Y0sf-emY5oE", "q": "初代《星之卡比》的目标客群是谁？", "a": "「新手」——包括大人、孩子、男女，而不是按年龄的「儿童」。", "t": 122}, {"cat": "L", "ep": "L-8 目标客群与市场调研", "u": "L/08-Y0sf-emY5oE.html", "vid": "Y0sf-emY5oE", "q": "为什么一直追随市场调研会出问题？", "a": "它是别人走过的路，追下去会变得平凡、跳进红海（如 FC/SFC 时代一窝蜂做 RPG）。", "t": 152}, {"cat": "L", "ep": "L-9 大乱斗拳!!", "u": "L/09-v4BG0wnc72s.html", "vid": "v4BG0wnc72s", "q": "「大乱斗拳」是怎么来的？", "a": "初代不被理解，给杂志社的《秘传之书》效果不佳，于是公开成面向玩家的网站，由樱井独自熬夜制作。", "t": 56}, {"cat": "L", "ep": "L-9 大乱斗拳!!", "u": "L/09-v4BG0wnc72s.html", "vid": "v4BG0wnc72s", "q": "《大乱斗X》的「Smash Bros. DOJO!!」有何特点？", "a": "周一到周五每日更新，支持 6 种语言，与美国、欧洲任天堂合作。", "t": 206}, {"cat": "L", "ep": "L-9 大乱斗拳!!", "u": "L/09-v4BG0wnc72s.html", "vid": "v4BG0wnc72s", "q": "樱井为什么在最忙的开发期仍亲自发信息？", "a": "交给别人也要监修，且总监最了解游戏；开发与宣传是两个轮子。", "t": 275}, {"cat": "M", "ep": "M-1 打倒延迟！", "u": "M/01-gjoKKyskco4.html", "vid": "gjoKKyskco4", "q": "E3 2018 现场试玩的事说明了什么？", "a": "多名布展人员摸过仍没发现严重延迟，说明多数人很难察觉延迟。", "t": 70}, {"cat": "M", "ep": "M-1 打倒延迟！", "u": "M/01-gjoKKyskco4.html", "vid": "gjoKKyskco4", "q": "如何简单检查自家电视的延迟？", "a": "用按下即反应的 2D 游戏（如 NSO 的 FC 游戏）按跳跃，感觉慢就切游戏模式/低延迟模式。", "t": 130}, {"cat": "M", "ep": "M-1 打倒延迟！", "u": "M/01-gjoKKyskco4.html", "vid": "gjoKKyskco4", "q": "显示延迟主要来自哪里？60fps 时一帧多少毫秒？", "a": "电视为画质做的后处理；约 16.67ms。", "t": 245}, {"cat": "M", "ep": "M-2 游戏奖项", "u": "M/02-re5JlUcYvxU.html", "vid": "re5JlUcYvxU", "q": "樱井对「决出游戏第一名」持什么态度？", "a": "不太赞成；你觉得好的就是第一，游戏的好在于各自方向而非排名。", "t": 30}, {"cat": "M", "ep": "M-2 游戏奖项", "u": "M/02-re5JlUcYvxU.html", "vid": "re5JlUcYvxU", "q": "他认为游戏奖项存在的意义是什么？", "a": "让做出好游戏的制作者和支持他们的粉丝高兴。", "t": 60}, {"cat": "M", "ep": "M-2 游戏奖项", "u": "M/02-re5JlUcYvxU.html", "vid": "re5JlUcYvxU", "q": "游戏设计师大奖与以票数为主的奖有何不同？", "a": "由做独创作品的导演投票，以独创性为主题，而非人气。", "t": 120}, {"cat": "M", "ep": "M-3 边玩游戏边运动！", "u": "M/03-ysaNUatLMn0.html", "vid": "ysaNUatLMn0", "q": "樱井怎样把游戏时间与运动结合？", "a": "一边骑健身车一边玩游戏，靠游戏忘记运动的辛苦，能长时间骑。", "t": 24}, {"cat": "M", "ep": "M-3 边玩游戏边运动！", "u": "M/03-ysaNUatLMn0.html", "vid": "ysaNUatLMn0", "q": "什么类型的游戏骑车时会效果更好，什么会骑慢？", "a": "赛车游戏想象自己踩出速度效果好；潜行游戏会不自觉骑慢。", "t": 56}, {"cat": "M", "ep": "M-3 边玩游戏边运动！", "u": "M/03-ysaNUatLMn0.html", "vid": "ysaNUatLMn0", "q": "他为什么讨厌运动却仍要运动？", "a": "运动与否明显影响工作能力。", "t": 112}, {"cat": "M", "ep": "M-4 游戏的价格", "u": "M/04-i6jKMAU3aJ8.html", "vid": "i6jKMAU3aJ8", "q": "樱井为什么认为游戏便宜？", "a": "能玩几十小时而 3A 也不到 1 万日元，且规模比过去大几十几百倍价格却没怎么涨。", "t": 56}, {"cat": "M", "ep": "M-4 游戏的价格", "u": "M/04-i6jKMAU3aJ8.html", "vid": "i6jKMAU3aJ8", "q": "订阅服务对制作者意味着什么？", "a": "既能确保制作成本，也要和过去作品一起竞争。", "t": 126}, {"cat": "M", "ep": "M-4 游戏的价格", "u": "M/04-i6jKMAU3aJ8.html", "vid": "i6jKMAU3aJ8", "q": "他最后呼吁玩家做什么？", "a": "对想玩、想支持的作品毫不犹豫地购买或在订阅中游玩，支持制作。", "t": 145}, {"cat": "M", "ep": "M-5 我的爱猫「膨拉西」", "u": "M/05-EbkshNLpMwo.html", "vid": "EbkshNLpMwo", "q": "膨拉西的正式名字是什么？", "a": "福良（Fukura），顺口叫成了「膨拉西」。", "t": 30}, {"cat": "M", "ep": "M-5 我的爱猫「膨拉西」", "u": "M/05-EbkshNLpMwo.html", "vid": "EbkshNLpMwo", "q": "樱井说家里有猫后他最常说的话是什么？", "a": "「好可爱」。", "t": 40}, {"cat": "M", "ep": "M-5 我的爱猫「膨拉西」", "u": "M/05-EbkshNLpMwo.html", "vid": "EbkshNLpMwo", "q": "樱井每天给膨拉西的「功课」是什么？", "a": "洗澡后给她喂肉泥条（Churu）。", "t": 130}, {"cat": "M", "ep": "M-6 昔是昔，今是今", "u": "M/06-CVQ4PuihnTk.html", "vid": "CVQ4PuihnTk", "q": "樱井说游戏的乐趣是绝对的还是相对的？受哪些因素影响？", "a": "相对的；受时代、周围环境、流行、技术程度影响。", "t": 90}, {"cat": "M", "ep": "M-6 昔是昔，今是今", "u": "M/06-CVQ4PuihnTk.html", "vid": "CVQ4PuihnTk", "q": "老游戏在哪方面可能比现代游戏更有价值？", "a": "理论尚未定型，可能有更多游戏设计上的发现。", "t": 130}, {"cat": "M", "ep": "M-6 昔是昔，今是今", "u": "M/06-CVQ4PuihnTk.html", "vid": "CVQ4PuihnTk", "q": "对「多感时期接触的作品」，樱井的建议是？", "a": "它们很重要，但别因此不去享受现代游戏，积极尝试新东西。", "t": 160}, {"cat": "M", "ep": "M-7 有限会社 Sora", "u": "M/07-VVhGCtCNGHg.html", "vid": "VVhGCtCNGHg", "q": "有限会社 Sora 的定位是什么？", "a": "樱井与其他公司签约用的公司，几乎没有制作人员，也不招聘。", "t": 30}, {"cat": "M", "ep": "M-7 有限会社 Sora", "u": "M/07-VVhGCtCNGHg.html", "vid": "VVhGCtCNGHg", "q": "樱井的收入模式与一般外包公司有何不同？", "a": "开发期间不收费，发售后按销量拿收入；一般外包每月收固定开发费。", "t": 100}, {"cat": "M", "ep": "M-7 有限会社 Sora", "u": "M/07-VVhGCtCNGHg.html", "vid": "VVhGCtCNGHg", "q": "他为什么选择这种高风险的收入方式？", "a": "为了与要卖出才有利润的发行商共担风险。", "t": 140}, {"cat": "M", "ep": "M-8 实体派还是下载派？", "u": "M/08-ynBcgPh8xV4.html", "vid": "ynBcgPh8xV4", "q": "实体版和下载版各有什么优点？", "a": "实体：实物可收藏、不占容量、限定版等；下载：随时买、不缺货、不用跑店、不占地方。", "t": 30}, {"cat": "M", "ep": "M-8 实体派还是下载派？", "u": "M/08-ynBcgPh8xV4.html", "vid": "ynBcgPh8xV4", "q": "樱井为何是下载派？", "a": "不是收藏家，不执着实物，独立后收纳空间不足，重视玩过而非包装。", "t": 70}, {"cat": "M", "ep": "M-8 实体派还是下载派？", "u": "M/08-ynBcgPh8xV4.html", "vid": "ynBcgPh8xV4", "q": "他对下载版有什么期望？", "a": "价格更合理（目前与实体相差无几），并能按喜好分文件夹。", "t": 125}, {"cat": "M", "ep": "M-9 Sora 的居家办公对策", "u": "M/09-YXudgEHF78M.html", "vid": "YXudgEHF78M", "q": "问卷中远程办公的主要问题有哪些？", "a": "没有桌椅、没有基准电视、网络慢不稳、无法面对面测试对战、缺少人际接触。", "t": 60}, {"cat": "M", "ep": "M-9 Sora 的居家办公对策", "u": "M/09-YXudgEHF78M.html", "vid": "YXudgEHF78M", "q": "Sora 的居家支援是怎么运作的？", "a": "员工自选所需物品发商品页，Sora 下单直寄到家，不用归还。", "t": 130}, {"cat": "M", "ep": "M-9 Sora 的居家办公对策", "u": "M/09-YXudgEHF78M.html", "vid": "YXudgEHF78M", "q": "为什么由 Sora 而不是各公司来采购？", "a": "团队跨多家公司，各自申请审批耗时；为追求最快速度由 Sora 承担。", "t": 190}, {"cat": "M", "ep": "M-10 与过去竞争", "u": "M/10-EhcitspNMuI.html", "vid": "EhcitspNMuI", "q": "为什么订阅制让影像作品与过去竞争？", "a": "看到饱服务中新旧作品同列，在观众时间里以同等价值被观看。", "t": 40}, {"cat": "M", "ep": "M-10 与过去竞争", "u": "M/10-EhcitspNMuI.html", "vid": "EhcitspNMuI", "q": "游戏与过去竞争的压力为什么相对小？", "a": "技术进步使旧画面/操作未必满足人，且游戏规模不同，不能用固定时长衡量。", "t": 90}, {"cat": "M", "ep": "M-10 与过去竞争", "u": "M/10-EhcitspNMuI.html", "vid": "EhcitspNMuI", "q": "樱井认为脱颖而出的最好方法是？", "a": "做出更新颖、只有这部作品才有的东西。", "t": 135}, {"cat": "M", "ep": "M-11 游戏与眼睛疲劳", "u": "M/11-0VaLAZeMJnE.html", "vid": "0VaLAZeMJnE", "q": "樱井为什么不太玩手游和 Switch 掌机模式？", "a": "近距离看屏幕眼睛会极度疲劳。", "t": 10}, {"cat": "M", "ep": "M-11 游戏与眼睛疲劳", "u": "M/11-0VaLAZeMJnE.html", "vid": "0VaLAZeMJnE", "q": "他在工作环境中做了什么调整？代价是什么？", "a": "把显示器放到 1 米以上；需要更大的显示器、机型选择变少。", "t": 84}, {"cat": "M", "ep": "M-11 游戏与眼睛疲劳", "u": "M/11-0VaLAZeMJnE.html", "vid": "0VaLAZeMJnE", "q": "他认为减轻眼睛负担最有效的方法是什么？", "a": "改变环境（如拉开与屏幕的距离），比调亮度、眼药水、补充剂更有效。", "t": 130}, {"cat": "M", "ep": "M-12 母盘完成（Master Up）", "u": "M/12-y2Webks5iTs.html", "vid": "y2Webks5iTs", "q": "为什么 Master Up 的瞬间未必畅快？", "a": "过程中有割舍的艰难判断，且可在线更新时还要继续修补遗漏，更像带着伤。", "t": 35}, {"cat": "M", "ep": "M-12 母盘完成（Master Up）", "u": "M/12-y2Webks5iTs.html", "vid": "y2Webks5iTs", "q": "FC/GB 时代游戏是怎么交付的？", "a": "在东京完成 ROM 后亲手揣着坐新干线送到京都的任天堂总部或宇治工厂。", "t": 67}, {"cat": "M", "ep": "M-12 母盘完成（Master Up）", "u": "M/12-y2Webks5iTs.html", "vid": "y2Webks5iTs", "q": "在线更新的普及让完成的感觉有什么变化？", "a": "「到此为止」的终点感变淡，没那么畅快。", "t": 100}, {"cat": "M", "ep": "M-13 Famicom（与 NES）", "u": "M/13-PHBKYrnIUmY.html", "vid": "PHBKYrnIUmY", "q": "FC 在 1983 年为什么出类拔萃？", "a": "漂亮画面、响亮音效、流畅高速处理、好用手柄、价格不高，且软件好玩（如《大金刚》几乎原样移植）。", "t": 60}, {"cat": "M", "ep": "M-13 Famicom（与 NES）", "u": "M/13-PHBKYrnIUmY.html", "vid": "PHBKYrnIUmY", "q": "日本 FC 与海外 NES 的发售时间差带来了什么？", "a": "两年间日本游戏技术大进步，海外市场混入新旧作品，内容量落差大。", "t": 130}, {"cat": "M", "ep": "M-13 Famicom（与 NES）", "u": "M/13-PHBKYrnIUmY.html", "vid": "PHBKYrnIUmY", "q": "FC 是怎样实现不断进化的？", "a": "ROM 容量扩大，以及卡带内加入定制芯片；日本还有扩展音源针脚。", "t": 224}, {"cat": "M", "ep": "M-14 初代《星之卡比》开发秘话", "u": "M/14-ZUY2AtBD6Sk.html", "vid": "ZUY2AtBD6Sk", "q": "瓦豆鲁迪和瓦豆为什么长得这么像？", "a": "为了用 1.5 只的容量做 2 只角色，背面共用同一张图。", "t": 294}, {"cat": "M", "ep": "M-14 初代《星之卡比》开发秘话", "u": "M/14-ZUY2AtBD6Sk.html", "vid": "ZUY2AtBD6Sk", "q": "初代卡比的敌人为什么不做地形判定？这样做有什么好处？", "a": "预先做好动作再配合背景摆放；处理很轻，对当时的 GB 非常重要。", "t": 525}, {"cat": "M", "ep": "M-14 初代《星之卡比》开发秘话", "u": "M/14-ZUY2AtBD6Sk.html", "vid": "ZUY2AtBD6Sk", "q": "初代卡比企划书中藏着什么惊人内容？", "a": "被攻击吹飞、飞出画面即失误、体力影响吹飞——就是《大乱斗》的规则。", "t": 651}, {"cat": "M", "ep": "M-15 开发中止的游戏", "u": "M/15-5Ob9OA0peQY.html", "vid": "5Ob9OA0peQY", "q": "开发中止的冲击谁最大？为什么？", "a": "公司：收益全失，维持费成为亏损，一部失败就可能让公司倾斜。", "t": 70}, {"cat": "M", "ep": "M-15 开发中止的游戏", "u": "M/15-5Ob9OA0peQY.html", "vid": "5Ob9OA0peQY", "q": "中止多由什么来判断？", "a": "今后要花的费用与预期收益的平衡。", "t": 104}, {"cat": "M", "ep": "M-15 开发中止的游戏", "u": "M/15-5Ob9OA0peQY.html", "vid": "5Ob9OA0peQY", "q": "樱井建议开发者如何面对中止风险？", "a": "意识到风险，不只做分内事，尽量俯瞰全局、建设性协作推进完成。", "t": 152}, {"cat": "M", "ep": "M-16 ♪ PRESS START", "u": "M/16-zJcPrrjFNFw.html", "vid": "zJcPrrjFNFw", "q": "PRESS START 是怎样成立的？", "a": "2002 年 FF 与《大乱斗 DX》音乐会都由竹本泰藏指挥，五人酒桌上聊起，借 Companys 与 enterbrain 之力实现。", "t": 69}, {"cat": "M", "ep": "M-16 ♪ PRESS START", "u": "M/16-zJcPrrjFNFw.html", "vid": "zJcPrrjFNFw", "q": "为什么演出时不过度放原作影像？", "a": "画面太闹会让观众无法专注于演奏本身。", "t": 190}, {"cat": "M", "ep": "M-16 ♪ PRESS START", "u": "M/16-zJcPrrjFNFw.html", "vid": "zJcPrrjFNFw", "q": "PRESS START 持续困难的原因有哪些？", "a": "每场约 60 首要调查编排，与本职开发冲突；版权上出不了 CD。", "t": 225}, {"cat": "M", "ep": "M-17 我童年时的游戏", "u": "M/17-mDVaOyzO5pY.html", "vid": "mDVaOyzO5pY", "q": "樱井最早的电子游戏记忆是什么？为什么让他感动？", "a": "Pong 式旋钮游戏；拧旋钮画面里的东西直接动、还闪闪发光。", "t": 28}, {"cat": "M", "ep": "M-17 我童年时的游戏", "u": "M/17-mDVaOyzO5pY.html", "vid": "mDVaOyzO5pY", "q": "周日在超市，他如何使用 200 日元？", "a": "50 日元一局玩 4 次，仔细挑选；用完再去玩具区试玩各种主机。", "t": 91}, {"cat": "M", "ep": "M-17 我童年时的游戏", "u": "M/17-mDVaOyzO5pY.html", "vid": "mDVaOyzO5pY", "q": "日本 Falcom 在立川的店有什么特别之处？", "a": "软件店与开发室并设，开发现场从店里就能看到，可能是他第一次看到制作现场。", "t": 182}, {"cat": "M", "ep": "M-18 《大乱斗X》团队是怎样组成的", "u": "M/18-MammcQ3XkpY.html", "vid": "MammcQ3XkpY", "q": "任天堂为什么在开发体制未定时就发表新作《大乱斗》？", "a": "展开 Wi-Fi 网络服务时，日美最期待的都是《大乱斗》，先作为 Wii Wi-Fi 应用例发表。", "t": 88}, {"cat": "M", "ep": "M-18 《大乱斗X》团队是怎样组成的", "u": "M/18-MammcQ3XkpY.html", "vid": "MammcQ3XkpY", "q": "如果樱井拒绝，岩田打算怎么做？", "a": "努力在别处做，但可能只做 Wi-Fi 对应、不动 DX 的 26 名斗士。", "t": 144}, {"cat": "M", "ep": "M-18 《大乱斗X》团队是怎样组成的", "u": "M/18-MammcQ3XkpY.html", "vid": "MammcQ3XkpY", "q": "《X》的开发团队是怎样组成的？", "a": "任天堂以樱井为中心在东京集结，以 Game Arts 为主体，约 100 多人。", "t": 270}, {"cat": "M", "ep": "M-19 指导规范（Guidelines）", "u": "M/19-HgvheCHsExA.html", "vid": "HgvheCHsExA", "q": "《俄罗斯方块》规范统一了哪些内容？为什么需要？", "a": "方块颜色、NEXT 数、旋转轴、落点提示等；以前各版本规则不同，很难玩。", "t": 75}, {"cat": "M", "ep": "M-19 指导规范（Guidelines）", "u": "M/19-HgvheCHsExA.html", "vid": "HgvheCHsExA", "q": "规范给创作者带来什么矛盾？", "a": "想加入的表现因规范做不了，而玩家不知原因，印象可能变差。", "t": 128}, {"cat": "M", "ep": "M-19 指导规范（Guidelines）", "u": "M/19-HgvheCHsExA.html", "vid": "HgvheCHsExA", "q": "樱井对规范的最终看法是？", "a": "规范是人定的，有合有不合；希望能更灵活，做出好东西才最重要。", "t": 150}, {"cat": "M", "ep": "M-20 展示珍藏：几件稀有物品", "u": "M/20-Yk8WsbCQXGc.html", "vid": "Yk8WsbCQXGc", "q": "那支特别的 Wii 遥控器有什么不同？", "a": "用激光打印印着樱井的 Mii 头像，是任天堂送的。", "t": 64}, {"cat": "M", "ep": "M-20 展示珍藏：几件稀有物品", "u": "M/20-Yk8WsbCQXGc.html", "vid": "Yk8WsbCQXGc", "q": "刻着他名字的 Xbox 360 面板后来怎样了？", "a": "360 出现红环死机，面板沿用到下一代；换成 Series X 后没地方装了。", "t": 180}, {"cat": "M", "ep": "M-20 展示珍藏：几件稀有物品", "u": "M/20-Yk8WsbCQXGc.html", "vid": "Yk8WsbCQXGc", "q": "世嘉的认定证是怎么得来的？", "a": "80 年代后期投稿世嘉的企划征集活动获得，构想是动作化的主动时间战斗。", "t": 204}, {"cat": "M", "ep": "M-21 Game & Watch 的液晶图案", "u": "M/21-8JLA5YG16QM.html", "vid": "8JLA5YG16QM", "q": "Game & Watch 的液晶如何表现动作？", "a": "每个图案在固定位置，靠点亮/熄灭来表现；所有姿势同时印在液晶上。", "t": 44}, {"cat": "M", "ep": "M-21 Game & Watch 的液晶图案", "u": "M/21-8JLA5YG16QM.html", "vid": "8JLA5YG16QM", "q": "樱井为什么会有这些液晶图案资料？", "a": "开发《大乱斗》时作为参考资料获得（用于 Mr. Game & Watch、平面世界等）。", "t": 11}, {"cat": "M", "ep": "M-21 Game & Watch 的液晶图案", "u": "M/21-8JLA5YG16QM.html", "vid": "8JLA5YG16QM", "q": "G&W 液晶图案排布需要满足什么条件？", "a": "所有姿势、所有位置的图案要互不重叠地排在同一块液晶上。", "t": 77}, {"cat": "M", "ep": "M-22 创作者也会改变", "u": "M/22-pb4MCvedyOg.html", "vid": "pb4MCvedyOg", "q": "当认识的创作者音讯全无时，樱井希望大家别怎么做？", "a": "别说「那家伙完了」——他们可能在别处成功或找到了充实的工作。", "t": 48}, {"cat": "M", "ep": "M-22 创作者也会改变", "u": "M/22-pb4MCvedyOg.html", "vid": "pb4MCvedyOg", "q": "为什么说改变是自然的？", "a": "经验累积后做不同的事很自然，一直待在同一位置反而不普通。", "t": 80}, {"cat": "M", "ep": "M-22 创作者也会改变", "u": "M/22-pb4MCvedyOg.html", "vid": "pb4MCvedyOg", "q": "樱井自己有什么「改变」？", "a": "仍在做游戏，但开始做这个 YouTube 频道。", "t": 128}, {"cat": "M", "ep": "M-23 很久以前，像素画是用数字画的", "u": "M/23-5pJC1YLMbhk.html", "vid": "5pJC1YLMbhk", "q": "一位 16 进制数能表示几个点？两位呢？", "a": "一位 4 个点；两位 8 个点（一行）。", "t": 85}, {"cat": "M", "ep": "M-23 很久以前，像素画是用数字画的", "u": "M/23-5pJC1YLMbhk.html", "vid": "5pJC1YLMbhk", "q": "像 FC 那样的 3 色点阵怎样用数据表现？", "a": "两张同尺寸点阵叠加，4 种组合 = 透明 + 3 色。", "t": 200}, {"cat": "M", "ep": "M-23 很久以前，像素画是用数字画的", "u": "M/23-5pJC1YLMbhk.html", "vid": "5pJC1YLMbhk", "q": "数据压缩的例子是什么？", "a": "用「0x8」代替写 00000000。", "t": 220}, {"cat": "M", "ep": "M-24 把送礼变成游戏", "u": "M/24-CB85OhWD9o8.html", "vid": "CB85OhWD9o8", "q": "樱井给员工的礼物来自哪里？", "a": "重复的游戏、买错/不常用的东西、显卡显示器等高价物、活动周边。", "t": 20}, {"cat": "M", "ep": "M-24 把送礼变成游戏", "u": "M/24-CB85OhWD9o8.html", "vid": "CB85OhWD9o8", "q": "举出两种他用过的抽选规则。", "a": "用开发中的《大乱斗》对战；回复时间最接近 0 秒者优先（还有猜拳、先放自爆咒等）。", "t": 80}, {"cat": "M", "ep": "M-24 把送礼变成游戏", "u": "M/24-CB85OhWD9o8.html", "vid": "CB85OhWD9o8", "q": "把抽选游戏化有什么效果？", "a": "让送礼变成活动，促进员工交流，让大家都开心。", "t": 100}, {"cat": "M", "ep": "M-25 没有脚印的世界", "u": "M/25-GJJT8Yoxu_U.html", "vid": "GJJT8Yoxu_U", "q": "「没有脚印的世界」指怎样的游玩方式？", "a": "一无所知、无剧透、无他人痕迹地独自体验作品（偏好离线单人）。", "t": 14}, {"cat": "M", "ep": "M-25 没有脚印的世界", "u": "M/25-GJJT8Yoxu_U.html", "vid": "GJJT8Yoxu_U", "q": "樱井什么时候才看攻略？", "a": "真的卡住又想继续时，几乎作为最后手段。", "t": 63}, {"cat": "M", "ep": "M-25 没有脚印的世界", "u": "M/25-GJJT8Yoxu_U.html", "vid": "GJJT8Yoxu_U", "q": "他为什么推荐偶尔只凭自己感觉玩？", "a": "偏见少、感动能 100% 享受，感受更多，也最适合研究作品；感想可玩完后再看。", "t": 105}, {"cat": "M", "ep": "M-26 1986：传说之年", "u": "M/26-l2yPIetSPDw.html", "vid": "l2yPIetSPDw", "q": "举出三个 1986 年诞生的系列。", "a": "《塞尔达传说》《勇者斗恶龙》《银河战士》（还有《恶魔城》《光神话》等）。", "t": 28}, {"cat": "M", "ep": "M-26 1986：传说之年", "u": "M/26-l2yPIetSPDw.html", "vid": "l2yPIetSPDw", "q": "樱井认为 1986 年名作爆发的原因有哪些？", "a": "磁碟机与 Mega ROM 带来的容量飞跃；家用、街机、PC 激烈竞争，软硬件飞速进步。", "t": 144}, {"cat": "M", "ep": "M-26 1986：传说之年", "u": "M/26-l2yPIetSPDw.html", "vid": "l2yPIetSPDw", "q": "当年流行隐藏角色和秘技，有什么另一面？", "a": "对不知情的人太严苛，加上庞大化、高难度化。", "t": 240}, {"cat": "M", "ep": "M-27 樱井的收纳术", "u": "M/27-3tpttuaYiPI.html", "vid": "3tpttuaYiPI", "q": "FC 与 MD 卡带是怎样收纳的？", "a": "卡带与磁带同尺寸，用磁带盒装并贴上标题与发售年标签。", "t": 60}, {"cat": "M", "ep": "M-27 樱井的收纳术", "u": "M/27-3tpttuaYiPI.html", "vid": "3tpttuaYiPI", "q": "定制游戏柜在散热上做了哪些处理？", "a": "使用时开门且门可收进柜内，拆背板，Series X 与 PS5 连顶板也拆掉。", "t": 348}, {"cat": "M", "ep": "M-27 樱井的收纳术", "u": "M/27-3tpttuaYiPI.html", "vid": "3tpttuaYiPI", "q": "对于实物收藏，樱井最终看重什么？", "a": "不执着于实物，看重玩过的经验和记忆；软件已全面数字版。", "t": 552}, {"cat": "M", "ep": "M-28 现场演出中的实机游玩", "u": "M/28-_ofubdMhvBM.html", "vid": "_ofubdMhvBM", "q": "这次现场游玩的规则有哪些紧张点？", "a": "难度 9.0、防御力 0；中 Boss 让时间不定；Game Over 则演奏当场中断、没有第二次。", "t": 72}, {"cat": "M", "ep": "M-28 现场演出中的实机游玩", "u": "M/28-_ofubdMhvBM.html", "vid": "_ofubdMhvBM", "q": "为什么乐团必须配合游戏？", "a": "有中 Boss 等，通关时间不固定，演奏要配合击破时机等展开。", "t": 63}, {"cat": "M", "ep": "M-28 现场演出中的实机游玩", "u": "M/28-_ofubdMhvBM.html", "vid": "_ofubdMhvBM", "q": "樱井认为 PRESS START 的生命是什么？", "a": "现场——只在当场的一期一会的乐趣。", "t": 108}, {"cat": "M", "ep": "M-29 把任何游戏变成对战", "u": "M/29-B2z5xpvtcRw.html", "vid": "B2z5xpvtcRw", "q": "「同时进行对战」怎么玩？", "a": "两人同时开始同一款游戏，先失误者输或分数高者赢，结束立刻换下一款。", "t": 42}, {"cat": "M", "ep": "M-29 把任何游戏变成对战", "u": "M/29-B2z5xpvtcRw.html", "vid": "B2z5xpvtcRw", "q": "怎样把《勇者斗恶龙》变成对战？", "a": "设定目标，例如先打倒 3 只史莱姆的人获胜。", "t": 84}, {"cat": "M", "ep": "M-29 把任何游戏变成对战", "u": "M/29-B2z5xpvtcRw.html", "vid": "B2z5xpvtcRw", "q": "这种玩法需要什么条件？", "a": "同一款软件能同时运行两份（例如各带一台加入 NSO 的 Switch）。", "t": 110}, {"cat": "M", "ep": "M-30 显像管（CRT）显示器", "u": "M/30-9FDDPZtWvhM.html", "vid": "9FDDPZtWvhM", "q": "FC 光线枪如何判定命中？", "a": "枪像摄像头看画面；扣扳机时画面变暗、目标显示白框，按扫描线位置捕捉白框判定命中。", "t": 156}, {"cat": "M", "ep": "M-30 显像管（CRT）显示器", "u": "M/30-9FDDPZtWvhM.html", "vid": "9FDDPZtWvhM", "q": "游戏机如何在隔行扫描的 CRT 上实现 60 帧？", "a": "在奇数场与偶数场画不同的图，每场 1/60 秒。", "t": 216}, {"cat": "M", "ep": "M-30 显像管（CRT）显示器", "u": "M/30-9FDDPZtWvhM.html", "vid": "9FDDPZtWvhM", "q": "什么是「安全框」？", "a": "有效扫描线约 490 条，画面边缘看不到；做游戏时把重要内容放在可见范围内，边缘破图也无妨。", "t": 252}, {"cat": "M", "ep": "M-31 岩田先生", "u": "M/31-o2wYKkqhkG0.html", "vid": "o2wYKkqhkG0", "q": "樱井对岩田的第一印象是什么？", "a": "HAL 面试时打字极快，说话时带着发自内心的笑容。", "t": 60}, {"cat": "M", "ep": "M-31 岩田先生", "u": "M/31-o2wYKkqhkG0.html", "vid": "o2wYKkqhkG0", "q": "岩田亲自为樱井的哪个项目编程？", "a": "N64《大乱斗》原型「格斗游戏龙王」（以及另一款冒险游戏），利用休息日制作。", "t": 204}, {"cat": "M", "ep": "M-31 岩田先生", "u": "M/31-o2wYKkqhkG0.html", "vid": "o2wYKkqhkG0", "q": "岩田在 DX 最后关头做了什么？", "a": "已是任天堂经营企划室长，仍坐到程序员旁亲自找出并修正 Bug，让 DX 赶上 2001 年发售。", "t": 300}, {"cat": "N", "ep": "N-1 《星之卡比》（初代）", "u": "N/01-PBRt2D2YN44.html", "vid": "PBRt2D2YN44", "q": "卡比的「吸入」源自什么想法？", "a": "利用敌人有趣（风险回报一体），想用更简单的方法利用眼前的敌人。", "t": 105}, {"cat": "N", "ep": "N-1 《星之卡比》（初代）", "u": "N/01-PBRt2D2YN44.html", "vid": "PBRt2D2YN44", "q": "卡比为什么能飞？", "a": "体力制游戏中掉坑即死太重，保留失误但能靠飞行越过。", "t": 147}, {"cat": "N", "ep": "N-1 《星之卡比》（初代）", "u": "N/01-PBRt2D2YN44.html", "vid": "PBRt2D2YN44", "q": "樱井为何坚持把初代卡比做成面向初学者？", "a": "FC 末期游戏普遍很难，新手进不来；卡比的角色是把初学者带进游戏世界。", "t": 238}, {"cat": "N", "ep": "N-2 《星之卡比 梦之泉物语》", "u": "N/02-khJa2vIW0xY.html", "vid": "khJa2vIW0xY", "q": "为什么樱井认为初代的初学者向概念在 FC 上行不通？", "a": "FC 市场已完全成熟，从 FC 入门的初学者几乎没有了。", "t": 88}, {"cat": "N", "ep": "N-2 《星之卡比 梦之泉物语》", "u": "N/02-khJa2vIW0xY.html", "vid": "khJa2vIW0xY", "q": "复制能力如何同时满足初学者和高手？", "a": "初学者只用吸入吐出就能通关，熟练者可用复制能力玩出更宽广的乐趣。", "t": 128}, {"cat": "N", "ep": "N-2 《星之卡比 梦之泉物语》", "u": "N/02-khJa2vIW0xY.html", "vid": "khJa2vIW0xY", "q": "画面变宽导致飞行过强，用了哪些对策？", "a": "加大底部信息栏、中 Boss 锁定卷轴、降低飞行速度。", "t": 248}, {"cat": "N", "ep": "N-3 《星之卡比 超级豪华版》", "u": "N/03-PkeETXCSn5M.html", "vid": "PkeETXCSn5M", "q": "为什么横版跳跃游戏很难做二人同时游玩？", "a": "两个同等权重的角色会互相拉扯卷轴，而跳跃越障需要看清画面。", "t": 90}, {"cat": "N", "ep": "N-3 《星之卡比 超级豪华版》", "u": "N/03-PkeETXCSn5M.html", "vid": "PkeETXCSn5M", "q": "Helper 系统如何解决双人卷轴问题？", "a": "分主角与配角，镜头只追主角，配角出画可用空间跳跃回来。", "t": 140}, {"cat": "N", "ep": "N-3 《星之卡比 超级豪华版》", "u": "N/03-PkeETXCSn5M.html", "vid": "PkeETXCSn5M", "q": "樱井为什么采用「合集」结构？", "a": "通关过长的游戏让人吃不消；短剧本各自决胜负、玩法各异，大体量也不易腻。", "t": 296}, {"cat": "N", "ep": "N-4 《任天堂明星大乱斗》（初代）", "u": "N/04-i3IOWaVDbx0.html", "vid": "i3IOWaVDbx0", "q": "樱井认为传统格斗游戏的「连招」有什么问题？", "a": "连招成立的过程中没有对手技术的介入，不是博弈；新手只能旁观挨打。", "t": 220}, {"cat": "N", "ep": "N-4 《任天堂明星大乱斗》（初代）", "u": "N/04-i3IOWaVDbx0.html", "vid": "i3IOWaVDbx0", "q": "「弹（Smash）输入」着眼于摇杆的什么特性？", "a": "输入完成所需的时间（快速倾倒），而非方向或倾斜深度。", "t": 297}, {"cat": "N", "ep": "N-4 《任天堂明星大乱斗》（初代）", "u": "N/04-i3IOWaVDbx0.html", "vid": "i3IOWaVDbx0", "q": "为什么要借用任天堂人气角色？", "a": "家用格斗一开始就有大量陌生主角，玩家难以产生亲近感；人气角色能解决这一点。", "t": 363}, {"cat": "N", "ep": "N-5 《任天堂明星大乱斗 DX》", "u": "N/05-vLRRNsAVl-8.html", "vid": "vLRRNsAVl-8", "q": "DX 的企划概念与樱井其他作品有什么不同？", "a": "其他多是「课题→解决」的逻辑型，DX 则很简单：让大乱斗飞跃式强化。", "t": 22}, {"cat": "N", "ep": "N-5 《任天堂明星大乱斗 DX》", "u": "N/05-vLRRNsAVl-8.html", "vid": "vLRRNsAVl-8", "q": "光盘开发给 DX 的音乐带来了什么？", "a": "可以流媒体播放实录音乐，采用了管弦乐编曲，进而引出 PRESS START 演奏会等合作。", "t": 121}, {"cat": "N", "ep": "N-5 《任天堂明星大乱斗 DX》", "u": "N/05-vLRRNsAVl-8.html", "vid": "vLRRNsAVl-8", "q": "为什么要花大力气做手办？", "a": "游戏内角色有限，而收集与解说任天堂历史角色是别处没有的乐趣；作品需要「别处没有」的特点。", "t": 176}, {"cat": "N", "ep": "N-6 《卡比的空中骑士》", "u": "N/06-bRDAYgRns4E.html", "vid": "bRDAYgRns4E", "q": "为什么卡比在这时做赛车游戏？", "a": "需要配合动画的游戏阵容，赛车比一部正统动作游戏更快完成。", "t": 56}, {"cat": "N", "ep": "N-6 《卡比的空中骑士》", "u": "N/06-bRDAYgRns4E.html", "vid": "bRDAYgRns4E", "q": "樱井如何让漂移更好玩？", "a": "在刹车开始漂移时同时蓄力，「吸住再放开」，而不只是让漂移更快。", "t": 128}, {"cat": "N", "ep": "N-6 《卡比的空中骑士》", "u": "N/06-bRDAYgRns4E.html", "vid": "bRDAYgRns4E", "q": "机体个性迥异的秘密是什么？", "a": "其实都是同一规格（仅星型/机车型之分），个性全靠参数差异。", "t": 304}, {"cat": "N", "ep": "N-7 《Meteos》", "u": "N/07-snHecpmPeJs.html", "vid": "snHecpmPeJs", "q": "樱井不擅长下落式方块游戏，为何仍能企划？", "a": "只要懂得游戏性产生的原理（风险与回报）就能企划。", "t": 110}, {"cat": "N", "ep": "N-7 《Meteos》", "u": "N/07-snHecpmPeJs.html", "vid": "snHecpmPeJs", "q": "Meteos 与传统下落式方块的根本差别是什么？", "a": "不是消除，而是把对齐的方块当推进力发射上去。", "t": 220}, {"cat": "N", "ep": "N-7 《Meteos》", "u": "N/07-snHecpmPeJs.html", "vid": "snHecpmPeJs", "q": "Meteos 的「星球」与一般选角色有何不同？", "a": "每颗星球的方块形状、场地宽度、发射特性和音乐全都不同，而不只是换必杀技。", "t": 352}, {"cat": "N", "ep": "N-8 《养成！甲虫王者 虫之王》", "u": "N/08-b3Fd8pBK0EA.html", "vid": "b3Fd8pBK0EA", "q": "原作街机《甲虫王者》的对战博弈来自什么？", "a": "石头剪刀布，每种虫擅长的手不同，出有利手还是反其道而行产生读心。", "t": 48}, {"cat": "N", "ep": "N-8 《养成！甲虫王者 虫之王》", "u": "N/08-b3Fd8pBK0EA.html", "vid": "b3Fd8pBK0EA", "q": "樱井为增强「养虫」的感觉做了什么情绪表现？", "a": "喂食不是一下吃光，而是慢慢咀嚼。", "t": 408}, {"cat": "N", "ep": "N-8 《养成！甲虫王者 虫之王》", "u": "N/08-b3Fd8pBK0EA.html", "vid": "b3Fd8pBK0EA", "q": "发售版出现了什么遗憾的问题？原因是什么？", "a": "肚子饿得比预想快；完成前没能用实机形态测试，可能与开发基板处理速度不同。", "t": 504}, {"cat": "N", "ep": "N-9 《任天堂明星大乱斗 X》", "u": "N/09-dXpFTHtlmCo.html", "vid": "dXpFTHtlmCo", "q": "为什么樱井认为大乱斗与联机相性不好？", "a": "大乱斗的乐趣是在小圈子里称王，联机竞争会打击信心；还必须完全同步通信，延迟会造成卡顿。", "t": 70}, {"cat": "N", "ep": "N-9 《任天堂明星大乱斗 X》", "u": "N/09-dXpFTHtlmCo.html", "vid": "dXpFTHtlmCo", "q": "「亚空的使者」为什么几乎全部内制？", "a": "规模几乎等于一款游戏，原想外包但找不到合适对象。", "t": 190}, {"cat": "N", "ep": "N-9 《任天堂明星大乱斗 X》", "u": "N/09-dXpFTHtlmCo.html", "vid": "dXpFTHtlmCo", "q": "X 为什么放慢了游戏速度？", "a": "DX 对休闲层太难，Wii 面向休闲层，且当时联机承受不了高操作密度。", "t": 333}, {"cat": "N", "ep": "N-10 《新·光神话 帕尔提娜之镜》", "u": "N/10-p-uwRfckTs4.html", "vid": "p-uwRfckTs4", "q": "为什么樱井把新作定位为「骨太、丰富」的游戏？", "a": "当时休闲路线由触摸世代等软件担当，所以反其道而行。", "t": 64}, {"cat": "N", "ep": "N-10 《新·光神话 帕尔提娜之镜》", "u": "N/10-p-uwRfckTs4.html", "vid": "p-uwRfckTs4", "q": "为什么先让玩家玩轨道射击的空战？", "a": "一开始就 TPS，躲、瞄、射同时出现，新手难以理解；空战更爽快，也可让音乐与场景同步。", "t": 256}, {"cat": "N", "ep": "N-10 《新·光神话 帕尔提娜之镜》", "u": "N/10-p-uwRfckTs4.html", "vid": "p-uwRfckTs4", "q": "为什么地面战敌人做得很大？", "a": "掌机屏幕小，瞄远处目标时只在极小面积游玩；杂兵也有皮特的 4~5 倍高。", "t": 320}, {"cat": "N", "ep": "N-11 《任天堂明星大乱斗 for 3DS / Wii U》", "u": "N/11-DeLrIXCOUw0.html", "vid": "DeLrIXCOUw0", "q": "樱井为什么选择 3DS 与 Wii U 双平台？", "a": "3DS 能随身但性能弱，Wii U 有 HD 却只是拼性能；想连接个人掌机与聚会主机的优点。", "t": 98}, {"cat": "N", "ep": "N-11 《任天堂明星大乱斗 for 3DS / Wii U》", "u": "N/11-DeLrIXCOUw0.html", "vid": "DeLrIXCOUw0", "q": "「大乱斗冒险」的规则来自哪款作品？", "a": "《卡比的空中骑士》的城市试炼。", "t": 224}, {"cat": "N", "ep": "N-11 《任天堂明星大乱斗 for 3DS / Wii U》", "u": "N/11-DeLrIXCOUw0.html", "vid": "DeLrIXCOUw0", "q": "4 代在开发体制上有什么划时代变化？", "a": "首次由樱井以外的人（数名企划）设定斗士参数。", "t": 406}, {"cat": "N", "ep": "N-12 《任天堂明星大乱斗 特别版》", "u": "N/12-RDrNWAHaKfI.html", "vid": "RDrNWAHaKfI", "q": "为什么特别版能实现「全员参战」？", "a": "4 代与特别版同在 BNS 开发，人员与环境可沿用，迁移较容易，且只差 7 名斗士。", "t": 75}, {"cat": "N", "ep": "N-12 《任天堂明星大乱斗 特别版》", "u": "N/12-RDrNWAHaKfI.html", "vid": "RDrNWAHaKfI", "q": "卡带容量减半带来什么问题？如何解决？", "a": "从 25GB 光盘变成约 16GB 卡带；音乐靠压缩技术缩到 4 代的 1/4。", "t": 345}, {"cat": "N", "ep": "N-12 《任天堂明星大乱斗 特别版》", "u": "N/12-RDrNWAHaKfI.html", "vid": "RDrNWAHaKfI", "q": "命魂与一般收集要素有何不同？", "a": "有「借用力量」的设定，获得它的战斗会让人联想原作，并可培养等级。", "t": 435}, {"cat": "N", "ep": "N-13 最终回特别篇：这个频道是怎么做出来的", "u": "N/13-_qPqBilhEtI.html", "vid": "_qPqBilhEtI", "q": "为什么樱井在开播前就写完了全部稿子？", "a": "一边做游戏一边运营频道本来不可能，必须事先定下所有内容（代价是不能按观众要求改）。", "t": 560}, {"cat": "N", "ep": "N-13 最终回特别篇：这个频道是怎么做出来的", "u": "N/13-_qPqBilhEtI.html", "vid": "_qPqBilhEtI", "q": "樱井为什么认为频道比讲课、书籍更适合传承知识？", "a": "讲课一次只能触达几百人、书读的人少；频道谁都能自由访问，并能作为资料留存。", "t": 392}, {"cat": "N", "ep": "N-13 最终回特别篇：这个频道是怎么做出来的", "u": "N/13-_qPqBilhEtI.html", "vid": "_qPqBilhEtI", "q": "频道总费用约多少？是否有收入？", "a": "约 9000 万日元（平均每集约 35 万日元），不变现、收入为零，他视之为捐赠。", "t": 2184}, {"cat": "extra", "ep": "extra-1 特别联动 #1：「太空侵略者之后的十年」（1978–1982）", "u": "extra/01-6QH1cQWmXlY.html", "vid": "6QH1cQWmXlY", "q": "这次联动企划的规则是什么？", "a": "两人同时玩同一作，有野玩到 Game Over，樱井一命即止，任一方失误就进下一作。", "t": 264}, {"cat": "extra", "ep": "extra-1 特别联动 #1：「太空侵略者之后的十年」（1978–1982）", "u": "extra/01-6QH1cQWmXlY.html", "vid": "6QH1cQWmXlY", "q": "《爆破彗星》的「矢量扫描」是怎样显示画面的？", "a": "像示波器一样用一束电子束直接在屏幕上画线（线框）。", "t": 594}, {"cat": "extra", "ep": "extra-1 特别联动 #1：「太空侵略者之后的十年」（1978–1982）", "u": "extra/01-6QH1cQWmXlY.html", "vid": "6QH1cQWmXlY", "q": "《Scramble》对后来的横版射击有什么重要意义？", "a": "横向卷轴，以及射击和炸弹两个键分开使用（另有燃料机制）。", "t": 957}, {"cat": "extra", "ep": "extra-2 特别联动 #2：「太空侵略者之后的十年」（1982–1985）", "u": "extra/02-ll01fYUI_iQ.html", "vid": "ll01fYUI_iQ", "q": "《铁板阵》在画面上有什么突破？", "a": "用灰阶绘制图像，渐变兼作抗锯齿，画面远超当时水准。", "t": 198}, {"cat": "extra", "ep": "extra-2 特别联动 #2：「太空侵略者之后的十年」（1982–1985）", "u": "extra/02-ll01fYUI_iQ.html", "vid": "ll01fYUI_iQ", "q": "《铁板阵》中打掉雷达有什么效果？", "a": "敌人表回退，游戏变简单（动态难度）。", "t": 264}, {"cat": "extra", "ep": "extra-2 特别联动 #2：「太空侵略者之后的十年」（1982–1985）", "u": "extra/02-ll01fYUI_iQ.html", "vid": "ll01fYUI_iQ", "q": "樱井指出游戏复杂化对街机有什么影响？", "a": "单局时间变长，街机的收益可能下降。", "t": 1387}, {"cat": "extra", "ep": "extra-3 特别联动 #3：「太空侵略者之后的十年」（1985–1987）", "u": "extra/03-zfh0oq-_nJQ.html", "vid": "zfh0oq-_nJQ", "q": "《梦幻空间》在横版射击里加入了什么独特要素？", "a": "购物系统（捡钱进商店买装备）。", "t": 297}, {"cat": "extra", "ep": "extra-3 特别联动 #3：「太空侵略者之后的十年」（1985–1987）", "u": "extra/03-zfh0oq-_nJQ.html", "vid": "zfh0oq-_nJQ", "q": "初代《街头霸王》的按键有什么特点？", "a": "压感按键，按得越用力攻击越强。", "t": 1155}, {"cat": "extra", "ep": "extra-3 特别联动 #3：「太空侵略者之后的十年」（1985–1987）", "u": "extra/03-zfh0oq-_nJQ.html", "vid": "zfh0oq-_nJQ", "q": "为什么 FC 版《拳无虚发》的主角变成了小人？", "a": "街机版的大角色缩放表现 FC 做不到。", "t": 1550}, {"cat": "extra", "ep": "extra-4 关于这个频道", "u": "extra/04-7M-DnOIeasA.html", "vid": "7M-DnOIeasA", "q": "频道的目标是什么？", "a": "把全世界游戏的乐趣稍微垫高一点。", "t": 27}, {"cat": "extra", "ep": "extra-4 关于这个频道", "u": "extra/04-7M-DnOIeasA.html", "vid": "7M-DnOIeasA", "q": "为什么频道不深入技术话题？", "a": "各开发环境差异大、保密事项多。", "t": 207}, {"cat": "extra", "ep": "extra-4 关于这个频道", "u": "extra/04-7M-DnOIeasA.html", "vid": "7M-DnOIeasA", "q": "樱井如何定位频道不变现、越做越亏这件事？", "a": "视为志愿活动和对游戏业的投资。", "t": 300}, {"cat": "extra", "ep": "extra-5 樱井政博的作品集", "u": "extra/05-frNXwWqZpkI.html", "vid": "frNXwWqZpkI", "q": "哪部作品首次加入复制能力？", "a": "1993 年的《星之卡比 梦之泉物语》。", "t": 14}, {"cat": "extra", "ep": "extra-5 樱井政博的作品集", "u": "extra/05-frNXwWqZpkI.html", "vid": "frNXwWqZpkI", "q": "首个支持联机的大乱斗是哪一部？", "a": "2008 年的《任天堂明星大乱斗 X》。", "t": 84}, {"cat": "extra", "ep": "extra-5 樱井政博的作品集", "u": "extra/05-frNXwWqZpkI.html", "vid": "frNXwWqZpkI", "q": "樱井在 Fami 通连载的专栏持续了多久？", "a": "近 20 年，是游戏开发者在周刊上连载最久的专栏。", "t": 49}, {"cat": "extra", "ep": "extra-6 频道介绍预告", "u": "extra/06-PUj0WzkmLf0.html", "vid": "PUj0WzkmLf0", "q": "这个频道的目标是什么？", "a": "把全世界游戏的乐趣稍微垫高一点。", "t": 6}, {"cat": "extra", "ep": "extra-6 频道介绍预告", "u": "extra/06-PUj0WzkmLf0.html", "vid": "PUj0WzkmLf0", "q": "节目会介绍哪两类内容？", "a": "怎样给游戏增加乐趣，以及构思方法。", "t": 12}, {"cat": "extra", "ep": "extra-6 频道介绍预告", "u": "extra/06-PUj0WzkmLf0.html", "vid": "PUj0WzkmLf0", "q": "樱井希望节目具有怎样的价值？", "a": "小众，但有别处没有的价值，多年后仍能作为参考。", "t": 18}];